INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C1','kor',6,1,'u5',1,'주장하는 글의 뜻 — 주장하는 글은 어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글로, 본 것을 그대로 전하는 글이나 마음을 적는 일기와 달리 「어떻게 하면 좋겠다」는 생각을 세워 남을 움직이려 한다',ARRAY['6국03-02 쓰기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C2','kor',6,1,'u5',1,'주장 · 이유 · 근거 — 주장은 어떤 문제에 대해 내세우는 글쓴이의 의견, 이유는 그렇게 주장하는 주관적인 까닭, 근거는 이유를 뒷받침하는 객관적인 자료이며, 주장만 있으면 우기는 말이 되고 근거가 없으면 혼자만의 생각에 머문다 — 본 것을 그대로 말한 문장은 주장이 아니라 문제 상황이다',ARRAY['6국03-02 쓰기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C3','kor',6,1,'u5',1,'주장하는 글을 쓰면 좋은 점 — 왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈되고 · 글로 남아 여러 사람을 움직이며 · 무엇이 문제인지 찾다 보면 둘레를 다시 보게 되고, 함께 쓰는 곳을 위한 글이라 쓰는 사람에게 책임이 따른다',ARRAY['6국03-02 쓰기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C4','kor',6,1,'u5',1,'문제마다 다른 주장 — 같은 학교 안이라도 무엇이 불편한지가 다르면 펼칠 주장도 달라지므로, 먼저 불편을 잡고 그 불편을 없앨 방법을 주장으로 세운다(사물함 칸이 없다 → 반마다 칸을 정하자)',ARRAY['6국03-02 쓰기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C5','kor',6,1,'u5',1,'쓰는 동안 점검하면 좋은 점 — 점검하지 않고 쓰면 다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰리지만, 쓰면서 점검하면 어긋난 부분을 그때그때 바로잡고 내 글을 한 걸음 떨어져 볼 수 있다',ARRAY['6국03-05 쓰기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C6','kor',6,1,'u5',1,'완성이 아니라 과정 — 이 단원은 흠 없는 글 한 편을 내놓는 시간이 아니라 쓰고 살펴보고 고치는 길을 익히는 시간이며, 처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿으므로 우선 한 줄부터 적어 본다',ARRAY['6국03-05 쓰기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C7','kor',6,1,'u5',2,'이유는 내 생각, 근거는 밖에서 — 이유는 「∼하기 때문이다」로 이어지는 내 주관적인 까닭이고, 근거는 조사 결과 · 기사 · 전문가의 말처럼 밖에서 가져와 누구나 확인할 수 있는 자료라서, 둘을 섞지 않는 것이 첫걸음이다',ARRAY['6국03-02 쓰기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C8','kor',6,1,'u5',2,'글에서 근거 찾기 — 글쓴이의 생각을 말한 문장과, 밖에서 가져와 출처를 붙인 자료를 갈라 보면 근거가 보이며, 설문 결과 · 직접 센 기록 · 선생님 면담처럼 누구나 확인할 수 있는 것이 근거다',ARRAY['6국03-02 쓰기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C9','kor',6,1,'u5',2,'이유의 타당성 — 이유를 볼 때에는 「주장과 이유가 관련 있는가」 · 「이유가 주장을 잘 설명하는가」를 물으며, 옳은 말이어도 주장과 이어지지 않으면(운동장을 나누자 ← 급식을 남기면 아깝다) 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C10','kor',6,1,'u5',2,'근거의 타당성 — 근거를 볼 때에는 「이유와 근거가 관련 있는가」 · 「근거의 출처를 믿을 수 있는가」 · 「이유를 뒷받침하는 객관적인 자료인가」를 묻고, 주장하는 글은 고개를 끄덕이며만 읽지 않고 「정말 그런가」를 물으며 읽는다',ARRAY['6국03-02 쓰기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C11','kor',6,1,'u5',2,'서론 — 서론은 문제 제기와 주장 밝히기를 하는 부분으로, 왜 이 글을 쓰게 되었는지 · 지금 무엇이 불편한지를 밝히고 글쓴이의 의견을 뚜렷이 드러내며, 이어서 무엇을 살펴볼지 한 줄로 안내하기도 한다',ARRAY['6국03-02 쓰기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C12','kor',6,1,'u5',2,'본론 — 본론은 이유와 그 이유를 뒷받침하는 근거로 주장을 펼쳐 나가는 부분으로, 이유는 「첫째 · 둘째」처럼 갈라 적으면 따라오기 쉽고, 하나의 이유에 근거가 여러 개 붙기도 한다',ARRAY['6국03-02 쓰기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C13','kor',6,1,'u5',2,'결론 — 결론은 앞에서 말한 이유를 짧게 모아 요약하고 주장을 한 번 더 강조하는 부분이며, 때로는 「이렇게 하면 어떻게 될 것이다」처럼 앞을 내다보는 내용을 담고, 처음 꺼내는 새 근거를 두는 부분이 아니다',ARRAY['6국03-02 쓰기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C14','kor',6,1,'u5',2,'중심 문장과 뒷받침 문장 — 중심 문장은 그 문단을 대표하는 한 문장이고 나머지는 그것을 받쳐 주는 뒷받침 문장이며, 본론 문단에서는 대개 「첫째, ∼하기 때문이다」가 중심 문장이고 수나 조사 결과가 든 문장은 대개 뒷받침 문장이다 — 중심 문장만 이어 읽으면 글의 뼈대가 드러난다',ARRAY['6국03-02 쓰기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C15','kor',6,1,'u5',2,'출처가 붙었다고 다 타당하지는 않다 — 출처는 자료가 어디서 왔는지를 알려 줄 뿐이라 「이 자료가 이 이유를 정말 뒷받침하는가」를 한 번 더 보아야 하며, 타당하다고 판단했다면 그렇게 판단한 까닭도 함께 말할 수 있어야 한다 — 「그냥 그럴 것 같아서」는 판단이 아니다',ARRAY['6국03-02 쓰기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C16','kor',6,1,'u5',4,'인용 자료의 갈래 — 주장하는 글에는 수로 나타낸 통계 자료 · 그 일을 잘 아는 사람의 전문가 의견 · 누구나 확인할 수 있는 기록이나 규칙인 사실 자료 · 실험이나 조사의 결과가 들어오며, 넷 다 내가 만든 것이 아니라 출처를 밝혀야 한다',ARRAY['6국03-02 쓰기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C17','kor',6,1,'u5',4,'인용과 표절 — 인용은 다른 사람의 말이나 글 · 자료를 가져와 내 글에서 쓰는 것으로 글을 튼튼하게 하지만, 출처를 밝히지 않거나 · 여러 글에서 조각조각 가져와 내 글인 척하거나 · 표나 사진을 출처 없이 쓰면 표절이 된다',ARRAY['6국03-02 쓰기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C18','kor',6,1,'u5',4,'출처를 밝히는 까닭 — 출처를 밝히면 만든 사람의 권리를 지키고 · 어디까지가 내 말인지 읽는 사람이 알 수 있고 · 원래 어떤 상황에서 나온 말인지 확인할 수 있어 뜻이 정확히 전해지며, 이것은 예의가 아니라 지켜야 할 약속이다',ARRAY['6국03-02 쓰기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C19','kor',6,1,'u5',4,'뜻을 비틀지 않기 — 인용에는 출처를 밝히는 일과 뜻을 왜곡하지 않는 일이 함께 붙으므로, 만든 사람이 하려던 말을 먼저 정확히 이해하고 그대로 살려 옮긴 뒤 출처를 붙이며, 출처를 적었어도 뜻을 과장하거나 비틀면 소용이 없다',ARRAY['6국03-02 쓰기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C20','kor',6,1,'u5',4,'저작물 · 저작자 · 저작권 — 저작물은 사람의 생각이나 감정을 표현한 창작물, 저작자는 그것을 만든 사람, 저작권은 저작자가 저작물에 대해 가지는 권리이며, 글 · 그림 · 사진 · 노래 · 영상이 모두 저작물이고 내가 쓴 주장하는 글도 저작물이라 나도 저작자다',ARRAY['6국03-02 쓰기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C21','kor',6,1,'u5',4,'출처의 네 가지 — 출처에는 누가 만들었는가(만든 사람이나 기관) · 언제 나왔는가(만든 시기) · 무엇인가(자료의 이름) · 어디에 실렸는가(실린 곳)가 들어가며, 네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다 — 하나라도 빠지면 「어딘가에서 봤다」와 다르지 않다',ARRAY['6국03-02 쓰기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C22','kor',6,1,'u5',4,'출처 적는 차례와 부호 — 출처를 적는 차례와 부호는 조금씩 다를 수 있지만 네 가지가 빠지지 않는 것이 중요하며, 표나 그래프를 가져올 때에는 제목과 만든 곳을 함께 적는다',ARRAY['6국03-02 쓰기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C23','kor',6,1,'u5',4,'믿을 수 있는 자료 — 공공 기관의 누리집 · 신문과 방송의 기사 · 학교가 낸 기록 · 내가 직접 한 조사와 면담은 믿을 만하고, 누가 썼는지 · 언제 올라왔는지 모르는 글이나 옮겨 적은 것만 있는 글은 한 번 더 확인하며, 직접 조사한 자료도 언제 · 누구에게 · 어디서 했는지 적어 두면 훌륭한 근거가 된다',ARRAY['6국03-02 쓰기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C24','kor',6,1,'u5',4,'많이 인용할수록 좋은 글이 아니다 — 자료를 잔뜩 붙이고 내 문장이 몇 줄뿐이면 글쓴이의 생각이 남지 않으므로, 내 이유를 세우고 그 이유에 꼭 맞는 자료를 붙이며, 주장과 분명한 관련이 없는 자료는 글을 무겁게만 한다',ARRAY['6국03-02 쓰기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C25','kor',6,1,'u5',4,'쓰기 윤리 — 글을 쓰는 사람은 확인되지 않은 사실을 쓰지 않았는가 · 인용할 때 출처를 정확히 밝혔는가 · 다른 사람을 헐뜯는 말을 쓰지 않았는가를 스스로 물으며, 글의 길이나 어려운 낱말의 수는 쓰기 윤리와 관계가 없다',ARRAY['6국03-02 쓰기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C26','kor',6,1,'u5',6,'주제 · 목적 · 대상 — 주장을 펼치기 전에 어떤 문제를 다룰지(주제) · 무엇을 이루고 싶은지(목적) · 누가 들을지(대상)를 정하면 할 말이 좁혀지며, 대상이 달라지면 주장 자체가 아니라 고르는 근거와 말하는 방법이 달라진다',ARRAY['6국03-02 쓰기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C27','kor',6,1,'u5',6,'주장은 명료하게 — 주장은 무엇을 하자는 것인지 한 가지로 읽혀야 하며(「비 오는 날 우산은 우산꽂이에 꽂읍시다」), 뜻이 흐리거나(「우산을 잘 관리합시다」) 두 가지로 읽히면(「복도를 더 좋게 만듭시다」) 아무리 좋은 근거를 붙여도 무엇을 설득당한 것인지 남지 않는다',ARRAY['6국03-02 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C28','kor',6,1,'u5',6,'이유 세우기 — 이유는 내 주관적인 까닭이지만 하나하나가 주장을 뒷받침해야 하므로, 주장이 이루어지면 사라지는 불편이라야 이유가 되고, 주장과 이어지지 않으면 사실이어도 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C29','kor',6,1,'u5',6,'근거를 찾는 길 — 직접 조사하기(설문 · 수 세기) · 여쭈어 보기(면담) · 기사와 책 찾기 · 공공 자료 보기 가운데 어느 길로 찾든, 이 자료가 그 이유를 정말 뒷받침하는가와 출처를 믿을 수 있는가를 보며, 이유가 말하는 낱말(넘어짐 · 잃어버림 · 미끄러움)이 든 자료를 짝짓는다',ARRAY['6국03-02 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C30','kor',6,1,'u5',6,'객관적인 자료 — 「나는 그렇게 느꼈다」나 「아마 다들 그럴 것이다」는 아무리 진심이어도 객관적인 자료가 아니며, 그 자리에 없던 사람도 나중에 찾아가 확인할 수 있어야 근거다',ARRAY['6국03-02 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C31','kor',6,1,'u5',6,'예상되는 반박에 대비하기 — 반대할 사람이 할 말을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일로, 못 들은 척하면 발표하는 그 자리에서 무너지지만 맞는 말을 받아들여 내용을 보태면 주장이 더 단단해진다',ARRAY['6국03-02 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C32','kor',6,1,'u5',6,'말로 먼저 펼쳐 보기 — 정리한 내용을 종이에 쓰기 전에 서론(문제와 주장) → 본론(이유마다 근거와 출처) → 결론(주장을 다시 힘주어) 차례로 소리 내어 말해 보면 쓰기 부담이 줄고, 말한 뒤 주장이 뚜렷했는지 · 출처를 밝혔는지 스스로 확인한다',ARRAY['6국03-02 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C33','kor',6,1,'u5',8,'주제를 고르는 두 조건 — 주장하는 글의 주제는 주장 · 이유 · 근거를 댈 수 있고 · 여러 사람에게 알릴 만한 문제여야 하며, 좋은 주제는 내가 실제로 겪은 일 가운데 우리가 바꿀 수 있는 일에서 나온다 — 나 혼자만의 일이나 근거를 찾을 수 없는 일은 글이 되지 않는다',ARRAY['6국03-05 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C34','kor',6,1,'u5',8,'계획하기 — 계획하기는 글을 쓸 준비를 하는 과정으로 글을 쓰는 목적 · 글의 주제 · 글을 읽을 사람을 정하며, 이것이 정해지면 어떤 말투로 쓸지와 어떤 근거를 고를지도 함께 정해진다',ARRAY['6국03-05 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C35','kor',6,1,'u5',8,'계획하기는 쓰기 전에만이 아니다 — 계획하기는 글을 쓰기 전에만 거치는 단계가 아니라, 쓰다가 읽을 사람이 달라져야 함을 알면 언제든 계획으로 되돌아가 고칠 수 있으며, 어긋난 계획을 붙들고 끝까지 가지 않는다',ARRAY['6국03-05 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C36','kor',6,1,'u5',8,'내용 생성하기 — 내용 생성하기는 쓸 거리를 떠올리고 자료를 모으는 과정으로, 핵심 낱말과 짧은 문장으로 떠오르는 것을 최대한 많이 꺼내 놓고(문장 다듬기는 나중), 찾은 자료의 출처를 그때 함께 적어 두어야 나중에 찾아 헤매지 않는다',ARRAY['6국03-05 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C37','kor',6,1,'u5',8,'내용 조직하기와 통일성 — 내용 조직하기는 떠올린 것을 서론 · 본론 · 결론 짜임에 맞게 늘어놓아 개요를 짜는 과정이며, 이때 글의 주제와 세부 내용이 서로 가깝게 이어지는 성질인 통일성을 살펴 옳은 말이라도 주제와 이어지지 않는 내용은 걸러 낸다',ARRAY['6국03-05 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C38','kor',6,1,'u5',8,'중심 문장부터 세우기 — 중심 문장이 없으면 문단이 어색해지지만 뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있으므로, 문단을 짤 때에는 「이 문단에서 하고 싶은 말」을 한 문장으로 먼저 세우고 그 아래에 근거와 설명을 붙인다',ARRAY['6국03-05 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C39','kor',6,1,'u5',8,'표현하기 — 표현하기는 조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 과정으로, 조직하기까지 낱말과 어구로 적었던 것을 문장으로 풀며, 읽을 사람이 이해할 수 있게 쓰고, 쓰다가 더 좋은 생각이 떠오르면 앞 단계로 돌아가 내용을 보태도 된다',ARRAY['6국03-05 쓰기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C40','kor',6,1,'u5',10,'점검하고 조정하기 — 점검은 다 쓴 뒤에 채점하는 일이 아니라 쓰는 도중에 내가 한 일을 되돌아보고 · 고칠 곳을 찾고 · 방향을 다시 잡는 일이며, 쓰기 과정 다섯 단계 한가운데에 놓여 어느 단계에서나 일어난다',ARRAY['6국03-05 쓰기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C41','kor',6,1,'u5',10,'쓰기 과정 다섯 단계 — 계획하기(목적 · 주제 · 읽을 사람 정하기) → 내용 생성하기(쓸 거리 떠올리고 자료 모으기) → 내용 조직하기(짜임에 맞게 늘어놓기) → 표현하기(문장으로 써 내려가기) → 고쳐쓰기(손볼 곳 찾아 고치기)',ARRAY['6국03-05 쓰기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C42','kor',6,1,'u5',10,'쓰기는 되돌아오는 성질을 지닌다 — 쓰기 과정은 앞으로만 가는 길이 아니라 쓰다가 근거가 약하면 내용 생성하기로, 조직하다가 계획으로 되돌아가는 것이 정상이며, 되돌아가는 것은 처음부터 다시 하는 실패가 아니라 쓰기의 성질이라 되돌아간 단계에서 글이 좋아진다',ARRAY['6국03-05 쓰기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C43','kor',6,1,'u5',10,'단계마다 점검할 것 — 계획하기는 목적 · 주제 · 읽을 사람을 정했는가, 내용 생성하기는 아는 것을 먼저 꺼내고 모자란 부분을 채울 자료를 찾았는가, 내용 조직하기는 짜임에 맞게 · 관련 있는 것끼리 묶어 늘어놓았는가, 표현하기는 짜임대로 문장이 되었고 읽을 사람이 알아듣는가를 묻는다 — 표현하기 점검의 잣대는 내가 아니라 읽을 사람이다',ARRAY['6국03-05 쓰기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C44','kor',6,1,'u5',10,'점검은 흠 잡기가 아니다 — 고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이고 이 단원이 재는 것은 완성된 글의 흠이 아니라 고쳐 가는 과정이므로, 다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 되고 한 군데만 고쳐도 점검을 한 것이다',ARRAY['6국03-05 쓰기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C45','kor',6,1,'u5',10,'고쳐쓰기의 세 수준 — 글 수준(주제가 드러나는가 · 짜임에 맞는가) · 문단 수준(중심 문장을 뒷받침 문장이 받치는가 · 문장끼리 이어지는가) · 문장과 낱말 수준(이해하기 쉬운가 · 띄어쓰기와 맞춤법)으로 나누어 고치며, 큰 것부터 손보면 헛수고가 줄지만 반드시 이 차례일 필요는 없어 눈에 띄는 곳부터 손대도 된다',ARRAY['6국03-05 쓰기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C46','kor',6,1,'u5',10,'띄어쓰기와 맞춤법 살피기 — 문장과 낱말 수준에서는 띄어쓰기가 바른가 · 맞춤법이 틀리지 않았는가 · 읽는 사람이 알기 쉬운 낱말을 골랐는가를 민감하게 살펴 바르게 고치며(「안돼요」 → 「안 돼요」), 이것도 글쓰기의 한 부분이다',ARRAY['6국04-06 문법']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C47','kor',6,1,'u5',12,'실천할 문제와 한 문장 주장 — 실천 활동의 문제는 우리 힘으로 바꿀 수 있고 근거를 댈 수 있어야 하며(비 오는 날이 많다 ✗), 주장은 「∼합시다 · ∼하지 맙시다」처럼 할 일이 드러나는 한 문장으로 만든다 — 길어질수록 흐려진다',ARRAY['6국03-02 쓰기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C48','kor',6,1,'u5',12,'주장을 펼치는 여러 방법과 근거 — 만화 · 공익 광고 · 표어 · 노랫말 바꾸기처럼 방법은 여러 가지지만 주장 · 이유 · 근거는 그대로 있어야 하며, 큰 글씨나 화려한 그림은 눈길을 끌 뿐 생각을 바꾸지 못하므로 어떤 방법이든 확인할 수 있는 근거 하나는 남긴다 — 사람을 움직이는 것은 목소리의 크기가 아니라 근거다',ARRAY['6국03-02 쓰기']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C49','kor',6,1,'u5',12,'네 칸 짜임 — 의견(하고 싶은 말 한 문장) → 까닭(왜 그렇게 여기는지) → 사례(실제로 있었던 일이나 조사 결과) → 제안(그러니 이렇게 하자)의 네 칸은 서론 · 본론 · 결론을 짧게 줄인 틀로, 표어 · 만화 · 짧은 알림 글처럼 길게 쓸 수 없는 곳에서 근거가 사라지는 것을 막는다',ARRAY['6국03-02 쓰기']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C50','kor',6,1,'u5',12,'말한 대로 해 보기 — 주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이라, 내가 알린 대로 내가 먼저 일주일 동안 해 보고 날마다 지켰는지 표시하고 무엇이 달라졌는지 적으며, 잘된 점과 아쉬운 점 한 줄이 다음 주장의 출발선이 된다',ARRAY['6국03-02 쓰기']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C51','kor',6,1,'u5',12,'흐린 출처 알아보기 — 「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 누가 · 언제 · 무엇을 · 어디에 실었는지가 빠진 출처는 읽는 사람이 확인할 길이 없어 근거가 아니라 짐작이나 떠도는 말이 되며, 만든 사람의 권리도 지키지 못한 것이 된다',ARRAY['6국03-02 쓰기']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u5-C52','kor',6,1,'u5',12,'비와 눈을 가리키는 우리말 — 같은 비 · 눈이라도 언제 · 얼마나 · 어떻게 내리느냐에 따라 여우비(볕이 난 날 잠깐 오다 그치는 비) · 먼지잼(먼지나 겨우 가라앉힐 만큼 조금 오는 비) · 밤비(밤에 내리는 비) · 도둑눈(밤사이 사람들 모르게 내린 눈) · 숫눈(쌓인 뒤 아무도 밟지 않은 눈) · 가루눈(가루처럼 잘게 내리는 눈)처럼 이름이 달라지며, 사전에서 「비」나 「눈」을 표제어로 잡고 딸린 말을 찾아 넓힌다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X01','kor',6,'u5',ARRAY['K6-1-u5-C1']::text[],'주장하는 글을 본 것을 그대로 전하는 글이나 마음만 적는 일기와 같은 글로 여긴다','설득할 목적이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X02','kor',6,'u5',ARRAY['K6-1-u5-C2','K6-1-u5-C4']::text[],'본 것을 그대로 말한 문제 상황 문장을 주장으로 고른다','어떻게 하자고 내세웠나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X03','kor',6,'u5',ARRAY['K6-1-u5-C7','K6-1-u5-C2']::text[],'이유와 근거를 섞어, 내 생각을 근거로 여기거나 밖에서 가져온 자료를 이유로 여긴다','내 생각 · 밖의 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X04','kor',6,'u5',ARRAY['K6-1-u5-C2']::text[],'주장만 힘주어 말하면 이유나 근거가 없어도 설득된다고 여긴다','주장만 있으면 우기는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X05','kor',6,'u5',ARRAY['K6-1-u5-C3']::text[],'주장하는 글을 쓰면 좋은 점을 모르거나, 나만을 위한 글이라 책임이 따르지 않는다고 여긴다','정돈 · 움직임 · 책임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X06','kor',6,'u5',ARRAY['K6-1-u5-C5','K6-1-u5-C40']::text[],'글쓰기를 점검하는 일을 글씨 · 줄 수 · 빠르기를 재는 일로 여긴다','무엇을 다시 보게 되나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X07','kor',6,'u5',ARRAY['K6-1-u5-C6','K6-1-u5-C44']::text[],'처음부터 흠 없는 완성 글을 내야 한다고 여겨 첫 문장부터 손이 멈춘다','과정을 익히는 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X08','kor',6,'u5',ARRAY['K6-1-u5-C9','K6-1-u5-C28']::text[],'옳은 말이기만 하면 주장과 이어지지 않아도 이유가 된다고 여긴다','주장과 관련 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X09','kor',6,'u5',ARRAY['K6-1-u5-C30','K6-1-u5-C8']::text[],'「나는 그렇게 느꼈다」 · 「아마 다들 그럴 것이다」 같은 느낌이나 짐작을 근거로 쓴다','남이 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X10','kor',6,'u5',ARRAY['K6-1-u5-C11','K6-1-u5-C12','K6-1-u5-C13']::text[],'서론 · 본론 · 결론이 맡은 몫을 헷갈린다(서론에 근거만 잔뜩 · 본론에 문제 제기만)','제기 · 펼치기 · 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X11','kor',6,'u5',ARRAY['K6-1-u5-C13']::text[],'결론에서 처음 꺼내는 새로운 근거를 내놓아야 한다고 여긴다','결론은 모으고 힘주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X12','kor',6,'u5',ARRAY['K6-1-u5-C12']::text[],'하나의 이유에는 근거가 꼭 하나만 붙어야 한다고 여긴다','여러 개 붙기도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X13','kor',6,'u5',ARRAY['K6-1-u5-C14','K6-1-u5-C38']::text[],'수나 조사 결과가 든 뒷받침 문장을 그 문단의 중심 문장으로 고른다','문단을 한 문장으로 줄이면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X14','kor',6,'u5',ARRAY['K6-1-u5-C15']::text[],'출처가 붙어 있기만 하면 그 근거는 무조건 타당하다고 여긴다','이 이유를 정말 받치나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X15','kor',6,'u5',ARRAY['K6-1-u5-C15','K6-1-u5-C10']::text[],'타당한지를 까닭 없이 「그냥 그럴 것 같아서」로 판단한다','판단에도 까닭을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X16','kor',6,'u5',ARRAY['K6-1-u5-C16','K6-1-u5-C17']::text[],'남이 만든 표 · 말 · 문장도 내 글에 넣으면 출처를 밝히지 않아도 된다고 여기거나, 내가 세운 주장에도 출처가 필요하다고 여긴다','내가 만들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X17','kor',6,'u5',ARRAY['K6-1-u5-C17']::text[],'여러 글에서 조각조각 가져와 이어 붙이면 내 글이 된다고 여긴다','조각 이어 붙이기도 표절') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X18','kor',6,'u5',ARRAY['K6-1-u5-C18']::text[],'출처를 밝히는 일을 해도 되고 안 해도 되는 예의 정도로 여긴다','지켜야 할 약속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X19','kor',6,'u5',ARRAY['K6-1-u5-C19']::text[],'출처만 적으면 원래 뜻을 내 주장에 맞게 세게 바꾸거나 비틀어도 된다고 여긴다','뜻을 그대로 살려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X20','kor',6,'u5',ARRAY['K6-1-u5-C20']::text[],'저작물 · 저작자 · 저작권을 헷갈리거나, 학생이 쓴 글은 저작물이 아니라고 여긴다','물건 · 사람 · 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X21','kor',6,'u5',ARRAY['K6-1-u5-C21']::text[],'출처의 네 가지 가운데 하나쯤 빠져도 읽는 사람이 찾아갈 수 있다고 여긴다','네 가지가 다 있어야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X22','kor',6,'u5',ARRAY['K6-1-u5-C22']::text[],'출처를 적는 차례와 부호는 하나로 정해져 있어 조금만 달라도 틀린다고 여기거나, 표를 가져올 때 제목과 만든 곳을 빠뜨린다','차례보다 네 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X23','kor',6,'u5',ARRAY['K6-1-u5-C23']::text[],'누가 썼는지 · 언제 올라왔는지 모르는 글을 믿을 만한 자료로 여기거나, 직접 한 조사는 근거가 될 수 없다고 여긴다','찾아가 확인할 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X24','kor',6,'u5',ARRAY['K6-1-u5-C24']::text[],'자료를 많이 인용할수록 좋은 글이 된다고 여긴다','내 생각이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X25','kor',6,'u5',ARRAY['K6-1-u5-C25']::text[],'쓰기 윤리를 글의 길이나 어려운 낱말 수로 여기거나, 남을 헐뜯는 말은 상관없다고 여긴다','참 · 출처 · 헐뜯지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X26','kor',6,'u5',ARRAY['K6-1-u5-C26']::text[],'듣는 사람이 달라지면 주장 자체를 바꿔야 한다고 여기거나, 대상을 생각하지 않고 근거와 말투를 고른다','바뀌는 것은 전하는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X27','kor',6,'u5',ARRAY['K6-1-u5-C27','K6-1-u5-C47']::text[],'뜻이 흐리거나 두 가지로 읽히는 주장(「복도를 더 좋게 만듭시다」)도 괜찮다고 여긴다','한 가지로 읽히나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X28','kor',6,'u5',ARRAY['K6-1-u5-C31']::text[],'반대하는 말은 못 들은 척해야 내 주장이 흔들리지 않는다고 여긴다','미리 떠올리면 단단해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X29','kor',6,'u5',ARRAY['K6-1-u5-C33']::text[],'나 혼자만의 일이나 근거를 찾을 수 없는 일을 주장하는 글의 주제로 고른다','근거 · 여럿에게 알릴 만함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X30','kor',6,'u5',ARRAY['K6-1-u5-C35']::text[],'계획은 이미 세웠으니 쓰는 도중에 계획으로 되돌아가면 안 된다고 여긴다','언제든 되돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X31','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'내용 생성하기 단계에서 문장부터 다듬느라 떠오르는 것을 꺼내 놓지 못한다','핵심 낱말로 많이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X32','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'자료를 찾을 때 출처는 나중에 적으면 된다고 미뤄 둔다','지금 적어 두어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X33','kor',6,'u5',ARRAY['K6-1-u5-C37']::text[],'옳은 말이면 글의 주제와 이어지지 않아도 넣어도 된다고 여긴다(통일성)','주제와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X34','kor',6,'u5',ARRAY['K6-1-u5-C38']::text[],'중심 문장 없이 뒷받침 문장만 늘어놓아 문단을 짠다','하고 싶은 말 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X35','kor',6,'u5',ARRAY['K6-1-u5-C39','K6-1-u5-C43']::text[],'표현하기를 점검할 때 내가 읽어 매끄러우면 된다고 여겨 나만 아는 줄임말을 그대로 둔다','잣대는 읽을 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X36','kor',6,'u5',ARRAY['K6-1-u5-C40']::text[],'점검을 글을 다 쓴 뒤에 한 번 채점하는 일로 여긴다','쓰는 도중에 방향을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X37','kor',6,'u5',ARRAY['K6-1-u5-C41']::text[],'쓰기 과정 다섯 단계의 이름과 하는 일을 헷갈린다','정하기 · 모으기 · 늘어놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X38','kor',6,'u5',ARRAY['K6-1-u5-C42']::text[],'앞 단계로 되돌아가면 처음부터 다시 하는 실패라고 여긴다','쓰기의 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X39','kor',6,'u5',ARRAY['K6-1-u5-C43']::text[],'점검 질문을 엉뚱한 단계에 붙인다(계획하기에서 띄어쓰기를 묻는 식)','그 단계에서 한 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X40','kor',6,'u5',ARRAY['K6-1-u5-C44']::text[],'고칠 곳이 많으면 망한 글이라 여기거나, 고치려면 반드시 새 종이에 전부 다시 써야 한다고 여긴다','쪽지 하나도 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X41','kor',6,'u5',ARRAY['K6-1-u5-C45']::text[],'고쳐쓰기 세 수준을 헷갈리거나, 반드시 맞춤법부터 또는 반드시 정해진 차례로만 고쳐야 한다고 여긴다','크기를 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X42','kor',6,'u5',ARRAY['K6-1-u5-C46']::text[],'띄어쓰기와 맞춤법은 글쓰기와 상관없는 일이라 살피지 않아도 된다고 여긴다','낱말도 민감하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X43','kor',6,'u5',ARRAY['K6-1-u5-C47']::text[],'우리 힘으로 바꿀 수 없는 문제(날씨 · 방학 길이)를 실천 활동의 문제로 고른다','우리가 바꿀 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X44','kor',6,'u5',ARRAY['K6-1-u5-C48']::text[],'큰 글씨나 화려한 그림처럼 눈에 띄기만 하면 근거가 없어도 설득된다고 여긴다','근거 하나는 남겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X45','kor',6,'u5',ARRAY['K6-1-u5-C49']::text[],'네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 차례나 칸마다 들어갈 것을 헷갈린다','꺼내고 · 왜 · 실제 · 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X46','kor',6,'u5',ARRAY['K6-1-u5-C50']::text[],'주장을 알리고 나면 끝이라 여겨 내가 먼저 해 보는 일은 하지 않아도 된다고 여긴다','마지막 걸음은 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X47','kor',6,'u5',ARRAY['K6-1-u5-C51','K6-1-u5-C21']::text[],'「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 흐린 말도 출처를 밝힌 것으로 여긴다','누가 · 언제 · 무엇 · 어디') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u5-X48','kor',6,'u5',ARRAY['K6-1-u5-C52']::text[],'비와 눈을 가리키는 우리말의 뜻을 헷갈리거나, 우리말에는 비와 눈을 갈라 부르는 말이 없다고 여긴다','언제 · 얼마나 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',1,'mc','auto','「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X01']::text[],false,'{"seq":1,"concept":"K6-1-u5-C1","difficulty":1,"kind":"mc","stem":"「주장하는 글」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글","correct":true},{"t":"본 것을 있는 그대로 전하려고 쓰는 글","mis":"K6-1-u5-X01"},{"t":"그날 있었던 일과 마음을 적어 두는 글","mis":"K6-1-u5-X01"},{"t":"재미있는 일을 꾸며 지어낸 글","mis":"K6-1-u5-X01"}],"explanation":["본 것만 전하는 글이 아니에요.","일기와도 달라요.","다른 사람을 설득하려고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C2","difficulty":1,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"주장","r":"어떤 문제에 대해 내세우는 글쓴이의 의견"},{"l":"이유","r":"그렇게 주장하는 주관적인 까닭"},{"l":"근거","r":"이유를 뒷받침하는 객관적인 자료"}],"mis":"K6-1-u5-X03","explanation":["주장은 의견이에요.","이유는 내 까닭이에요.","근거는 밖에서 가져온 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',1,'mc','auto','예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":3,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"예찬이와 규리의 대화에서 주장에 해당하는 말은 어느 것인가요?","options":[{"t":"반마다 칸을 나누어 쓰면 좋겠어","correct":true},{"t":"신발주머니가 바닥에 쏟아져 있잖아","mis":"K6-1-u5-X02"},{"t":"체육관 사물함이 늘 뒤엉켜 있어","mis":"K6-1-u5-X02"},{"t":"칸이 정해져 있지 않아서 그래","mis":"K6-1-u5-X02"}],"explanation":["본 것을 그대로 말했어요.","문제 상황을 말했어요.","어떻게 하자고 내세운 말이 주장이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C6',1,'ox','auto','이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":4,"concept":"K6-1-u5-C6","difficulty":1,"kind":"ox","stem":"이 단원은 흠 없는 글 한 편을 완성해 내놓는 것이 가장 중요한 시간이에요.","answer":"X","reason_options":[{"t":"쓰고 살펴보고 고치는 글쓰기 과정을 익히는 시간이기 때문에","correct":true},{"t":"좋은 글은 처음부터 흠 없이 써야 하기 때문에","mis":"K6-1-u5-X07"}],"mis":"K6-1-u5-X07","explanation":["완성이 목표가 아니에요.","과정을 살펴보는 단원이에요.","우선 한 줄부터 적어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C3',2,'mc','auto','주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X04','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C3","difficulty":2,"kind":"mc","stem":"주장하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈된다","correct":true},{"t":"나만 보는 글이라 아무렇게나 써도 된다","mis":"K6-1-u5-X05"},{"t":"이유 없이 주장만 크게 말해도 남이 따른다","mis":"K6-1-u5-X04"},{"t":"글씨를 바르게 쓰는 연습이 된다","mis":"K6-1-u5-X06"}],"explanation":["함께 쓰는 곳을 위한 글이라 책임이 따라요.","주장만으로는 우기는 말이 돼요.","생각이 정돈되고 남을 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C4',2,'match','auto','문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u5-C4","difficulty":2,"kind":"match","stem":"문제 상황과 그때 펼칠 만한 주장을 알맞게 이으세요.","pairs":[{"l":"체육관 사물함에 칸이 없다","r":"반마다 쓸 칸을 정해 둡시다"},{"l":"빌린 책이 제때 돌아오지 않는다","r":"반납일을 지켜 돌려줍시다"},{"l":"비 오는 날 우산이 복도에 흩어진다","r":"우산은 우산꽂이에 모아 둡시다"}],"mis":"K6-1-u5-X02","explanation":["불편을 먼저 잡아요.","불편을 없앨 방법이 주장이에요.","문제가 다르면 주장도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',2,'mc','auto','글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C5","difficulty":2,"kind":"mc","stem":"글을 쓰는 과정을 점검하면 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"보완할 점을 찾아 다시 조정할 수 있다","correct":true},{"t":"글을 몇 줄 썼는지 정확히 셀 수 있다","mis":"K6-1-u5-X06"},{"t":"글을 더 빨리 끝낼 수 있다","mis":"K6-1-u5-X06"},{"t":"글씨가 얼마나 반듯한지 잴 수 있다","mis":"K6-1-u5-X06"}],"explanation":["줄 수를 재는 일이 아니에요.","빠르기를 재는 일도 아니에요.","내 글을 한 걸음 떨어져 보게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C2',2,'ox','auto','이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.',ARRAY['K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C2","difficulty":2,"kind":"ox","stem":"이유는 있는데 근거가 없으면 글쓴이 혼자만의 생각에 머물러요.","answer":"O","reason_options":[{"t":"누구나 확인할 수 있는 자료가 이유를 받쳐 주지 않기 때문에","correct":true},{"t":"이유만 있으면 누구나 그대로 믿기 때문에","mis":"K6-1-u5-X04"}],"mis":"K6-1-u5-X04","explanation":["이유는 내 까닭이에요.","근거가 받쳐 주어야 해요.","셋이 함께 다녀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C1',2,'mc','auto','규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X06','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":9,"concept":"K6-1-u5-C1","difficulty":2,"kind":"mc","stem":"규리가 「왜 그래야 하는지도 함께 적어야겠다」고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그냥 하자고만 하면 다른 사람이 따르지 않아 설득하기 어렵기 때문이다","correct":true},{"t":"글을 길게 써야 상을 받을 수 있기 때문이다","mis":"K6-1-u5-X06"},{"t":"본 것을 빠짐없이 전하는 글이기 때문이다","mis":"K6-1-u5-X01"},{"t":"주장만 쓰면 충분하기 때문이다","mis":"K6-1-u5-X04"}],"explanation":["길이를 늘리려는 것이 아니에요.","본 것만 전하는 글이 아니에요.","까닭이 있어야 설득돼요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_basic#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_basic','lesson_basic','K6-1-u5-C5',3,'mc','auto','점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06']::text[],false,'{"seq":10,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"점검하지 않고 끝까지 쓴 뒤에 생기기 쉬운 일로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰린다","correct":true},{"t":"고칠 곳이 하나도 생기지 않는다","mis":"K6-1-u5-X36"},{"t":"글씨가 저절로 반듯해진다","mis":"K6-1-u5-X06"},{"t":"어긋난 부분을 그때그때 바로잡게 된다","mis":"K6-1-u5-X36"}],"explanation":["고칠 곳은 늘 생겨요.","글씨와는 관계없어요.","쓰면서 점검해야 그때그때 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#1','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',2,'mc','auto','대화에서 주장이 아닌 것은 어느 것인가요?',ARRAY['K6-1-u5-X02']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":2,"kind":"mc","stem":"대화에서 주장이 아닌 것은 어느 것인가요?","options":[{"t":"수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아","correct":true},{"t":"반마다 칸을 나누어 쓰면 좋겠어","mis":"K6-1-u5-X02"},{"t":"글로 써서 다른 반에도 알리자","mis":"K6-1-u5-X02"},{"t":"왜 그래야 하는지도 함께 적자","mis":"K6-1-u5-X02"}],"explanation":["칸을 나누자는 것은 주장이에요.","알리자는 것도 내세운 말이에요.","본 것을 그대로 말한 문장은 문제 상황이에요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#2','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',2,'ox','auto','주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.',ARRAY['K6-1-u5-X05']::text[],false,'{"seq":2,"concept":"K6-1-u5-C3","difficulty":2,"kind":"ox","stem":"주장하는 글은 함께 쓰는 곳을 위한 글이라서 쓰는 사람에게 책임이 따라요.","answer":"O","reason_options":[{"t":"여러 사람에게 닿아 생각과 생활을 움직이는 글이기 때문에","correct":true},{"t":"나 혼자만 읽고 덮는 글이기 때문에","mis":"K6-1-u5-X05"}],"mis":"K6-1-u5-X05","explanation":["여러 사람에게 가 닿아요.","나만을 위한 글이 아니에요.","그래서 책임이 따라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#3','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'error','auto','단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?',ARRAY['K6-1-u5-X07']::text[],false,'{"seq":3,"concept":"K6-1-u5-C6","difficulty":3,"kind":"error","stem":"단원을 시작하며 한 다짐이에요. 알맞지 않은 다짐은 누구의 것인가요?","options":[{"t":"예찬 — 「한 번에 흠 없는 글을 써내야 해. 못 쓰면 어떡하지.」","correct":true,"mis_target":"K6-1-u5-X07"},{"t":"규리 — 「우선 한 줄부터 써 놓고 살펴보며 다듬을래.」","mis":"K6-1-u5-X07"},{"t":"슬아 — 「쓰고 살펴보고 고치는 길을 익혀 볼게.」","mis":"K6-1-u5-X07"}],"explanation":["규리는 바르게 다짐했어요.","슬아도 바르게 다짐했어요.","처음부터 완성할 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#4','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C4',3,'mc','auto','「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X08','K6-1-u5-X27']::text[],false,'{"seq":4,"concept":"K6-1-u5-C4","difficulty":3,"kind":"mc","stem":"「급식실 앞에서 줄이 엉켜 서로 밀친다」는 문제에 알맞은 주장은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 섭시다","correct":true},{"t":"급식실 앞이 몹시 북적입니다","mis":"K6-1-u5-X02"},{"t":"반찬을 골고루 먹읍시다","mis":"K6-1-u5-X08"},{"t":"학교 생활을 더 좋게 합시다","mis":"K6-1-u5-X27"}],"explanation":["문제 상황을 다시 말했어요.","줄과 이어지지 않아요.","불편을 없앨 방법이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#5','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',3,'mc','auto','「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?',ARRAY['K6-1-u5-X03','K6-1-u5-X01','K6-1-u5-X04']::text[],false,'{"seq":5,"concept":"K6-1-u5-C2","difficulty":3,"kind":"mc","stem":"「주장만 있고 이유가 없는 말」은 어떤 말이 되나요?","options":[{"t":"왜 그래야 하는지 밝히지 않고 우기는 말","correct":true},{"t":"누구나 확인할 수 있는 객관적인 말","mis":"K6-1-u5-X03"},{"t":"본 것을 정확하게 전하는 말","mis":"K6-1-u5-X01"},{"t":"저절로 남을 설득하는 말","mis":"K6-1-u5-X04"}],"explanation":["객관적인 자료는 근거예요.","본 것을 전하는 말과 달라요.","이유가 있어야 설득돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#6','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C5',3,'mc','auto','쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06','K6-1-u5-X38']::text[],false,'{"seq":6,"concept":"K6-1-u5-C5","difficulty":3,"kind":"mc","stem":"쓰는 도중에 「이 이유가 주장과 맞나?」를 물어보면 좋아지는 점은 어느 것인가요?","options":[{"t":"어긋난 부분을 그때그때 바로잡을 수 있다","correct":true},{"t":"다 쓰고 나서 한꺼번에 고칠 수 있다","mis":"K6-1-u5-X36"},{"t":"줄 수가 늘어 글이 풍성해진다","mis":"K6-1-u5-X06"},{"t":"이유를 더는 고치지 않아도 된다","mis":"K6-1-u5-X38"}],"explanation":["몰아서 고치면 손대기 어려워요.","줄 수와는 관계없어요.","그때그때 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#7','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',3,'mc','auto','「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X07','K6-1-u5-X38','K6-1-u5-X06']::text[],false,'{"seq":7,"concept":"K6-1-u5-C6","difficulty":3,"kind":"mc","stem":"「처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"좋은 글은 써 놓고 살펴보며 고쳐 가는 과정에서 만들어진다","correct":true},{"t":"타고난 사람만 좋은 글을 쓴다","mis":"K6-1-u5-X07"},{"t":"한 번 쓴 글은 고치지 않는 것이 좋다","mis":"K6-1-u5-X38"},{"t":"살펴보는 일은 글씨를 고치는 일이다","mis":"K6-1-u5-X06"}],"explanation":["누구나 고쳐 가며 써요.","고치는 것이 과정이에요.","살펴보는 것은 내용과 짜임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#8','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C3',4,'mc','auto','「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u5-X05','K6-1-u5-X06','K6-1-u5-X04']::text[],false,'{"seq":8,"concept":"K6-1-u5-C3","difficulty":4,"kind":"mc","stem":"「주장하는 글을 쓰다 보면 둘레를 다시 보게 된다」는 말을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"사물함 문제를 쓰려고 살피다가 그동안 지나쳤던 체육관 신발장 문제도 눈에 들어왔다","correct":true},{"t":"글을 쓰느라 둘레에 무슨 일이 있는지 신경 쓰지 못했다","mis":"K6-1-u5-X05"},{"t":"글씨를 쓰려고 책상 둘레를 정리했다","mis":"K6-1-u5-X06"},{"t":"주장만 크게 말하자 친구들이 모두 따라왔다","mis":"K6-1-u5-X04"}],"explanation":["오히려 둘레가 보여요.","책상 정리 이야기가 아니에요.","문제를 찾다 보면 지나친 일이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#9','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C2',4,'essay','teacher','예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C2","difficulty":4,"kind":"essay","stem":"예찬이와 규리가 쓸 글의 주장을 한 문장으로 쓰고, 이유 하나와 그 이유를 받쳐 줄 근거로 쓸 만한 자료를 하나씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 체육관 사물함을 반마다 칸을 나누어 씁시다. 이유 — 칸이 정해지면 신발주머니가 바닥에 쏟아지는 일이 줄기 때문이다. 근거 — 일주일 동안 수업이 끝난 뒤 바닥에 떨어진 신발주머니 수를 세어 적은 기록.","scoring_points":["주장을 할 일이 드러나는 한 문장으로 썼는가","주장과 이어진 이유를 썼는가","누구나 확인할 수 있는 자료를 근거로 들었는가"]},"explanation":["하자는 말로 주장을 세워요.","왜 그런지 이유를 붙여요.","확인할 수 있는 자료를 골라요."],"asset":{"type":"speech","turns":[{"who":"예찬","text":"체육관 사물함이 늘 뒤엉켜 있어. 수업이 끝나면 신발주머니가 바닥에 쏟아져 있잖아."},{"who":"규리","text":"칸이 정해져 있지 않아서 그래. 반마다 칸을 나누어 쓰면 좋겠어."},{"who":"예찬","text":"그 생각을 우리끼리만 말하면 바뀌지 않아. 글로 써서 다른 반에도 알리자."},{"who":"규리","text":"그럼 왜 그래야 하는지도 함께 적어야겠다. 그냥 하자고만 하면 아무도 안 들을 테니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L01_challenge#10','kor',6,1,'u5','L01','g6_1_kor_u5_L01_challenge','lesson_challenge','K6-1-u5-C6',4,'essay','teacher','글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C6","difficulty":4,"kind":"essay","stem":"글쓰기를 앞두고 「못 쓰면 어떡하지」 하고 걱정하는 친구에게, 이 단원에서 배우는 것이 무엇인지 알려 주며 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이 단원은 처음부터 흠 없는 글을 내는 시간이 아니라 쓰고 살펴보고 고치는 과정을 익히는 시간이야. 처음부터 잘 쓴 사람보다 다시 살펴본 사람이 좋은 글에 닿는대. 그러니 우선 한 줄부터 써 놓고 같이 고쳐 가 보자.","scoring_points":["완성이 아니라 과정을 익히는 단원임을 썼는가","살펴보고 고치는 일의 가치를 썼는가","부담을 덜어 주는 말을 썼는가"]},"explanation":["걱정하는 마음을 떠올려요.","이 단원이 배우는 것을 써요.","해 볼 수 있는 첫걸음을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#1','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C7',1,'mc','auto','이유와 근거를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C7","difficulty":1,"kind":"mc","stem":"이유와 근거를 바르게 가른 것은 어느 것인가요?","options":[{"t":"이유는 내 생각이고, 근거는 밖에서 가져온 자료이다","correct":true},{"t":"이유는 밖에서 가져온 자료이고, 근거는 내 생각이다","mis":"K6-1-u5-X03"},{"t":"이유와 근거는 같은 말이다","mis":"K6-1-u5-X03"},{"t":"근거는 주장을 다시 한번 말한 것이다","mis":"K6-1-u5-X03"}],"explanation":["거꾸로 말했어요.","둘은 섞지 않아요.","내 까닭과 밖의 자료를 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#2','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C8',1,'mc','auto','「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X02','K6-1-u5-X09']::text[],false,'{"seq":2,"concept":"K6-1-u5-C8","difficulty":1,"kind":"mc","stem":"「점심시간 운동장을 나누어 씁시다」에서 근거에 해당하는 것은 어느 것인가요?","options":[{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔했다는 설문 결과","correct":true},{"t":"나누어 쓰면 더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X03"},{"t":"운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X02"},{"t":"뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X09"}],"explanation":["「때문이다」는 이유예요.","하자는 말은 주장이에요.","출처가 붙은 조사 결과가 근거예요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#3','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C11',1,'ox','auto','서론에서는 문제를 제기하고 주장을 밝혀요.',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":3,"concept":"K6-1-u5-C11","difficulty":1,"kind":"ox","stem":"서론에서는 문제를 제기하고 주장을 밝혀요.","answer":"O","reason_options":[{"t":"왜 이 글을 쓰게 되었는지와 글쓴이의 의견을 먼저 드러내는 부분이기 때문에","correct":true},{"t":"이유와 근거를 모두 늘어놓는 부분이기 때문에","mis":"K6-1-u5-X10"}],"mis":"K6-1-u5-X10","explanation":["서론은 글의 앞부분이에요.","문제와 주장을 먼저 밝혀요.","이유와 근거는 본론에서 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#4','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',1,'match','auto','글의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u5-C12","difficulty":1,"kind":"match","stem":"글의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"서론","r":"문제를 제기하고 주장을 밝힌다"},{"l":"본론","r":"이유와 근거로 주장을 펼친다"},{"l":"결론","r":"요약하고 다시 한번 강조한다"}],"mis":"K6-1-u5-X10","explanation":["서론은 꺼내요.","본론은 펼쳐요.","결론은 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#5','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C9',2,'mc','auto','「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":5,"concept":"K6-1-u5-C9","difficulty":2,"kind":"mc","stem":"「운동장을 나누어 쓰자」는 주장과 관련이 없는 이유는 어느 것인가요?","options":[{"t":"급식을 남기면 아깝기 때문이다","correct":true},{"t":"더 안전하게 놀 수 있기 때문이다","mis":"K6-1-u5-X08"},{"t":"놀 곳을 두고 벌어지는 다툼이 줄어들기 때문이다","mis":"K6-1-u5-X08"},{"t":"하려던 놀이를 끝까지 할 수 있기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["안전은 운동장과 이어져요.","다툼도 이어져요.","급식은 운동장을 나누는 일과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#6','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C14',2,'mc','auto','②문단의 중심 문장은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X10']::text[],false,'{"seq":6,"concept":"K6-1-u5-C14","difficulty":2,"kind":"mc","stem":"②문단의 중심 문장은 어느 것인가요?","options":[{"t":"첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다","correct":true},{"t":"스물다섯 명 가운데 열여덟 명이 부딪힐 뻔한 적이 있다고 답했다","mis":"K6-1-u5-X13"},{"t":"넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다","mis":"K6-1-u5-X13"},{"t":"점심시간 운동장을 학년에 따라 나누어 써야 한다","mis":"K6-1-u5-X10"}],"explanation":["수가 든 문장은 받쳐 주는 쪽이에요.","이 문장도 뒷받침 문장이에요.","문단 전체를 한 문장으로 줄여요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#7','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C12',2,'ox','auto','본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.',ARRAY['K6-1-u5-X12']::text[],false,'{"seq":7,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"본론에서 하나의 이유에는 근거가 꼭 하나만 붙어야 해요.","answer":"X","reason_options":[{"t":"하나의 이유에 근거가 여러 개 붙기도 하기 때문에","correct":true},{"t":"근거가 둘이면 이유가 흐려지기 때문에","mis":"K6-1-u5-X12"}],"mis":"K6-1-u5-X12","explanation":["근거 수는 정해져 있지 않아요.","여러 근거가 받치기도 해요.","이유와 이어지는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#8','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C13',2,'mc','auto','⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":8,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"⑤문단이 결론인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 가지 까닭을 모아 말하고 주장을 다시 강조했기 때문이다","correct":true},{"t":"처음 꺼내는 새 근거를 내놓았기 때문이다","mis":"K6-1-u5-X11"},{"t":"문제를 처음으로 제기했기 때문이다","mis":"K6-1-u5-X10"},{"t":"설문 결과를 자세히 밝혔기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["결론은 새 근거를 꺼내지 않아요.","문제 제기는 서론이에요.","모으고 다시 힘주는 부분이에요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#9','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C10',2,'mc','auto','근거가 타당한지 판단할 때 던질 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X09']::text[],false,'{"seq":9,"concept":"K6-1-u5-C10","difficulty":2,"kind":"mc","stem":"근거가 타당한지 판단할 때 던질 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"이 근거가 이유를 뒷받침하는가?","correct":true},{"t":"근거의 글자 수가 많은가?","mis":"K6-1-u5-X15"},{"t":"근거가 맨 앞에 나오는가?","mis":"K6-1-u5-X15"},{"t":"근거가 글쓴이의 느낌인가?","mis":"K6-1-u5-X09"}],"explanation":["길이는 기준이 아니에요.","놓인 차례도 아니에요.","받쳐 주는지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_basic#10','kor',6,1,'u5','L02','g6_1_kor_u5_L02_basic','lesson_basic','K6-1-u5-C15',3,'mc','auto','「출처가 적혀 있네. 그럼 맞는 말이겠지.」라고 읽는 태도의 문제점은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X21','K6-1-u5-X15']::text[],false,'{"seq":10,"concept":"K6-1-u5-C15","difficulty":3,"kind":"mc","stem":"「출처가 적혀 있네. 그럼 맞는 말이겠지.」라고 읽는 태도의 문제점은 어느 것인가요?","options":[{"t":"출처는 어디서 왔는지 알려 줄 뿐, 자료가 이유를 정말 받치는지는 따로 보아야 한다","correct":true},{"t":"출처가 있으면 언제나 맞는 말이다","mis":"K6-1-u5-X14"},{"t":"출처는 아예 읽지 않아도 된다","mis":"K6-1-u5-X21"},{"t":"그냥 그럴 것 같으면 맞는 말로 여겨도 된다","mis":"K6-1-u5-X15"}],"explanation":["출처가 곧 타당함은 아니에요.","출처도 꼭 살펴요.","판단에도 까닭이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#1','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C11',2,'mc','auto','①문단에서 「지금부터 그렇게 해야 하는 까닭을 살펴보자.」가 하는 일은 어느 것인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X27']::text[],false,'{"seq":1,"concept":"K6-1-u5-C11","difficulty":2,"kind":"mc","stem":"①문단에서 「지금부터 그렇게 해야 하는 까닭을 살펴보자.」가 하는 일은 어느 것인가요?","options":[{"t":"이어서 무엇을 살펴볼지 한 줄로 안내한다","correct":true},{"t":"주장한 내용을 요약한다","mis":"K6-1-u5-X10"},{"t":"이유를 뒷받침하는 근거를 든다","mis":"K6-1-u5-X10"},{"t":"처음 꺼내는 새 주장을 밝힌다","mis":"K6-1-u5-X27"}],"explanation":["요약은 결론에서 해요.","근거는 본론에서 들어요.","서론은 이어질 내용을 안내하기도 해요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#2','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C14',2,'ox','auto','중심 문장만 이어 읽어도 글 전체의 뼈대가 드러나요.',ARRAY['K6-1-u5-X13']::text[],false,'{"seq":2,"concept":"K6-1-u5-C14","difficulty":2,"kind":"ox","stem":"중심 문장만 이어 읽어도 글 전체의 뼈대가 드러나요.","answer":"O","reason_options":[{"t":"중심 문장이 문단마다 하고 싶은 말을 대표하기 때문에","correct":true},{"t":"뒷받침 문장에만 글의 뜻이 담기기 때문에","mis":"K6-1-u5-X13"}],"mis":"K6-1-u5-X13","explanation":["중심 문장이 문단을 대표해요.","뒷받침 문장은 받쳐 줘요.","중심 문장으로 뼈대가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#3','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C8',3,'match','auto','이유와 그 이유를 받친 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C8","difficulty":3,"kind":"match","stem":"이유와 그 이유를 받친 근거를 알맞게 이으세요.","pairs":[{"l":"더 안전하게 놀 수 있다","r":"부딪힐 뻔했다는 학급 설문"},{"l":"놀이를 끝까지 할 수 있다","r":"그만둔 무리를 센 관찰 기록"},{"l":"다툼이 줄어든다","r":"다툼에 대한 선생님 면담"}],"mis":"K6-1-u5-X03","explanation":["안전은 부딪힘과 이어져요.","놀이는 그만둔 무리와 이어져요.","다툼은 선생님 말씀과 이어져요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#4','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C10',3,'error','auto','이 글을 읽고 근거를 판단한 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X14','K6-1-u5-X23']::text[],false,'{"seq":4,"concept":"K6-1-u5-C10","difficulty":3,"kind":"error","stem":"이 글을 읽고 근거를 판단한 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"슬아 — 「근거가 길게 적혀 있으니 타당한 근거야.」","correct":true,"mis_target":"K6-1-u5-X15"},{"t":"규리 — 「설문이 「부딪힐 뻔했는지」를 물었으니 안전 이유를 받쳐 줘.」","mis":"K6-1-u5-X14"},{"t":"민찬 — 「직접 센 기록이라 누구나 다시 세어 확인할 수 있어.」","mis":"K6-1-u5-X23"}],"explanation":["규리는 이유와 이어지는지 보았어요.","민찬은 확인할 수 있는지 보았어요.","길이는 타당성의 기준이 아니에요."],"asset":{"type":"passage","lines":["① 점심시간이면 운동장은 공놀이와 달리기와 줄넘기가 한꺼번에 벌어져","서로 부딪힐까 봐 마음을 놓지 못한다. 점심시간 운동장을 학년에 따라","나누어 써야 한다. 지금부터 그렇게 해야 하는 까닭을 살펴보자.","② 첫째, 나누어 쓰면 더 안전하게 놀 수 있기 때문이다. 우리 반 스물다섯","명 가운데 열여덟 명이 다른 사람과 부딪힐 뻔한 적이 있다고 답했다.","(솔바람반(2026), 「점심시간 운동장 이용 설문」, 학급 게시판.)","넉넉한 곳에서 놀면 뒤를 살피느라 멈칫할 일이 줄어든다."],"title":"「점심시간 운동장을 나누어 씁시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#5','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C9',3,'mc','auto','이유가 타당한지 묻는 두 물음으로 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X03','K6-1-u5-X08']::text[],false,'{"seq":5,"concept":"K6-1-u5-C9","difficulty":3,"kind":"mc","stem":"이유가 타당한지 묻는 두 물음으로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"주장과 이유가 관련 있는가? · 이유가 주장을 잘 설명하는가?","correct":true},{"t":"이유가 길게 쓰였는가? · 이유가 맨 처음에 나오는가?","mis":"K6-1-u5-X15"},{"t":"이유에 숫자가 있는가? · 이유에 출처가 있는가?","mis":"K6-1-u5-X03"},{"t":"이유가 옳은 말인가? · 이유가 재미있는가?","mis":"K6-1-u5-X08"}],"explanation":["길이와 차례는 기준이 아니에요.","수와 출처는 근거를 볼 때예요.","옳은 말이어도 주장과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#6','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C13',3,'mc','auto','결론에 「요일마다 학년을 정하는 방법도 있다」를 넣은 것은 어떤 내용을 담은 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10','K6-1-u5-X03']::text[],false,'{"seq":6,"concept":"K6-1-u5-C13","difficulty":3,"kind":"mc","stem":"결론에 「요일마다 학년을 정하는 방법도 있다」를 넣은 것은 어떤 내용을 담은 것인가요?","options":[{"t":"주장이 이루어질 방법과 앞으로를 내다보는 내용","correct":true},{"t":"처음 꺼내는 새로운 근거","mis":"K6-1-u5-X11"},{"t":"문제를 처음 제기하는 내용","mis":"K6-1-u5-X10"},{"t":"이유를 받치는 설문 결과","mis":"K6-1-u5-X03"}],"explanation":["새 근거가 아니에요.","문제 제기는 서론이에요.","결론은 전망을 담기도 해요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#7','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C14',3,'mc','auto','④문단의 「학년 선생님께 여쭈어 보니 … 가장 잦다고 하셨다.」가 중심 문장이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X23','K6-1-u5-X03']::text[],false,'{"seq":7,"concept":"K6-1-u5-C14","difficulty":3,"kind":"mc","stem":"④문단의 「학년 선생님께 여쭈어 보니 … 가장 잦다고 하셨다.」가 중심 문장이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「셋째, 다툼이 줄어들기 때문이다」를 받쳐 주는 면담 내용이기 때문이다","correct":true},{"t":"문단에서 가장 긴 문장이기 때문이다","mis":"K6-1-u5-X13"},{"t":"선생님 말씀은 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"출처가 붙어 있어 주장이기 때문이다","mis":"K6-1-u5-X03"}],"explanation":["길이로 정하지 않아요.","면담도 근거가 돼요.","받쳐 주는 문장이라 뒷받침 문장이에요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#8','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C15',4,'mc','auto','「출처가 붙어 있다고 다 타당한 근거는 아니다」를 가장 잘 보여 주는 예는 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X47']::text[],false,'{"seq":8,"concept":"K6-1-u5-C15","difficulty":4,"kind":"mc","stem":"「출처가 붙어 있다고 다 타당한 근거는 아니다」를 가장 잘 보여 주는 예는 어느 것인가요?","options":[{"t":"「운동장을 나누자」는 글에 출처를 밝힌 「급식 잔반 설문」을 근거로 붙였다","correct":true},{"t":"「부딪힐 뻔한 적이 있다」는 설문을 안전 이유에 붙였다","mis":"K6-1-u5-X14"},{"t":"선생님 면담을 다툼 이유에 붙였다","mis":"K6-1-u5-X14"},{"t":"출처 없이 「다들 그렇대」라고 썼다","mis":"K6-1-u5-X47"}],"explanation":["이것은 이유와 이어진 근거예요.","이것도 이어진 근거예요.","출처가 있어도 이유와 이어지지 않으면 힘이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#9','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C10',4,'essay','teacher','③문단의 근거가 이유를 잘 뒷받침하는지 판단하고, 그렇게 판단한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C10","difficulty":4,"kind":"essay","stem":"③문단의 근거가 이유를 잘 뒷받침하는지 판단하고, 그렇게 판단한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 잘 뒷받침한다. 첫째, 이유는 「하려던 놀이를 끝까지 할 수 있다」인데 근거가 「놀이를 그만둔 무리 수」를 세어서 이유와 바로 이어진다. 둘째, 사흘 동안 직접 센 기록이고 언제 · 누가 · 어디에 실었는지 출처가 밝혀져 있어 누구나 다시 확인할 수 있다.","scoring_points":["뒷받침하는지 판단을 밝혔는가","이유와 근거의 관련을 까닭으로 썼는가","출처나 확인 가능성을 까닭으로 썼는가"]},"explanation":["판단을 먼저 밝혀요.","이유와 근거를 견줘요.","출처를 살펴요."],"asset":{"type":"passage","lines":["③ 둘째, 하려던 놀이를 끝까지 할 수 있기 때문이다. 사흘 동안 세어 보니","줄넘기를 하다 공에 밀려 그만둔 무리가 하루 평균 네 무리였다.","(솔바람반(2026), 「사흘 동안의 운동장 관찰 기록」, 학급 게시판.)","④ 셋째, 다툼이 줄어들기 때문이다. 학년 선생님께 여쭈어 보니 점심시간","다툼 가운데 놀 곳을 두고 벌어지는 다툼이 가장 잦다고 하셨다.","(김○○ 선생님 면담(2026), 「점심시간 생활 지도」, 육 학년 교무실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 요일마다 학년을 정하는 방법도","있다. 모두에게 넉넉한 점심시간이 되도록 운동장을 나누어 쓰자."],"title":"「점심시간 운동장을 나누어 씁시다」 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L02_challenge#10','kor',6,1,'u5','L02','g6_1_kor_u5_L02_challenge','lesson_challenge','K6-1-u5-C12',4,'essay','teacher','이 글의 짜임을 서론 · 본론 · 결론으로 나누고, 각 부분이 어떤 일을 하는지 문단 번호를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C12","difficulty":4,"kind":"essay","stem":"이 글의 짜임을 서론 · 본론 · 결론으로 나누고, 각 부분이 어떤 일을 하는지 문단 번호를 들어 설명하세요.","answer_guide":{"answer":"예: 서론은 ①문단으로, 운동장이 붐비는 문제를 꺼내고 「운동장을 학년에 따라 나누어 써야 한다」는 주장을 밝혔다. 본론은 ②~④문단으로, 안전 · 놀이 · 다툼의 세 이유마다 설문 · 관찰 기록 · 면담의 근거를 붙여 주장을 펼쳤다. 결론은 ⑤문단으로, 세 까닭을 모아 말하고 주장을 다시 강조했다.","scoring_points":["서론과 그 일을 썼는가","본론과 이유 · 근거를 썼는가","결론과 요약 · 강조를 썼는가"]},"explanation":["문단 번호를 나눠요.","각 부분이 하는 일을 써요.","이유와 근거도 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#1','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C17',1,'mc','auto','「인용」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X16','K6-1-u5-X17','K6-1-u5-X10']::text[],false,'{"seq":1,"concept":"K6-1-u5-C17","difficulty":1,"kind":"mc","stem":"「인용」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 사람의 말이나 글, 자료를 가져와 자신의 글에서 쓰는 것","correct":true},{"t":"내 생각을 처음으로 지어내 쓰는 것","mis":"K6-1-u5-X16"},{"t":"남의 글을 조각조각 이어 붙여 내 글인 척하는 것","mis":"K6-1-u5-X17"},{"t":"글의 마지막에 주장을 다시 쓰는 것","mis":"K6-1-u5-X10"}],"explanation":["내가 지어낸 것은 인용이 아니에요.","그것은 표절이에요.","가져와 쓰는 것이 인용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#2','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C20',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C20","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"저작물","r":"생각이나 감정을 표현한 창작물"},{"l":"저작자","r":"그 창작물을 만든 사람"},{"l":"저작권","r":"만든 사람이 가지는 권리"}],"mis":"K6-1-u5-X20","explanation":["「물」은 만든 것이에요.","「자」는 사람이에요.","「권」은 권리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#3','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',1,'mc','auto','출처에 들어가야 할 네 가지로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":3,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"출처에 들어가야 할 네 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳","correct":true},{"t":"만든 사람 · 자료의 길이 · 글씨체 · 쪽수","mis":"K6-1-u5-X21"},{"t":"자료의 이름 · 내 이름 · 읽은 날 · 느낌","mis":"K6-1-u5-X21"},{"t":"만든 사람 · 자료의 이름만","mis":"K6-1-u5-X21"}],"explanation":["길이나 글씨체는 아니에요.","내 느낌은 넣지 않아요.","네 가지가 다 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#4','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C16',1,'ox','auto','내가 직접 겪은 일을 쓴 문장에도 반드시 출처를 밝혀야 해요.',ARRAY['K6-1-u5-X16']::text[],false,'{"seq":4,"concept":"K6-1-u5-C16","difficulty":1,"kind":"ox","stem":"내가 직접 겪은 일을 쓴 문장에도 반드시 출처를 밝혀야 해요.","answer":"X","reason_options":[{"t":"출처는 내가 만들지 않은 것을 가져다 쓸 때 밝히는 것이기 때문에","correct":true},{"t":"내가 쓴 문장은 모두 인용이기 때문에","mis":"K6-1-u5-X16"}],"mis":"K6-1-u5-X16","explanation":["내 경험은 내가 만든 것이에요.","남이 만든 것에 출처를 붙여요.","무엇을 가져왔는지 갈라 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#5','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C16',2,'mc','auto','다음 가운데 출처를 밝혀야 하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X16']::text[],false,'{"seq":5,"concept":"K6-1-u5-C16","difficulty":2,"kind":"mc","stem":"다음 가운데 출처를 밝혀야 하는 것은 어느 것인가요?","options":[{"t":"누리집에서 내려받은 표","correct":true},{"t":"내가 세운 주장","mis":"K6-1-u5-X16"},{"t":"내가 어제 직접 겪은 일","mis":"K6-1-u5-X16"},{"t":"내가 떠올린 이유","mis":"K6-1-u5-X16"}],"explanation":["주장은 내 생각이에요.","내 경험이에요.","남이 만든 표는 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#6','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C18',2,'mc','auto','출처를 밝혀야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X18']::text[],false,'{"seq":6,"concept":"K6-1-u5-C18","difficulty":2,"kind":"mc","stem":"출처를 밝혀야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"만든 사람의 권리를 지키고 어디까지가 내 말인지 알리기 위해","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K6-1-u5-X25"},{"t":"하고 싶을 때만 지키는 예의라서","mis":"K6-1-u5-X18"},{"t":"읽는 사람을 헷갈리게 하려고","mis":"K6-1-u5-X18"}],"explanation":["길이를 늘리려는 것이 아니에요.","예의가 아니라 약속이에요.","권리를 지키고 내 말과 남의 말을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#7','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',2,'mc','auto','「솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.」에서 빠진 것은 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":7,"concept":"K6-1-u5-C21","difficulty":2,"kind":"mc","stem":"「솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.」에서 빠진 것은 어느 것인가요?","options":[{"t":"자료를 만든 시기","correct":true},{"t":"인용한 자료의 이름","mis":"K6-1-u5-X21"},{"t":"자료가 실린 곳","mis":"K6-1-u5-X21"},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"}],"explanation":["이름은 적혀 있어요.","실린 곳도 적혀 있어요.","언제 만든 자료인지 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#8','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C19',2,'ox','auto','출처만 정확히 적으면 원래 뜻을 내 주장에 맞게 조금 세게 바꿔도 돼요.',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":8,"concept":"K6-1-u5-C19","difficulty":2,"kind":"ox","stem":"출처만 정확히 적으면 원래 뜻을 내 주장에 맞게 조금 세게 바꿔도 돼요.","answer":"X","reason_options":[{"t":"인용에는 출처를 밝히는 일과 뜻을 비틀지 않는 일이 함께 붙기 때문에","correct":true},{"t":"출처가 있으면 뜻은 어떻게 써도 되기 때문에","mis":"K6-1-u5-X19"}],"mis":"K6-1-u5-X19","explanation":["출처만으로는 부족해요.","뜻을 그대로 살려 옮겨요.","둘 다 지켜야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#9','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C21',2,'match','auto','출처의 각 부분과 그것이 무엇인지 알맞게 이으세요. — ○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":2,"kind":"match","stem":"출처의 각 부분과 그것이 무엇인지 알맞게 이으세요. — ○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.","pairs":[{"l":"○○초등학교 도서관","r":"만든 사람이나 기관"},{"l":"2026","r":"만든 시기"},{"l":"「사월 대출 통계」","r":"인용한 자료의 이름"},{"l":"도서관 게시판","r":"자료가 실린 곳"}],"mis":"K6-1-u5-X21","explanation":["맨 앞은 만든 쪽이에요.","괄호 안은 때예요.","낫표 안은 이름, 끝은 실린 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_basic#10','kor',6,1,'u5','L04','g6_1_kor_u5_L04_basic','lesson_basic','K6-1-u5-C24',3,'mc','auto','자료를 다섯 개 붙이고 내 문장은 두 줄뿐인 글의 문제점은 어느 것인가요?',ARRAY['K6-1-u5-X24','K6-1-u5-X14']::text[],false,'{"seq":10,"concept":"K6-1-u5-C24","difficulty":3,"kind":"mc","stem":"자료를 다섯 개 붙이고 내 문장은 두 줄뿐인 글의 문제점은 어느 것인가요?","options":[{"t":"읽고 나면 글쓴이가 무슨 생각인지 남지 않는다","correct":true},{"t":"자료가 많아 저절로 설득력이 커진다","mis":"K6-1-u5-X24"},{"t":"출처를 모두 밝혔으니 문제가 없다","mis":"K6-1-u5-X14"},{"t":"내 문장이 짧아 더 깔끔하다","mis":"K6-1-u5-X24"}],"explanation":["많다고 힘이 커지지 않아요.","출처만으로는 모자라요.","글에 담을 것은 내 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#1','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C17',2,'mc','auto','다음 가운데 표절에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X17','K6-1-u5-X16','K6-1-u5-X19']::text[],false,'{"seq":1,"concept":"K6-1-u5-C17","difficulty":2,"kind":"mc","stem":"다음 가운데 표절에 해당하는 것은 어느 것인가요?","options":[{"t":"여러 글에서 한 문장씩 가져와 이어 붙이고 내 글로 냈다","correct":true},{"t":"설문 결과를 가져오며 출처를 밝혔다","mis":"K6-1-u5-X17"},{"t":"내가 겪은 일을 내 말로 썼다","mis":"K6-1-u5-X16"},{"t":"선생님 말씀을 뜻 그대로 옮기고 출처를 붙였다","mis":"K6-1-u5-X19"}],"explanation":["출처를 밝힌 인용이에요.","내 경험은 표절이 아니에요.","조각 이어 붙이기도 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#2','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C20',2,'ox','auto','내가 쓴 주장하는 글도 저작물이고, 나도 그 글의 저작자예요.',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":2,"concept":"K6-1-u5-C20","difficulty":2,"kind":"ox","stem":"내가 쓴 주장하는 글도 저작물이고, 나도 그 글의 저작자예요.","answer":"O","reason_options":[{"t":"내 생각을 표현한 창작물이기 때문에","correct":true},{"t":"책으로 나온 글만 저작물이기 때문에","mis":"K6-1-u5-X20"}],"mis":"K6-1-u5-X20","explanation":["글은 생각을 표현한 거예요.","책이 아니어도 저작물이에요.","나도 저작자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#3','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C22',3,'mc','auto','두 학생이 같은 자료의 출처를 차례만 다르게 적었어요. 어떻게 보아야 하나요?',ARRAY['K6-1-u5-X22']::text[],false,'{"seq":3,"concept":"K6-1-u5-C22","difficulty":3,"kind":"mc","stem":"두 학생이 같은 자료의 출처를 차례만 다르게 적었어요. 어떻게 보아야 하나요?","options":[{"t":"네 가지가 빠지지 않았다면 둘 다 바르게 적은 것이다","correct":true},{"t":"정해진 차례가 하나뿐이라 한 사람은 틀렸다","mis":"K6-1-u5-X22"},{"t":"차례가 다르면 다른 자료가 된다","mis":"K6-1-u5-X22"},{"t":"부호를 다르게 쓰면 출처가 아니다","mis":"K6-1-u5-X22"}],"explanation":["차례는 조금씩 다를 수 있어요.","같은 자료예요.","네 가지가 빠지지 않는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#4','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C21',3,'mc','auto','빠진 것이 「자료가 실린 곳」인 출처는 어느 것인가요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":3,"kind":"mc","stem":"빠진 것이 「자료가 실린 곳」인 출처는 어느 것인가요?","options":[{"t":"ㄴ","correct":true},{"t":"ㄱ","mis":"K6-1-u5-X21"},{"t":"ㄷ","mis":"K6-1-u5-X21"},{"t":"ㄹ","mis":"K6-1-u5-X21"}],"explanation":["ㄱ은 만든 시기가 없어요.","ㄷ은 만든 사람이 없어요.","ㄴ은 어디에 실렸는지가 없어요."],"asset":{"type":"passage","lines":["ㄱ. 솔바람반, 「우리 반 독서 시간 조사」, 학급 게시판.","ㄴ. 솔바람반(2026), 「우리 반 독서 시간 조사」.","ㄷ. (2026), 「우리 반 독서 시간 조사」, 학급 게시판.","ㄹ. 솔바람반(2026), 학급 게시판."],"title":"무엇인가 빠진 출처 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#5','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C23',3,'mc','auto','근거로 쓰기 전에 한 번 더 확인해야 하는 자료는 어느 것인가요?',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":5,"concept":"K6-1-u5-C23","difficulty":3,"kind":"mc","stem":"근거로 쓰기 전에 한 번 더 확인해야 하는 자료는 어느 것인가요?","options":[{"t":"누가 썼는지 알 수 없고 언제 올라왔는지도 모르는 글","correct":true},{"t":"학교가 낸 기록","mis":"K6-1-u5-X23"},{"t":"신문에 실린 기사","mis":"K6-1-u5-X23"},{"t":"언제 · 누구에게 · 어디서 했는지 적어 둔 우리 반 설문","mis":"K6-1-u5-X23"}],"explanation":["학교 기록은 믿을 만해요.","기사도 믿을 만해요.","누가 언제 썼는지 모르면 확인할 길이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#6','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C19',3,'mc','auto','선생님께서 「먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다」고 하셨어요. 뜻을 비틀어 옮긴 것은 어느 것인가요?',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":6,"concept":"K6-1-u5-C19","difficulty":3,"kind":"mc","stem":"선생님께서 「먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다」고 하셨어요. 뜻을 비틀어 옮긴 것은 어느 것인가요?","options":[{"t":"먼 곳만 바라보면 눈이 나빠지지 않는다고 하셨다","correct":true},{"t":"먼 곳을 잠깐 바라보면 눈 피로에 도움이 된다고 하셨다","mis":"K6-1-u5-X19"},{"t":"눈이 피로할 때 먼 곳을 잠깐 보는 것이 좋다고 하셨다","mis":"K6-1-u5-X19"},{"t":"눈이 피로하면 먼 곳을 잠깐 바라보라고 하셨다","mis":"K6-1-u5-X19"}],"explanation":["뜻을 그대로 옮겼어요.","같은 뜻이에요.","「도움이 된다」를 「나빠지지 않는다」로 과장했어요."],"asset":{"type":"passage","lines":["ㄱ. 보건 선생님께 여쭈어 보니, 눈이 피로할 때에는 먼 곳을 잠깐","바라보는 것이 도움이 된다고 하셨다.","(박○○ 보건 교사 면담(2026), 「눈 건강 상담」, 보건실.)","ㄴ. 학교 도서관 대출 기록을 보니, 지난달 가장 많이 빌려 간 갈래는 이야기책이었다.","(○○초등학교 도서관(2026), 「사월 대출 통계」, 도서관 게시판.)"],"title":"출처를 밝혀 쓴 두 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#7','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C25',3,'error','auto','글을 다 쓰고 스스로 물어본 말이에요. 쓰기 윤리를 점검하는 물음이 아닌 것은 누구의 것인가요?',ARRAY['K6-1-u5-X25']::text[],false,'{"seq":7,"concept":"K6-1-u5-C25","difficulty":3,"kind":"error","stem":"글을 다 쓰고 스스로 물어본 말이에요. 쓰기 윤리를 점검하는 물음이 아닌 것은 누구의 것인가요?","options":[{"t":"예찬 — 「글을 다른 친구보다 길게 썼는가?」","correct":true,"mis_target":"K6-1-u5-X25"},{"t":"규리 — 「확인되지 않은 사실을 쓰지는 않았는가?」","mis":"K6-1-u5-X25"},{"t":"슬아 — 「다른 사람을 헐뜯는 말을 쓰지는 않았는가?」","mis":"K6-1-u5-X25"}],"explanation":["규리는 참인지 물었어요.","슬아는 남을 다치게 하지 않았는지 물었어요.","길이는 쓰기 윤리와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#8','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C22',4,'mc','auto','누리집에서 찾은 그래프를 내 글에 넣으려고 해요. 가장 알맞게 한 것은 어느 것인가요?',ARRAY['K6-1-u5-X16','K6-1-u5-X21','K6-1-u5-X17']::text[],false,'{"seq":8,"concept":"K6-1-u5-C22","difficulty":4,"kind":"mc","stem":"누리집에서 찾은 그래프를 내 글에 넣으려고 해요. 가장 알맞게 한 것은 어느 것인가요?","options":[{"t":"그래프의 제목과 만든 곳을 포함해 출처의 네 가지를 함께 적었다","correct":true},{"t":"그래프 모양만 내 손으로 다시 그려 넣고 출처는 뺐다","mis":"K6-1-u5-X16"},{"t":"「누리집에서 찾음」이라고만 적었다","mis":"K6-1-u5-X21"},{"t":"그래프를 그대로 붙이고 내 글이라고 했다","mis":"K6-1-u5-X17"}],"explanation":["다시 그려도 남이 만든 자료예요.","어느 누리집인지 확인할 수 없어요.","표 · 그래프는 제목과 만든 곳도 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#9','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C21',4,'essay','teacher','「네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다」는 말을, 출처에서 하나가 빠졌을 때 생기는 일을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":4,"kind":"essay","stem":"「네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다」는 말을, 출처에서 하나가 빠졌을 때 생기는 일을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 출처에서 만든 시기가 빠지면 읽는 사람은 그 조사를 언제 했는지 알 수 없어, 같은 반이 여러 번 한 조사 가운데 어느 것인지 찾을 수 없다. 실린 곳이 빠지면 어디에 가서 확인해야 할지 모른다. 하나라도 빠지면 「어딘가에서 봤다」와 다르지 않게 되므로 네 가지를 모두 적어야 한다.","scoring_points":["네 가지 가운데 하나가 빠진 예를 들었는가","확인할 수 없게 되는 까닭을 썼는가","네 가지를 모두 적어야 함을 정리했는가"]},"explanation":["빠진 것을 하나 골라요.","읽는 사람 쪽에서 생각해요.","네 가지가 왜 필요한지 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L04_challenge#10','kor',6,1,'u5','L04','g6_1_kor_u5_L04_challenge','lesson_challenge','K6-1-u5-C24',4,'essay','teacher','앞으로 쓸 주장하는 글에 넣을 자료 하나를 정하고, 출처를 네 가지를 갖추어 적은 뒤 그 자료가 어떤 이유를 받쳐 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C24","difficulty":4,"kind":"essay","stem":"앞으로 쓸 주장하는 글에 넣을 자료 하나를 정하고, 출처를 네 가지를 갖추어 적은 뒤 그 자료가 어떤 이유를 받쳐 주는지 쓰세요.","answer_guide":{"answer":"예: 자료 — 우리 반에서 한 「아침 독서 시간 설문」. 출처 — 새솔반(2026), 「아침 독서 시간 설문」, 학급 게시판. 이 자료는 「아침 독서 시간을 늘리면 책 읽는 습관이 생기기 때문이다」라는 이유를 받쳐 준다. 자료를 여러 개 붙이기보다 이유에 꼭 맞는 이 자료 하나를 쓰겠다.","scoring_points":["내가 쓸 자료를 정했는가","출처의 네 가지를 갖추어 적었는가","그 자료가 받치는 이유를 썼는가"]},"explanation":["직접 만들 수 있는 자료도 좋아요.","네 칸을 빠짐없이 적어요.","어떤 이유를 받치는지 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#1','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C26',1,'match','auto','발표 전에 정할 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u5-C26","difficulty":1,"kind":"match","stem":"발표 전에 정할 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"주제","r":"비 오는 날 복도에 흩어지는 우산"},{"l":"목적","r":"우산을 우산꽂이에 모으자고 설득하기"},{"l":"대상","r":"같은 층을 쓰는 다른 반 친구들"}],"mis":"K6-1-u5-X26","explanation":["주제는 다룰 문제예요.","목적은 이루고 싶은 것이에요.","대상은 들을 사람이에요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 복도에 흩어지는 우산","목적 — 우산을 우산꽂이에 모으자고 설득하고 싶다","대상 — 같은 층을 쓰는 다른 반 친구들","주장 — 비 오는 날 우산은 우산꽂이에 꽂읍시다.","이유 — 첫째, 걸려 넘어질 수 있다 / 둘째, 우산이 섞여 잃어버린다","　　　 셋째, 물이 흘러 바닥이 미끄러워진다"],"title":"우산 발표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#2','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C27',1,'mc','auto','뜻이 한 가지로 뚜렷하게 읽히는 주장은 어느 것인가요?',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":2,"concept":"K6-1-u5-C27","difficulty":1,"kind":"mc","stem":"뜻이 한 가지로 뚜렷하게 읽히는 주장은 어느 것인가요?","options":[{"t":"비 오는 날 우산은 우산꽂이에 꽂읍시다","correct":true},{"t":"우산을 잘 관리합시다","mis":"K6-1-u5-X27"},{"t":"복도를 더 좋게 만듭시다","mis":"K6-1-u5-X27"},{"t":"우리 모두 노력합시다","mis":"K6-1-u5-X27"}],"explanation":["무엇을 하자는지 흐려요.","사람마다 다르게 읽어요.","무엇을 · 어디에 · 언제가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#3','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C30',1,'ox','auto','「나는 어제 그렇게 느꼈다」는 진심이라면 근거가 될 수 있어요.',ARRAY['K6-1-u5-X09']::text[],false,'{"seq":3,"concept":"K6-1-u5-C30","difficulty":1,"kind":"ox","stem":"「나는 어제 그렇게 느꼈다」는 진심이라면 근거가 될 수 있어요.","answer":"X","reason_options":[{"t":"다른 사람이 찾아가 확인할 수 있는 객관적인 자료가 아니기 때문에","correct":true},{"t":"진심으로 느낀 것은 모두 객관적이기 때문에","mis":"K6-1-u5-X09"}],"mis":"K6-1-u5-X09","explanation":["느낌은 내 안에 있어요.","남이 확인할 수 없어요.","확인할 수 있어야 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#4','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C28',1,'mc','auto','「우산을 우산꽂이에 꽂자」의 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":4,"concept":"K6-1-u5-C28","difficulty":1,"kind":"mc","stem":"「우산을 우산꽂이에 꽂자」의 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다","correct":true},{"t":"비 오는 날에는 날씨가 흐리기 때문입니다","mis":"K6-1-u5-X08"},{"t":"가방이 무거우면 어깨가 아프기 때문입니다","mis":"K6-1-u5-X08"},{"t":"우산은 색이 여러 가지이기 때문입니다","mis":"K6-1-u5-X08"}],"explanation":["사실이어도 주장과 이어지지 않아요.","우산과 관계없어요.","주장이 이루어지면 사라지는 불편이라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#5','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C29',2,'match','auto','이유와 그 이유를 받쳐 줄 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u5-C29","difficulty":2,"kind":"match","stem":"이유와 그 이유를 받쳐 줄 근거를 알맞게 이으세요.","pairs":[{"l":"걸려 넘어질 수 있다","r":"비 온 날 복도에 놓인 우산을 센 관찰 기록"},{"l":"우산을 잃어버린다","r":"주인을 못 찾은 우산 수를 적은 분실물 기록"},{"l":"바닥이 미끄럽다","r":"물기 있는 바닥을 조심하라는 학교 안전 안내문"}],"mis":"K6-1-u5-X03","explanation":["넘어짐은 놓인 우산 수와 이어져요.","잃어버림은 분실물 기록과 이어져요.","미끄러움은 안전 안내문과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#6','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C26',2,'mc','auto','듣는 사람이 달라지면 무엇이 달라지나요?',ARRAY['K6-1-u5-X26','K6-1-u5-X08']::text[],false,'{"seq":6,"concept":"K6-1-u5-C26","difficulty":2,"kind":"mc","stem":"듣는 사람이 달라지면 무엇이 달라지나요?","options":[{"t":"고르는 근거와 말하는 방법","correct":true},{"t":"내가 세운 주장 자체","mis":"K6-1-u5-X26"},{"t":"발표하는 요일과 시각","mis":"K6-1-u5-X26"},{"t":"주장과 이유의 관계","mis":"K6-1-u5-X08"}],"explanation":["주장은 그대로예요.","시간은 관계없어요.","전하는 방법이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#7','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C30',2,'mc','auto','다음 가운데 근거로 쓸 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23']::text[],false,'{"seq":7,"concept":"K6-1-u5-C30","difficulty":2,"kind":"mc","stem":"다음 가운데 근거로 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"학교 분실물 기록에 적힌 우산의 수","correct":true},{"t":"내가 어제 아침에 느낀 기분","mis":"K6-1-u5-X09"},{"t":"아마 다들 그럴 것이라는 짐작","mis":"K6-1-u5-X09"},{"t":"친구가 그런 것 같다고 한 말","mis":"K6-1-u5-X23"}],"explanation":["기분은 확인할 수 없어요.","짐작은 자료가 아니에요.","누구나 찾아가 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#8','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C31',2,'ox','auto','반대할 사람이 할 말을 미리 떠올려 보면 내 주장이 더 단단해져요.',ARRAY['K6-1-u5-X28']::text[],false,'{"seq":8,"concept":"K6-1-u5-C31","difficulty":2,"kind":"ox","stem":"반대할 사람이 할 말을 미리 떠올려 보면 내 주장이 더 단단해져요.","answer":"O","reason_options":[{"t":"맞는 지적을 받아들여 내용을 보탤 수 있기 때문에","correct":true},{"t":"반대하는 말은 못 들은 척해야 주장이 흔들리지 않기 때문에","mis":"K6-1-u5-X28"}],"mis":"K6-1-u5-X28","explanation":["반박을 미리 떠올려요.","맞는 말이면 받아들여요.","내 주장을 차갑게 다시 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#9','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C32',2,'mc','auto','정리한 주장을 소리 내어 말해 볼 때의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X04']::text[],false,'{"seq":9,"concept":"K6-1-u5-C32","difficulty":2,"kind":"mc","stem":"정리한 주장을 소리 내어 말해 볼 때의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제와 주장 → 이유마다 근거와 출처 → 주장을 다시 힘주어","correct":true},{"t":"근거와 출처 → 문제와 주장 → 새 근거","mis":"K6-1-u5-X10"},{"t":"주장을 다시 힘주어 → 문제 → 이유","mis":"K6-1-u5-X10"},{"t":"이유만 차례로 → 마무리 인사","mis":"K6-1-u5-X04"}],"explanation":["근거부터 말하면 무엇을 받치는지 몰라요.","결론부터 시작하지 않아요.","서론 · 본론 · 결론 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_basic#10','kor',6,1,'u5','L06','g6_1_kor_u5_L06_basic','lesson_basic','K6-1-u5-C31',3,'mc','auto','슬아가 「우산꽂이가 하나뿐이라 다 안 들어가는데요?」라고 했을 때 가장 알맞은 대처는 어느 것인가요?',ARRAY['K6-1-u5-X28','K6-1-u5-X27','K6-1-u5-X25']::text[],false,'{"seq":10,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"슬아가 「우산꽂이가 하나뿐이라 다 안 들어가는데요?」라고 했을 때 가장 알맞은 대처는 어느 것인가요?","options":[{"t":"맞는 말이니 「층마다 우산꽂이를 하나씩 더 두자」는 내용을 함께 넣는다","correct":true},{"t":"못 들은 척하고 발표를 이어 간다","mis":"K6-1-u5-X28"},{"t":"주장을 「우산을 잘 관리합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"반대하는 친구의 말을 끊는다","mis":"K6-1-u5-X25"}],"explanation":["그 자리에서 무너져요.","주장이 흐려져요.","받아들여 보태면 단단해져요."],"asset":{"type":"speech","turns":[{"who":"발표자","text":"비 오는 날 우산은 우산꽂이에 꽂읍시다. 첫째, 복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다."},{"who":"슬아","text":"우산꽂이가 하나뿐이라 다 안 들어가는데요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#1','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C27',2,'ox','auto','「복도를 더 좋게 만듭시다」는 사람마다 다르게 읽혀 힘을 잃는 주장이에요.',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":1,"concept":"K6-1-u5-C27","difficulty":2,"kind":"ox","stem":"「복도를 더 좋게 만듭시다」는 사람마다 다르게 읽혀 힘을 잃는 주장이에요.","answer":"O","reason_options":[{"t":"청소로도 꾸미기로도 읽혀 무엇을 하면 되는지 한 가지로 읽히지 않기 때문에","correct":true},{"t":"좋은 말이니 누구나 같은 뜻으로 읽기 때문에","mis":"K6-1-u5-X27"}],"mis":"K6-1-u5-X27","explanation":["청소로 읽는 사람도 있어요.","꾸미기로 읽는 사람도 있어요.","한 가지로 읽혀야 힘이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#2','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C29',2,'mc','auto','근거를 찾는 길과 그 예가 바르게 이어진 것은 어느 것인가요?',ARRAY['K6-1-u5-X29','K6-1-u5-X23']::text[],false,'{"seq":2,"concept":"K6-1-u5-C29","difficulty":2,"kind":"mc","stem":"근거를 찾는 길과 그 예가 바르게 이어진 것은 어느 것인가요?","options":[{"t":"여쭈어 보기 — 그 일을 잘 아는 어른께 면담을 청한다","correct":true},{"t":"직접 조사하기 — 신문 기사를 찾아 옮겨 적는다","mis":"K6-1-u5-X29"},{"t":"공공 자료 보기 — 친구의 짐작을 듣는다","mis":"K6-1-u5-X23"},{"t":"기사 · 책 찾기 — 우리 반에 설문을 한다","mis":"K6-1-u5-X29"}],"explanation":["직접 조사는 설문이나 수 세기예요.","짐작은 공공 자료가 아니에요.","설문은 직접 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#3','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C28',3,'mc','auto','「우산은 우산꽂이에 꽂읍시다」의 이유를 고치려고 해요. 이유로 세울 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":3,"concept":"K6-1-u5-C28","difficulty":3,"kind":"mc","stem":"「우산은 우산꽂이에 꽂읍시다」의 이유를 고치려고 해요. 이유로 세울 수 있는 것은 어느 것인가요?","options":[{"t":"우산에서 흐른 물로 복도 바닥이 미끄러워지기 때문입니다","correct":true},{"t":"비가 오면 기분이 가라앉기 때문입니다","mis":"K6-1-u5-X08"},{"t":"우산꽂이는 값이 싸기 때문입니다","mis":"K6-1-u5-X08"},{"t":"복도는 넓기 때문입니다","mis":"K6-1-u5-X08"}],"explanation":["기분은 우산을 꽂는 일과 이어지지 않아요.","값은 주장을 설명하지 못해요.","꽂으면 사라지는 불편이라 이유가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#4','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C30',3,'error','auto','근거를 고른 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X29']::text[],false,'{"seq":4,"concept":"K6-1-u5-C30","difficulty":3,"kind":"error","stem":"근거를 고른 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"민찬 — 「다들 넘어질 뻔했을 거라는 내 짐작을 근거로 쓸래.」","correct":true,"mis_target":"K6-1-u5-X09"},{"t":"규리 — 「우리 층에서 우산에 걸린 적이 있는지 설문을 해 볼래.」","mis":"K6-1-u5-X23"},{"t":"예찬 — 「보건 선생님께 복도에서 다친 일을 여쭈어 볼래.」","mis":"K6-1-u5-X29"}],"explanation":["규리는 직접 조사를 골랐어요.","예찬은 면담을 골랐어요.","짐작은 근거가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#5','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C10',3,'mc','auto','근거가 타당한지 묻는 세 물음 가운데 셋째 물음이 특히 까다로운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X15','K6-1-u5-X09']::text[],false,'{"seq":5,"concept":"K6-1-u5-C10","difficulty":3,"kind":"mc","stem":"근거가 타당한지 묻는 세 물음 가운데 셋째 물음이 특히 까다로운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"진심으로 느낀 것도 객관적인 자료는 아니어서 가려내기 어렵기 때문이다","correct":true},{"t":"출처만 있으면 객관적이기 때문이다","mis":"K6-1-u5-X14"},{"t":"근거가 길수록 객관적이기 때문이다","mis":"K6-1-u5-X15"},{"t":"짐작도 객관적인 자료이기 때문이다","mis":"K6-1-u5-X09"}],"explanation":["출처가 곧 객관은 아니에요.","길이는 기준이 아니에요.","느낌과 짐작은 객관적인 자료가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#6','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C26',3,'mc','auto','같은 주장을 낮은 학년 동생들에게 발표한다면 무엇을 바꾸는 것이 알맞은가요?',ARRAY['K6-1-u5-X27','K6-1-u5-X04','K6-1-u5-X26']::text[],false,'{"seq":6,"concept":"K6-1-u5-C26","difficulty":3,"kind":"mc","stem":"같은 주장을 낮은 학년 동생들에게 발표한다면 무엇을 바꾸는 것이 알맞은가요?","options":[{"t":"어려운 낱말을 쉽게 풀고 동생들이 겪은 일과 이어진 근거를 고른다","correct":true},{"t":"주장을 「우산을 잘 관리합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"근거를 빼고 주장만 크게 말한다","mis":"K6-1-u5-X04"},{"t":"같은 말과 같은 근거를 그대로 쓴다","mis":"K6-1-u5-X26"}],"explanation":["주장을 흐리면 안 돼요.","근거가 있어야 해요.","대상에 맞게 근거와 말투를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#7','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C31',3,'mc','auto','「반대할 사람을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일」이라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X28']::text[],false,'{"seq":7,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"「반대할 사람을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일」이라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 편이 아닌 눈으로 주장의 빈틈을 찾아본다는 뜻이다","correct":true},{"t":"반대하는 사람을 차갑게 대한다는 뜻이다","mis":"K6-1-u5-X25"},{"t":"반대 의견이 나오면 주장을 버린다는 뜻이다","mis":"K6-1-u5-X28"},{"t":"내 편만 떠올리며 쓴다는 뜻이다","mis":"K6-1-u5-X28"}],"explanation":["사람을 차갑게 대하는 게 아니에요.","버리는 것이 아니라 보태요.","내 편만 떠올리면 내 편만 설득해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#8','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C32',4,'mc','auto','발표를 말로 먼저 해 본 뒤 스스로 확인할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X06','K6-1-u5-X25']::text[],false,'{"seq":8,"concept":"K6-1-u5-C32","difficulty":4,"kind":"mc","stem":"발표를 말로 먼저 해 본 뒤 스스로 확인할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장이 뚜렷이 드러났는지, 근거의 출처를 밝혔는지","correct":true},{"t":"목소리가 다른 친구보다 컸는지","mis":"K6-1-u5-X44"},{"t":"말한 시간이 얼마나 길었는지","mis":"K6-1-u5-X06"},{"t":"어려운 낱말을 몇 개 썼는지","mis":"K6-1-u5-X25"}],"explanation":["크기가 설득을 만들지 않아요.","길이는 관계없어요.","주장과 출처를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#9','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C31',4,'essay','teacher','「비 오는 날 우산은 우산꽂이에 꽂읍시다」에 대해 나올 만한 반박을 하나 떠올려 쓰고, 그 반박을 받아들여 주장을 어떻게 보탤지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C31","difficulty":4,"kind":"essay","stem":"「비 오는 날 우산은 우산꽂이에 꽂읍시다」에 대해 나올 만한 반박을 하나 떠올려 쓰고, 그 반박을 받아들여 주장을 어떻게 보탤지 쓰세요.","answer_guide":{"answer":"예: 반박 — 「우산꽂이에 꽂으면 내 우산을 다른 사람이 가져갈 수도 있어요.」 대처 — 그 걱정이 맞으므로 우산 손잡이에 이름표를 붙이자는 내용을 함께 넣겠다. 그러면 잃어버릴 걱정이 줄어 주장이 더 단단해진다.","scoring_points":["나올 만한 반박을 썼는가","반박을 못 들은 척하지 않고 받아들였는가","주장에 보탤 내용을 구체적으로 썼는가"]},"explanation":["반대할 사람의 마음이 되어요.","맞는 말인지 따져요.","보탤 내용을 써요."],"asset":{"type":"speech","turns":[{"who":"발표자","text":"비 오는 날 우산은 우산꽂이에 꽂읍시다. 첫째, 복도에 놓인 우산에 걸려 넘어질 수 있기 때문입니다."},{"who":"슬아","text":"우산꽂이가 하나뿐이라 다 안 들어가는데요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L06_challenge#10','kor',6,1,'u5','L06','g6_1_kor_u5_L06_challenge','lesson_challenge','K6-1-u5-C29',4,'essay','teacher','「셋째, 물이 흘러 바닥이 미끄러워진다」는 이유를 받쳐 줄 근거를 직접 만들려고 해요. 어떤 자료를 어떻게 만들지 쓰고, 출처를 네 가지를 갖추어 적으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C29","difficulty":4,"kind":"essay","stem":"「셋째, 물이 흘러 바닥이 미끄러워진다」는 이유를 받쳐 줄 근거를 직접 만들려고 해요. 어떤 자료를 어떻게 만들지 쓰고, 출처를 네 가지를 갖추어 적으세요.","answer_guide":{"answer":"예: 비 오는 날 사흘 동안 쉬는 시간마다 복도 바닥에 물이 고인 곳의 수를 세어 기록하겠다. 출처 — 솔바람반(2026), 「비 오는 날 복도 바닥 관찰 기록」, 학급 게시판. 이렇게 하면 누구나 다시 세어 확인할 수 있는 근거가 된다.","scoring_points":["이유와 이어진 자료를 정했는가","자료를 만드는 방법을 썼는가","출처를 네 가지를 갖추어 적었는가"]},"explanation":["이유의 낱말을 잡아요.","직접 세거나 물어봐요.","출처 네 칸을 채워요."],"asset":{"type":"passage","lines":["주제 — 비 오는 날 복도에 흩어지는 우산","목적 — 우산을 우산꽂이에 모으자고 설득하고 싶다","대상 — 같은 층을 쓰는 다른 반 친구들","주장 — 비 오는 날 우산은 우산꽂이에 꽂읍시다.","이유 — 첫째, 걸려 넘어질 수 있다 / 둘째, 우산이 섞여 잃어버린다","　　　 셋째, 물이 흘러 바닥이 미끄러워진다"],"title":"우산 발표 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#1','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C33',1,'mc','auto','주장하는 글의 주제로 쓸 수 있는 문제는 어느 것인가요?',ARRAY['K6-1-u5-X29']::text[],false,'{"seq":1,"concept":"K6-1-u5-C33","difficulty":1,"kind":"mc","stem":"주장하는 글의 주제로 쓸 수 있는 문제는 어느 것인가요?","options":[{"t":"빌린 책이 제때 돌아오지 않는다","correct":true},{"t":"내가 어제 늦잠을 잤다","mis":"K6-1-u5-X29"},{"t":"오늘 날씨가 흐리다","mis":"K6-1-u5-X29"},{"t":"내 필통 색이 마음에 들지 않는다","mis":"K6-1-u5-X29"}],"explanation":["나 혼자만의 일이에요.","근거를 대어 바꿀 수 있는 일이 아니에요.","근거를 댈 수 있고 여럿에게 알릴 만해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#2','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C34',1,'match','auto','계획하기에서 정할 것과 민찬이가 정한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C34","difficulty":1,"kind":"match","stem":"계획하기에서 정할 것과 민찬이가 정한 내용을 알맞게 이으세요.","pairs":[{"l":"글을 쓰는 목적","r":"반납일을 지키자고 설득하고 싶다"},{"l":"글의 주제","r":"빌린 책은 반납일을 지켜 돌려주기"},{"l":"글을 읽을 사람","r":"도서관을 함께 쓰는 우리 학교 학생들"}],"mis":"K6-1-u5-X37","explanation":["목적은 이루고 싶은 것이에요.","주제는 무엇에 대한 글인지예요.","읽을 사람은 누가 읽는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#3','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C35',1,'ox','auto','계획하기는 글을 쓰기 전에 한 번만 거치는 단계예요.',ARRAY['K6-1-u5-X30']::text[],false,'{"seq":3,"concept":"K6-1-u5-C35","difficulty":1,"kind":"ox","stem":"계획하기는 글을 쓰기 전에 한 번만 거치는 단계예요.","answer":"X","reason_options":[{"t":"쓰다가도 필요하면 언제든 계획으로 되돌아가 고칠 수 있기 때문에","correct":true},{"t":"한 번 세운 계획은 끝까지 지켜야 하기 때문에","mis":"K6-1-u5-X30"}],"mis":"K6-1-u5-X30","explanation":["쓰는 도중에도 돌아가요.","어긋난 계획을 붙들지 않아요.","되돌아가는 것이 정상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#4','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C37',1,'mc','auto','「통일성」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X33','K6-1-u5-X06']::text[],false,'{"seq":4,"concept":"K6-1-u5-C37","difficulty":1,"kind":"mc","stem":"「통일성」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글의 주제와 세부 내용이 서로 가깝게 이어져 있는 성질","correct":true},{"t":"문단의 길이가 모두 같은 성질","mis":"K6-1-u5-X33"},{"t":"모든 문장이 옳은 말인 성질","mis":"K6-1-u5-X33"},{"t":"글씨 크기가 고른 성질","mis":"K6-1-u5-X06"}],"explanation":["길이는 관계없어요.","옳은 말이어도 주제와 멀 수 있어요.","주제와 이어지는지가 통일성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#5','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C34',2,'mc','auto','읽을 사람이 정해지면 함께 고를 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u5-X26','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C34","difficulty":2,"kind":"mc","stem":"읽을 사람이 정해지면 함께 고를 수 있는 것은 어느 것인가요?","options":[{"t":"알맞은 표현과 내세울 근거","correct":true},{"t":"글을 쓸 문단의 개수","mis":"K6-1-u5-X26"},{"t":"사용할 연필의 색","mis":"K6-1-u5-X06"},{"t":"글을 쓰는 목적 자체","mis":"K6-1-u5-X26"}],"explanation":["문단 수가 정해지는 것이 아니에요.","연필 색은 관계없어요.","표현과 근거를 읽을 사람에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#6','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C36',2,'ox','auto','내용 생성하기 단계에서는 문장을 다듬기보다 떠오르는 것을 많이 꺼내 놓는 것이 먼저예요.',ARRAY['K6-1-u5-X31']::text[],false,'{"seq":6,"concept":"K6-1-u5-C36","difficulty":2,"kind":"ox","stem":"내용 생성하기 단계에서는 문장을 다듬기보다 떠오르는 것을 많이 꺼내 놓는 것이 먼저예요.","answer":"O","reason_options":[{"t":"핵심 낱말과 짧은 문장으로 쓸 거리를 모으는 단계이기 때문에","correct":true},{"t":"처음부터 완성된 문장으로만 적어야 하기 때문에","mis":"K6-1-u5-X31"}],"mis":"K6-1-u5-X31","explanation":["지금은 모으는 단계예요.","문장 다듬기는 나중이에요.","핵심 낱말로 많이 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#7','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C36',2,'mc','auto','자료를 찾았을 때 출처를 바로 적어 두어야 하는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X32','K6-1-u5-X22','K6-1-u5-X25']::text[],false,'{"seq":7,"concept":"K6-1-u5-C36","difficulty":2,"kind":"mc","stem":"자료를 찾았을 때 출처를 바로 적어 두어야 하는 까닭은 어느 것인가요?","options":[{"t":"나중에 찾아 헤매지 않고, 적어 둔 출처가 그대로 글에 들어가기 때문이다","correct":true},{"t":"출처는 다 쓴 뒤에 생각해도 되기 때문이다","mis":"K6-1-u5-X32"},{"t":"표는 모두 옮겨 그려야 하기 때문이다","mis":"K6-1-u5-X22"},{"t":"출처를 적으면 글이 길어 보이기 때문이다","mis":"K6-1-u5-X25"}],"explanation":["나중엔 어디서 봤는지 잊어요.","다 옮겨 그리지 않아도 돼요.","길이 때문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#8','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C37',2,'mc','auto','「반납일을 지키자」는 글의 통일성을 깨는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":8,"concept":"K6-1-u5-C37","difficulty":2,"kind":"mc","stem":"「반납일을 지키자」는 글의 통일성을 깨는 문장은 어느 것인가요?","options":[{"t":"도서관에서는 조용히 해야 하므로 떠들지 맙시다","correct":true},{"t":"그 책을 기다리는 사람이 있습니다","mis":"K6-1-u5-X33"},{"t":"늦어질수록 돌려줄 일을 잊기 쉽습니다","mis":"K6-1-u5-X33"},{"t":"도서관 일이 늘어납니다","mis":"K6-1-u5-X33"}],"explanation":["반납과 이어져요.","반납과 이어져요.","옳은 말이어도 주제와 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#9','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C38',2,'mc','auto','문단을 짤 때 먼저 세워야 하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X34']::text[],false,'{"seq":9,"concept":"K6-1-u5-C38","difficulty":2,"kind":"mc","stem":"문단을 짤 때 먼저 세워야 하는 것은 어느 것인가요?","options":[{"t":"이 문단에서 하고 싶은 말을 담은 중심 문장","correct":true},{"t":"조사 결과가 든 뒷받침 문장","mis":"K6-1-u5-X34"},{"t":"문단을 꾸미는 재미있는 문장","mis":"K6-1-u5-X34"},{"t":"다음 문단에서 할 말","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 그 아래에 붙여요.","꾸미는 문장이 먼저가 아니에요.","중심 문장부터 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_basic#10','kor',6,1,'u5','L08','g6_1_kor_u5_L08_basic','lesson_basic','K6-1-u5-C39',3,'mc','auto','「기다리는 사람 · 예약 대기 열한 명」을 표현하기 단계에서 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u5-X31']::text[],false,'{"seq":10,"concept":"K6-1-u5-C39","difficulty":3,"kind":"mc","stem":"「기다리는 사람 · 예약 대기 열한 명」을 표현하기 단계에서 바르게 쓴 것은 어느 것인가요?","options":[{"t":"「첫째, 그 책을 기다리는 사람이 있기 때문입니다.」","correct":true},{"t":"「기다리는 사람 · 예약 대기 열한 명」","mis":"K6-1-u5-X31"},{"t":"「예약 대기」","mis":"K6-1-u5-X31"},{"t":"「기다림 — 많음」","mis":"K6-1-u5-X31"}],"explanation":["조직하기의 메모 그대로예요.","낱말 하나로는 문장이 아니에요.","표현하기는 스스로 문장을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#1','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C33',2,'mc','auto','주장하는 글의 주제가 되려면 넘겨야 할 두 조건은 어느 것인가요?',ARRAY['K6-1-u5-X29']::text[],false,'{"seq":1,"concept":"K6-1-u5-C33","difficulty":2,"kind":"mc","stem":"주장하는 글의 주제가 되려면 넘겨야 할 두 조건은 어느 것인가요?","options":[{"t":"주장 · 이유 · 근거를 댈 수 있다 · 여러 사람에게 알릴 만하다","correct":true},{"t":"나만 아는 일이다 · 길게 쓸 수 있다","mis":"K6-1-u5-X29"},{"t":"재미있다 · 어려운 낱말이 많다","mis":"K6-1-u5-X29"},{"t":"근거가 없어도 된다 · 혼자만의 일이다","mis":"K6-1-u5-X29"}],"explanation":["나만 아는 일은 설득할 상대가 없어요.","재미나 어려움이 조건이 아니에요.","근거와 알릴 상대가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#2','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C35',3,'error','auto','글을 쓰다가 한 말이에요. 쓰기 과정을 잘못 이해한 말은 누구의 것인가요?',ARRAY['K6-1-u5-X30','K6-1-u5-X38']::text[],false,'{"seq":2,"concept":"K6-1-u5-C35","difficulty":3,"kind":"error","stem":"글을 쓰다가 한 말이에요. 쓰기 과정을 잘못 이해한 말은 누구의 것인가요?","options":[{"t":"예찬 — 「계획은 이미 세웠으니 이제 되돌아가면 안 돼.」","correct":true,"mis_target":"K6-1-u5-X30"},{"t":"민찬 — 「쓰다 보니 읽을 사람이 달라져야겠네. 계획으로 돌아가자.」","mis":"K6-1-u5-X30"},{"t":"규리 — 「조직하다 보니 근거가 모자라. 내용 생성으로 돌아갈래.」","mis":"K6-1-u5-X38"}],"explanation":["민찬은 바르게 되돌아갔어요.","규리도 바르게 되돌아갔어요.","계획으로 언제든 돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#3','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C36',3,'match','auto','민찬이의 이유와 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C36","difficulty":3,"kind":"match","stem":"민찬이의 이유와 근거를 알맞게 이으세요.","pairs":[{"l":"기다리는 사람이 있다","r":"지난달 예약 대기 열한 명이라는 기록"},{"l":"늦을수록 잊기 쉽다","r":"열네 명이 잊은 적 있다는 설문"},{"l":"도서관 일이 늘어난다","r":"정리에 시간이 많이 든다는 면담"}],"mis":"K6-1-u5-X03","explanation":["기다림은 예약 대기와 이어져요.","잊음은 설문과 이어져요.","일이 늚은 면담과 이어져요."],"asset":{"type":"passage","lines":["근거 하나 — 예약해 놓고 기다리는 사람이 지난달에 열한 명이었다.","(○○초등학교 도서관(2026), 「사월 예약 대기 기록」, 도서관 게시판.)","근거 둘 — 우리 반 스물다섯 명 가운데 열네 명이 반납일을 잊은 적이 있다고 답했다.","(솔바람반(2026), 「도서 반납 습관 설문」, 학급 게시판.)","근거 셋 — 늦게 돌아온 책을 다시 정리하는 데 시간이 많이 든다고 하셨다.","(이○○ 사서 선생님 면담(2026), 「도서관 운영 이야기」, 학교 도서관.)"],"title":"민찬이 모은 근거와 출처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#4','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C37',3,'mc','auto','민찬이의 개요에 「도서관 책상은 깨끗이 써야 한다」를 본론에 넣으려 해요. 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u5-X33','K6-1-u5-X11','K6-1-u5-X27']::text[],false,'{"seq":4,"concept":"K6-1-u5-C37","difficulty":3,"kind":"mc","stem":"민찬이의 개요에 「도서관 책상은 깨끗이 써야 한다」를 본론에 넣으려 해요. 어떻게 하는 것이 알맞은가요?","options":[{"t":"옳은 말이지만 반납일과 이어지지 않으므로 개요에서 걸러 낸다","correct":true},{"t":"옳은 말이니 그대로 넣는다","mis":"K6-1-u5-X33"},{"t":"결론에 새 이유로 넣는다","mis":"K6-1-u5-X11"},{"t":"서론의 주장으로 바꾼다","mis":"K6-1-u5-X27"}],"explanation":["옳아도 주제와 멀면 통일성이 깨져요.","결론은 새 이유를 꺼내지 않아요.","주장이 흐려져요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#5','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C38',3,'mc','auto','「뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있지만, 중심 문장은 없으면 어색하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X34']::text[],false,'{"seq":5,"concept":"K6-1-u5-C38","difficulty":3,"kind":"mc","stem":"「뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있지만, 중심 문장은 없으면 어색하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"문단이 하고 싶은 말은 중심 문장이 맡고 있다는 뜻이다","correct":true},{"t":"뒷받침 문장이 문단의 중심이라는 뜻이다","mis":"K6-1-u5-X13"},{"t":"중심 문장은 없어도 된다는 뜻이다","mis":"K6-1-u5-X34"},{"t":"문단에는 문장이 하나만 있어야 한다는 뜻이다","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 받쳐 줘요.","중심 문장이 빠지면 어색해요.","중심 문장이 문단을 대표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#6','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C39',3,'mc','auto','표현하기를 하다가 더 좋은 근거가 떠올랐을 때 알맞은 행동은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X32']::text[],false,'{"seq":6,"concept":"K6-1-u5-C39","difficulty":3,"kind":"mc","stem":"표현하기를 하다가 더 좋은 근거가 떠올랐을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"앞 단계로 돌아가 근거와 출처를 보태고 다시 써 나간다","correct":true},{"t":"표현하기를 시작했으니 떠오른 생각은 버린다","mis":"K6-1-u5-X38"},{"t":"출처는 빼고 근거만 그 자리에서 넣는다","mis":"K6-1-u5-X32"},{"t":"처음부터 모든 단계를 다시 한다","mis":"K6-1-u5-X38"}],"explanation":["되돌아가도 괜찮아요.","출처도 함께 적어요.","처음부터가 아니라 그 단계로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#7','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C13',2,'mc','auto','민찬이의 개요에서 결론에 담긴 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":7,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"민찬이의 개요에서 결론에 담긴 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"반납일을 지키면 좋아질 모습과, 지금 할 일을 다시 힘주어 말한 것","correct":true},{"t":"처음 꺼내는 새 근거","mis":"K6-1-u5-X11"},{"t":"도서관에 책이 쌓인 문제 제기","mis":"K6-1-u5-X10"},{"t":"세 이유를 받치는 출처","mis":"K6-1-u5-X10"}],"explanation":["새 근거는 꺼내지 않아요.","문제 제기는 서론이에요.","출처는 본론에 있어요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#8','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C34',4,'mc','auto','민찬이가 쓰다가 「선생님들께도 이 글을 보여 드리자」고 읽을 사람을 넓혔어요. 가장 알맞은 다음 행동은 어느 것인가요?',ARRAY['K6-1-u5-X30','K6-1-u5-X26','K6-1-u5-X24']::text[],false,'{"seq":8,"concept":"K6-1-u5-C34","difficulty":4,"kind":"mc","stem":"민찬이가 쓰다가 「선생님들께도 이 글을 보여 드리자」고 읽을 사람을 넓혔어요. 가장 알맞은 다음 행동은 어느 것인가요?","options":[{"t":"계획하기로 돌아가 읽을 사람을 고치고, 선생님들께 맞는 말투와 근거인지 다시 살핀다","correct":true},{"t":"계획은 이미 끝났으니 그대로 쓴다","mis":"K6-1-u5-X30"},{"t":"읽을 사람이 늘었으니 주장을 바꾼다","mis":"K6-1-u5-X26"},{"t":"근거를 다섯 개 더 붙인다","mis":"K6-1-u5-X24"}],"explanation":["계획으로 돌아가도 돼요.","주장은 그대로예요.","많이 붙인다고 좋아지지 않아요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#9','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C37',4,'essay','teacher','민찬이의 개요가 통일성을 갖추었는지 판단하고, 그 까닭을 서론 · 본론 · 결론과 이어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C37","difficulty":4,"kind":"essay","stem":"민찬이의 개요가 통일성을 갖추었는지 판단하고, 그 까닭을 서론 · 본론 · 결론과 이어 설명하세요.","answer_guide":{"answer":"예: 통일성을 갖추었다. 서론에서 반납일이 지난 책 문제를 꺼내고 「반납일을 지켜 돌려주자」고 주장했다. 본론의 세 이유(기다리는 사람 · 잊기 쉬움 · 도서관 일)는 모두 반납일을 지켜야 하는 까닭이고 근거도 그 이유에 맞는다. 결론도 반납일을 지키자는 주장으로 모았다. 주제와 멀어진 내용이 없다.","scoring_points":["통일성에 대한 판단을 밝혔는가","본론의 이유가 주제와 이어지는지 썼는가","서론과 결론이 같은 주제로 모이는지 썼는가"]},"explanation":["주제를 먼저 잡아요.","이유마다 주제와 이어지는지 봐요.","처음과 끝도 견줘요."],"asset":{"type":"passage","lines":["서론 — 도서관에는 반납일이 지난 책이 늘 쌓여 있다.","　　　 빌린 책은 반납일을 지켜 돌려주어야 한다.","본론 — 첫째, 기다리는 사람이 있다.(예약 대기 기록)","　　　 둘째, 늦어질수록 잊기 쉽다.(반납 습관 설문)","　　　 셋째, 도서관 일이 늘어난다.(사서 선생님 면담)","결론 — 반납일을 지키면 모두가 더 편하게 책을 빌릴 수 있다.","　　　 오늘 빌린 책의 반납일을 지금 적어 두자."],"title":"민찬의 개요 「빌린 책은 반납일을 지켜 돌려줍시다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L08_challenge#10','kor',6,1,'u5','L08','g6_1_kor_u5_L08_challenge','lesson_challenge','K6-1-u5-C36',4,'essay','teacher','내가 주장하는 글을 쓴다면 어떤 주제로 쓸지 정하고, 내용 생성하기 단계에서 꺼낼 이유 두 가지와 근거로 찾을 자료를 핵심 낱말로 적으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C36","difficulty":4,"kind":"essay","stem":"내가 주장하는 글을 쓴다면 어떤 주제로 쓸지 정하고, 내용 생성하기 단계에서 꺼낼 이유 두 가지와 근거로 찾을 자료를 핵심 낱말로 적으세요.","answer_guide":{"answer":"예: 주제 — 빈 교실의 불은 끄고 나갑시다. 이유 — 첫째, 전기 낭비 · 둘째, 끄는 사람 따로 없음. 근거로 찾을 자료 — 일주일 동안 빈 교실에 불이 켜진 횟수 관찰 기록(우리 반) · 시설 담당 선생님 면담. 출처는 자료를 찾는 대로 적어 두겠다.","scoring_points":["근거를 댈 수 있고 여럿에게 알릴 만한 주제를 정했는가","이유 두 가지를 핵심 낱말로 꺼냈는가","찾을 자료와 출처를 적어 둘 계획을 썼는가"]},"explanation":["겪은 일 가운데 골라요.","문장보다 핵심 낱말로 꺼내요.","자료와 출처를 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#1','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C41',1,'mc','auto','쓰기 과정 다섯 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":1,"concept":"K6-1-u5-C41","difficulty":1,"kind":"mc","stem":"쓰기 과정 다섯 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"계획하기 → 내용 생성하기 → 내용 조직하기 → 표현하기 → 고쳐쓰기","correct":true},{"t":"내용 생성하기 → 계획하기 → 표현하기 → 내용 조직하기 → 고쳐쓰기","mis":"K6-1-u5-X37"},{"t":"표현하기 → 고쳐쓰기 → 계획하기 → 내용 생성하기 → 내용 조직하기","mis":"K6-1-u5-X37"},{"t":"계획하기 → 표현하기 → 내용 생성하기 → 고쳐쓰기 → 내용 조직하기","mis":"K6-1-u5-X37"}],"explanation":["계획이 먼저예요.","표현하기가 처음이 아니에요.","정하고 · 모으고 · 늘어놓고 · 쓰고 · 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#2','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C41',1,'match','auto','내가 한 일과 쓰기 과정을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u5-C41","difficulty":1,"kind":"match","stem":"내가 한 일과 쓰기 과정을 알맞게 이으세요.","pairs":[{"l":"글을 읽을 사람을 누구로 할지 정했다","r":"계획하기"},{"l":"도서관 기록을 찾아 출처를 적어 두었다","r":"내용 생성하기"},{"l":"이유 셋을 서론 · 본론 · 결론에 나누어 늘어놓았다","r":"내용 조직하기"},{"l":"쓴 글에서 어색한 문장을 찾아 고쳤다","r":"고쳐쓰기"}],"mis":"K6-1-u5-X37","explanation":["정하는 일은 계획하기예요.","모으는 일은 내용 생성하기예요.","늘어놓는 일은 조직하기, 손보는 일은 고쳐쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#3','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C42',1,'ox','auto','표현하기까지 왔다가 내용 생성하기로 되돌아가는 것은 실패예요.',ARRAY['K6-1-u5-X38']::text[],false,'{"seq":3,"concept":"K6-1-u5-C42","difficulty":1,"kind":"ox","stem":"표현하기까지 왔다가 내용 생성하기로 되돌아가는 것은 실패예요.","answer":"X","reason_options":[{"t":"쓰기는 되돌아오는 성질을 지녀 되돌아간 단계에서 글이 좋아지기 때문에","correct":true},{"t":"앞으로만 가야 좋은 글이 되기 때문에","mis":"K6-1-u5-X38"}],"mis":"K6-1-u5-X38","explanation":["되돌아가는 것이 정상이에요.","처음부터 다시 하는 게 아니에요.","여러 번 돌아온 글이 좋은 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#4','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C45',1,'match','auto','고친 내용과 그 수준을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u5-C45","difficulty":1,"kind":"match","stem":"고친 내용과 그 수준을 알맞게 이으세요.","pairs":[{"l":"결론이 없어서 마지막 문단을 새로 썼다","r":"글 수준"},{"l":"중심 문장만 있어 받쳐 주는 문장 두 줄을 보탰다","r":"문단 수준"},{"l":"「안돼요」를 「안 돼요」로 고쳤다","r":"문장과 낱말 수준"}],"mis":"K6-1-u5-X41","explanation":["글 전체가 달라지는 고침이에요.","한 문단 안의 고침이에요.","낱말 하나의 고침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#5','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C40',2,'mc','auto','점검하고 조정하기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06']::text[],false,'{"seq":5,"concept":"K6-1-u5-C40","difficulty":2,"kind":"mc","stem":"점검하고 조정하기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기 과정 다섯 단계 어디에서나 일어나며 쓰는 도중에 방향을 다시 잡는 일이다","correct":true},{"t":"글을 다 쓴 뒤에 한 번 채점하는 일이다","mis":"K6-1-u5-X36"},{"t":"고쳐쓰기 단계에서만 하는 일이다","mis":"K6-1-u5-X36"},{"t":"글씨와 분량을 재는 일이다","mis":"K6-1-u5-X06"}],"explanation":["채점이 아니에요.","어느 단계에서나 해요.","방향을 다시 잡는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#6','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C43',2,'mc','auto','계획하기를 점검하는 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":6,"concept":"K6-1-u5-C43","difficulty":2,"kind":"mc","stem":"계획하기를 점검하는 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 읽을 사람이 누구인지 정했나요?","correct":true},{"t":"띄어쓰기가 틀리지 않게 썼나요?","mis":"K6-1-u5-X39"},{"t":"문장과 문장이 자연스럽게 이어지나요?","mis":"K6-1-u5-X39"},{"t":"관련 있는 내용끼리 묶었나요?","mis":"K6-1-u5-X39"}],"explanation":["띄어쓰기는 고쳐쓰기에서 봐요.","문장 잇기는 표현과 고쳐쓰기예요.","계획하기는 읽을 사람을 정했는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#7','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C44',2,'ox','auto','다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 돼요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":7,"concept":"K6-1-u5-C44","difficulty":2,"kind":"ox","stem":"다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 돼요.","answer":"O","reason_options":[{"t":"이 단원이 재는 것은 완성된 글의 흠이 아니라 고쳐 가는 과정이기 때문에","correct":true},{"t":"고치려면 반드시 새 종이에 전부 다시 써야 하기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["새 종이가 꼭 필요하지 않아요.","한 군데만 고쳐도 점검이에요.","과정을 보는 단원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#8','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C46',2,'mc','auto','문장과 낱말 수준에서 살필 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42']::text[],false,'{"seq":8,"concept":"K6-1-u5-C46","difficulty":2,"kind":"mc","stem":"문장과 낱말 수준에서 살필 것은 어느 것인가요?","options":[{"t":"띄어쓰기와 맞춤법이 바른가","correct":true},{"t":"문단의 차례를 바꿔야 하는가","mis":"K6-1-u5-X41"},{"t":"서론에 주장이 드러나는가","mis":"K6-1-u5-X41"},{"t":"띄어쓰기는 글쓰기와 관계없으니 살피지 않는다","mis":"K6-1-u5-X42"}],"explanation":["문단 차례는 더 큰 수준이에요.","주장은 글 수준에서 봐요.","낱말도 민감하게 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#9','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C43',2,'mc','auto','표현하기를 점검할 때의 잣대로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X35','K6-1-u5-X06','K6-1-u5-X25']::text[],false,'{"seq":9,"concept":"K6-1-u5-C43","difficulty":2,"kind":"mc","stem":"표현하기를 점검할 때의 잣대로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람이 알아듣는가","correct":true},{"t":"내가 읽어서 매끄러운가","mis":"K6-1-u5-X35"},{"t":"글이 길게 쓰였는가","mis":"K6-1-u5-X06"},{"t":"어려운 낱말이 많은가","mis":"K6-1-u5-X25"}],"explanation":["나만 매끄러우면 안 돼요.","길이는 잣대가 아니에요.","잣대는 읽을 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_basic#10','kor',6,1,'u5','L10','g6_1_kor_u5_L10_basic','lesson_basic','K6-1-u5-C45',3,'mc','auto','「큰 것부터 손보면 헛수고가 줄어든다」는 말의 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42']::text[],false,'{"seq":10,"concept":"K6-1-u5-C45","difficulty":3,"kind":"mc","stem":"「큰 것부터 손보면 헛수고가 줄어든다」는 말의 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"문단을 통째로 지울 참이라면 그 안의 맞춤법을 먼저 고칠 까닭이 없기 때문이다","correct":true},{"t":"맞춤법을 가장 먼저 고쳐야 하기 때문이다","mis":"K6-1-u5-X41"},{"t":"작은 것은 고치지 않아도 되기 때문이다","mis":"K6-1-u5-X42"},{"t":"반드시 이 차례로만 고쳐야 하기 때문이다","mis":"K6-1-u5-X41"}],"explanation":["맞춤법부터가 아니에요.","작은 것도 고쳐요.","꼭 이 차례일 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#1','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C40',2,'mc','auto','과정을 점검하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u5-X36']::text[],false,'{"seq":1,"concept":"K6-1-u5-C40","difficulty":2,"kind":"mc","stem":"과정을 점검하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다 쓴 글에 점수를 매겨 다른 친구와 견줄 수 있다","correct":true},{"t":"어느 단계를 건너뛰었는지 보인다","mis":"K6-1-u5-X36"},{"t":"쓰는 도중에 고칠 점을 찾을 수 있다","mis":"K6-1-u5-X36"},{"t":"남은 부분을 다르게 써 나갈 수 있다","mis":"K6-1-u5-X36"}],"explanation":["되돌아보는 좋은 점이에요.","고칠 곳을 찾는 좋은 점이에요.","점검은 채점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#2','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',2,'ox','auto','고쳐쓰기는 반드시 글 수준 → 문단 수준 → 문장과 낱말 수준의 차례로만 해야 해요.',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":2,"concept":"K6-1-u5-C45","difficulty":2,"kind":"ox","stem":"고쳐쓰기는 반드시 글 수준 → 문단 수준 → 문장과 낱말 수준의 차례로만 해야 해요.","answer":"X","reason_options":[{"t":"큰 것부터가 좋지만 눈에 띄는 곳부터 손대도 되기 때문에","correct":true},{"t":"차례를 어기면 고친 것이 아니기 때문에","mis":"K6-1-u5-X41"}],"mis":"K6-1-u5-X41","explanation":["큰 것부터가 헛수고를 줄여요.","그래도 반드시는 아니에요.","어느 수준부터 손대도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#3','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C43',3,'mc','auto','내용 생성하기를 점검할 때 「아는 것부터 먼저 꺼냈는가」를 묻는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X31']::text[],false,'{"seq":3,"concept":"K6-1-u5-C43","difficulty":3,"kind":"mc","stem":"내용 생성하기를 점검할 때 「아는 것부터 먼저 꺼냈는가」를 묻는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"아는 것을 꺼내 보아야 무엇이 모자란지 보이고, 그다음에 자료를 찾아야 헤매지 않기 때문이다","correct":true},{"t":"아는 것만으로 글을 다 쓸 수 있기 때문이다","mis":"K6-1-u5-X09"},{"t":"자료는 찾지 않는 것이 좋기 때문이다","mis":"K6-1-u5-X23"},{"t":"문장을 먼저 다듬어야 하기 때문이다","mis":"K6-1-u5-X31"}],"explanation":["모자란 곳은 자료로 채워요.","자료도 찾아요.","지금은 꺼내는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#4','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C43',3,'error','auto','점검 질문을 단계에 붙였어요. 잘못 붙인 것은 누구의 것인가요?',ARRAY['K6-1-u5-X39','K6-1-u5-X35']::text[],false,'{"seq":4,"concept":"K6-1-u5-C43","difficulty":3,"kind":"error","stem":"점검 질문을 단계에 붙였어요. 잘못 붙인 것은 누구의 것인가요?","options":[{"t":"슬아 — 계획하기: 「맞춤법을 틀리지 않게 썼나요?」","correct":true,"mis_target":"K6-1-u5-X39"},{"t":"민찬 — 내용 조직하기: 「관련 있는 내용끼리 묶었나요?」","mis":"K6-1-u5-X39"},{"t":"규리 — 표현하기: 「읽을 사람이 이해하기 쉽게 썼나요?」","mis":"K6-1-u5-X35"}],"explanation":["민찬은 조직하기에 맞게 붙였어요.","규리는 표현하기에 맞게 붙였어요.","맞춤법은 계획하기의 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#5','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C44',3,'mc','auto','「고칠 곳이 이렇게 많다니, 내 글은 망했구나.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X40','K6-1-u5-X36','K6-1-u5-X07']::text[],false,'{"seq":5,"concept":"K6-1-u5-C44","difficulty":3,"kind":"mc","stem":"「고칠 곳이 이렇게 많다니, 내 글은 망했구나.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"고칠 곳을 찾아냈다는 건 네가 볼 줄 알게 되었다는 뜻이야","correct":true},{"t":"고칠 곳이 많으면 버리고 새로 쓰는 게 나아","mis":"K6-1-u5-X40"},{"t":"점검은 흠을 세는 일이니 어쩔 수 없어","mis":"K6-1-u5-X36"},{"t":"처음부터 잘 썼어야지","mis":"K6-1-u5-X07"}],"explanation":["버리지 않고 고쳐 가요.","점검은 흠 세기가 아니에요.","과정을 익히는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#6','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C46',3,'mc','auto','「도서관 에서 빌린책은 꼭 돌려 줍시다.」를 문장과 낱말 수준에서 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":6,"concept":"K6-1-u5-C46","difficulty":3,"kind":"mc","stem":"「도서관 에서 빌린책은 꼭 돌려 줍시다.」를 문장과 낱말 수준에서 바르게 고친 것은 어느 것인가요?","options":[{"t":"「도서관에서 빌린 책은 꼭 돌려줍시다.」","correct":true},{"t":"「도서관 에서 빌린책은 꼭 돌려줍시다.」","mis":"K6-1-u5-X42"},{"t":"「도서관에서 빌린책은 꼭 돌려 줍시다.」","mis":"K6-1-u5-X42"},{"t":"「도서관 에서 빌린 책은 꼭 돌려 줍시다.」","mis":"K6-1-u5-X42"}],"explanation":["「도서관에서」는 붙여 써요.","「빌린 책」은 띄어 써요.","「돌려줍시다」는 한 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#7','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C42',3,'mc','auto','「여러 번 돌아온 글이 좋은 글이다」라는 말과 가장 가까운 것은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X30','K6-1-u5-X41']::text[],false,'{"seq":7,"concept":"K6-1-u5-C42","difficulty":3,"kind":"mc","stem":"「여러 번 돌아온 글이 좋은 글이다」라는 말과 가장 가까운 것은 어느 것인가요?","options":[{"t":"쓰다가 근거가 약한 것을 알고 내용 생성하기로 돌아가 자료를 보탠 글","correct":true},{"t":"한 번에 끝까지 쓰고 다시 보지 않은 글","mis":"K6-1-u5-X38"},{"t":"계획을 바꾸지 않으려고 어긋난 내용을 그대로 둔 글","mis":"K6-1-u5-X30"},{"t":"맞춤법만 여러 번 고친 글","mis":"K6-1-u5-X41"}],"explanation":["다시 보지 않으면 고칠 곳을 놓쳐요.","어긋난 계획을 붙들면 안 돼요.","되돌아가 보탤 때 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#8','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',4,'mc','auto','글을 점검해 보니 「결론이 없음 · ③문단에 뒷받침 문장이 없음 · 맞춤법 두 군데」가 나왔어요. 헛수고를 줄이는 고칠 차례로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X42','K6-1-u5-X40']::text[],false,'{"seq":8,"concept":"K6-1-u5-C45","difficulty":4,"kind":"mc","stem":"글을 점검해 보니 「결론이 없음 · ③문단에 뒷받침 문장이 없음 · 맞춤법 두 군데」가 나왔어요. 헛수고를 줄이는 고칠 차례로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결론을 새로 쓰고 → ③문단에 뒷받침 문장을 보태고 → 맞춤법을 고친다","correct":true},{"t":"맞춤법을 고치고 → 결론을 쓰고 → 뒷받침 문장을 보탠다","mis":"K6-1-u5-X41"},{"t":"맞춤법만 고치고 나머지는 그대로 둔다","mis":"K6-1-u5-X42"},{"t":"글을 버리고 새 종이에 처음부터 다시 쓴다","mis":"K6-1-u5-X40"}],"explanation":["작은 것부터면 헛수고가 생길 수 있어요.","큰 고침도 필요해요.","버리지 않고 크기대로 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#9','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C42',4,'essay','teacher','「쓰기는 되돌아오는 성질을 지닌다」는 말을, 내가 쓰는 도중에 앞 단계로 되돌아가는 예를 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C42","difficulty":4,"kind":"essay","stem":"「쓰기는 되돌아오는 성질을 지닌다」는 말을, 내가 쓰는 도중에 앞 단계로 되돌아가는 예를 들어 설명하세요.","answer_guide":{"answer":"예: 표현하기를 하다가 둘째 이유의 근거가 「다들 그렇대」 같은 짐작뿐이라는 것을 알게 되면, 내용 생성하기로 돌아가 우리 반 설문을 하고 출처를 적어 근거를 바꾼다. 또 쓰다가 읽을 사람이 동생들이라는 것이 떠오르면 계획하기로 돌아가 말투를 고친다. 이렇게 되돌아가는 것은 실패가 아니라 쓰기의 성질이고, 되돌아간 단계에서 글이 좋아진다.","scoring_points":["쓰는 도중 되돌아가는 예를 들었는가","어느 단계로 왜 돌아가는지 썼는가","되돌아감이 실패가 아니라는 점을 썼는가"]},"explanation":["쓰다가 생길 일을 떠올려요.","돌아갈 단계를 정해요.","되돌아감의 뜻을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L10_challenge#10','kor',6,1,'u5','L10','g6_1_kor_u5_L10_challenge','lesson_challenge','K6-1-u5-C45',4,'essay','teacher','지난 시간에 쓴 주장하는 글을 고친다고 할 때, 글 · 문단 · 문장과 낱말 수준에서 살펴볼 것을 하나씩 쓰고, 어디부터 손댈지 정해 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C45","difficulty":4,"kind":"essay","stem":"지난 시간에 쓴 주장하는 글을 고친다고 할 때, 글 · 문단 · 문장과 낱말 수준에서 살펴볼 것을 하나씩 쓰고, 어디부터 손댈지 정해 까닭을 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 서론에 주장이 분명히 드러나는가. 문단 수준 — 본론 문단마다 중심 문장을 뒷받침 문장이 받쳐 주는가. 문장과 낱말 수준 — 띄어쓰기와 맞춤법이 바른가. 나는 글 수준부터 손보겠다. 주장이 흐리면 문단이 통째로 바뀔 수 있어 맞춤법을 먼저 고치면 헛수고가 되기 때문이다.","scoring_points":["세 수준에서 살필 것을 하나씩 썼는가","손댈 곳을 정했는가","그렇게 정한 까닭을 썼는가"]},"explanation":["세 크기를 떠올려요.","어디부터 할지 골라요.","까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#1','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C47',1,'mc','auto','실천 활동으로 고르기에 알맞은 문제는 어느 것인가요?',ARRAY['K6-1-u5-X43']::text[],false,'{"seq":1,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"실천 활동으로 고르기에 알맞은 문제는 어느 것인가요?","options":[{"t":"사물함 위에 주인 없는 물건이 쌓인다","correct":true},{"t":"비 오는 날이 너무 많다","mis":"K6-1-u5-X43"},{"t":"방학이 너무 짧다","mis":"K6-1-u5-X43"},{"t":"하늘이 흐리다","mis":"K6-1-u5-X43"}],"explanation":["날씨는 우리 힘으로 바꿀 수 없어요.","방학 길이도 우리가 정할 수 없어요.","우리가 바꿀 수 있고 근거를 댈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#2','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C47',1,'mc','auto','주장으로 알맞은 문장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X27']::text[],false,'{"seq":2,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"주장으로 알맞은 문장은 어느 것인가요?","options":[{"t":"사물함 위에는 물건을 두지 맙시다","correct":true},{"t":"사물함 위에 물건이 많이 쌓여 있습니다","mis":"K6-1-u5-X02"},{"t":"학교 생활을 더 좋게 합시다","mis":"K6-1-u5-X27"},{"t":"우리 모두 노력이 필요합니다","mis":"K6-1-u5-X27"}],"explanation":["문제 상황을 말했어요.","무엇을 하자는지 흐려요.","할 일이 한 문장으로 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#3','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C49',1,'match','auto','네 칸과 그 칸에 들어갈 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u5-C49","difficulty":1,"kind":"match","stem":"네 칸과 그 칸에 들어갈 문장을 알맞게 이으세요.","pairs":[{"l":"의견","r":"사물함 위에는 물건을 두지 맙시다"},{"l":"까닭","r":"떨어지면 다칠 수 있기 때문입니다"},{"l":"사례","r":"사흘 동안 세어 보니 하루 평균 아홉 개였습니다"},{"l":"제안","r":"오늘부터 사물함 위를 비워 둡시다"}],"mis":"K6-1-u5-X45","explanation":["처음은 꺼내는 말이에요.","까닭과 사례가 가운데에 와요.","끝은 다시 밀어 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#4','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',1,'ox','auto','표어를 만들 때 글씨를 크게 하고 알록달록 꾸미기만 하면 근거가 없어도 설득이 돼요.',ARRAY['K6-1-u5-X44']::text[],false,'{"seq":4,"concept":"K6-1-u5-C48","difficulty":1,"kind":"ox","stem":"표어를 만들 때 글씨를 크게 하고 알록달록 꾸미기만 하면 근거가 없어도 설득이 돼요.","answer":"X","reason_options":[{"t":"눈길을 끌 뿐 생각을 바꾸는 것은 확인할 수 있는 근거이기 때문에","correct":true},{"t":"눈에 띄는 것이 곧 설득이기 때문에","mis":"K6-1-u5-X44"}],"mis":"K6-1-u5-X44","explanation":["눈길은 잠깐이에요.","근거가 생각을 바꿔요.","근거 하나는 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#5','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C29',2,'match','auto','예찬이의 이유와 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u5-C29","difficulty":2,"kind":"match","stem":"예찬이의 이유와 근거를 알맞게 이으세요.","pairs":[{"l":"물건이 떨어져 다칠 수 있다","r":"사물함 위 물건을 센 사흘 동안의 관찰 기록"},{"l":"주인을 못 찾고 버려진다","r":"주인을 못 찾은 물건이 절반이 넘는 분실물 기록"},{"l":"청소할 때 손이 더 간다","r":"치우는 데 시간이 더 든다는 청소 담당 선생님 면담"}],"mis":"K6-1-u5-X03","explanation":["다침은 떨어질 물건 수와 이어져요.","잃어버림은 분실물 기록과 이어져요.","청소는 담당 선생님 말씀과 이어져요."],"asset":{"type":"passage","lines":["주장 — 사물함 위에는 물건을 두지 맙시다.","이유 하나 — 물건이 떨어져 다칠 수 있기 때문입니다.","근거 — 우리 층 사물함 위 물건을 사흘 동안 세어 보니 하루 평균 아홉 개였다.","(솔바람반(2026), 「사흘 동안의 사물함 관찰 기록」, 학급 게시판.)","이유 둘 — 주인을 찾지 못한 채 버려지기 때문입니다.","근거 — 지난달 분실물함에 들어온 물건 가운데 절반 넘게 주인을 찾지 못했다.","(○○초등학교(2026), 「사월 분실물 기록」, 학교 안내판.)"],"title":"예찬이 세운 주장과 근거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#6','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',2,'mc','auto','설득의 힘이 가장 센 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X24']::text[],false,'{"seq":6,"concept":"K6-1-u5-C48","difficulty":2,"kind":"mc","stem":"설득의 힘이 가장 센 것은 어느 것인가요?","options":[{"t":"「사흘 동안 하루 평균 아홉 개」라는 관찰 기록을 표어 아래에 붙였다","correct":true},{"t":"표어 글씨를 가장 크게 키웠다","mis":"K6-1-u5-X44"},{"t":"종이를 여러 색으로 알록달록 칠했다","mis":"K6-1-u5-X44"},{"t":"표어를 여러 장 붙였다","mis":"K6-1-u5-X24"}],"explanation":["크기가 설득을 만들지 않아요.","색은 눈길만 끌어요.","확인할 수 있는 사실 하나가 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#7','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C48',2,'mc','auto','주장을 펼치는 방법을 표어로 바꿀 때 지켜야 할 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X26','K6-1-u5-X45']::text[],false,'{"seq":7,"concept":"K6-1-u5-C48","difficulty":2,"kind":"mc","stem":"주장을 펼치는 방법을 표어로 바꿀 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"방법이 바뀌어도 주장 · 이유 · 근거는 그대로 남긴다","correct":true},{"t":"표어는 짧으니 근거를 빼도 된다","mis":"K6-1-u5-X44"},{"t":"표어로 바꾸면 주장도 바꿔야 한다","mis":"K6-1-u5-X26"},{"t":"표어는 길게 써야 한다","mis":"K6-1-u5-X45"}],"explanation":["짧아도 근거 하나는 남겨요.","주장은 그대로예요.","길게 쓸 수 없어 네 칸 짜임을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#8','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C50',2,'ox','auto','주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이에요.',ARRAY['K6-1-u5-X46']::text[],false,'{"seq":8,"concept":"K6-1-u5-C50","difficulty":2,"kind":"ox","stem":"주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이에요.","answer":"O","reason_options":[{"t":"내가 알린 대로 내가 먼저 해 보는 것이 가장 센 근거이기 때문에","correct":true},{"t":"주장을 알리고 나면 할 일이 끝나기 때문에","mis":"K6-1-u5-X46"}],"mis":"K6-1-u5-X46","explanation":["알리고 끝이 아니에요.","먼저 해 보아요.","생활에서 달라져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#9','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C49',2,'mc','auto','네 칸 짜임(의견 · 까닭 · 사례 · 제안)은 무엇을 줄인 틀인가요?',ARRAY['K6-1-u5-X37','K6-1-u5-X21','K6-1-u5-X41']::text[],false,'{"seq":9,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"네 칸 짜임(의견 · 까닭 · 사례 · 제안)은 무엇을 줄인 틀인가요?","options":[{"t":"서론 · 본론 · 결론","correct":true},{"t":"쓰기 과정 다섯 단계","mis":"K6-1-u5-X37"},{"t":"출처의 네 가지","mis":"K6-1-u5-X21"},{"t":"고쳐쓰기의 세 수준","mis":"K6-1-u5-X41"}],"explanation":["쓰기 과정과 다른 틀이에요.","출처의 네 칸과 달라요.","글의 짜임을 짧게 줄인 틀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_basic#10','kor',6,1,'u5','L12','g6_1_kor_u5_L12_basic','lesson_basic','K6-1-u5-C51',3,'mc','auto','「어떤 조사에 따르면, 읽지 않는 책을 둔 학생이 많다고 한다.」의 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X25','K6-1-u5-X23']::text[],false,'{"seq":10,"concept":"K6-1-u5-C51","difficulty":3,"kind":"mc","stem":"「어떤 조사에 따르면, 읽지 않는 책을 둔 학생이 많다고 한다.」의 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 · 언제 · 무엇을 · 어디에 실었는지 없어 읽는 사람이 확인할 길이 없다","correct":true},{"t":"조사라는 말이 들어 있으니 문제가 없다","mis":"K6-1-u5-X47"},{"t":"문장이 짧아서 문제가 된다","mis":"K6-1-u5-X25"},{"t":"조사 결과는 근거가 될 수 없다","mis":"K6-1-u5-X23"}],"explanation":["「조사」라는 말만으로는 출처가 아니에요.","길이 문제가 아니에요.","조사 결과도 출처가 있으면 근거예요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#1','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C47',2,'mc','auto','주장을 한 문장으로 만들어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X24','K6-1-u5-X04','K6-1-u5-X02']::text[],false,'{"seq":1,"concept":"K6-1-u5-C47","difficulty":2,"kind":"mc","stem":"주장을 한 문장으로 만들어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"길어질수록 흐려져 무엇을 할지 모르게 되기 때문이다","correct":true},{"t":"짧은 글이 늘 더 좋은 글이기 때문이다","mis":"K6-1-u5-X24"},{"t":"이유와 근거를 빼기 위해서이다","mis":"K6-1-u5-X04"},{"t":"주장은 문제 상황을 말하는 문장이기 때문이다","mis":"K6-1-u5-X02"}],"explanation":["길이 자체가 좋고 나쁨은 아니에요.","이유와 근거는 그대로예요.","할 일이 또렷해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#2','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',3,'error','auto','자기가 고른 표현 방법에 대해 한 말이에요. 알맞지 않은 말은 누구의 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X26']::text[],false,'{"seq":2,"concept":"K6-1-u5-C48","difficulty":3,"kind":"error","stem":"자기가 고른 표현 방법에 대해 한 말이에요. 알맞지 않은 말은 누구의 것인가요?","options":[{"t":"규리 — 「만화는 그림이 다 말해 주니까 근거는 넣지 않을래.」","correct":true,"mis_target":"K6-1-u5-X44"},{"t":"예찬 — 「표어 아래에 관찰 기록 한 줄을 붙일래.」","mis":"K6-1-u5-X44"},{"t":"슬아 — 「노랫말을 바꿔도 주장과 근거는 그대로 넣을래.」","mis":"K6-1-u5-X26"}],"explanation":["예찬은 근거를 남겼어요.","슬아도 근거를 남겼어요.","만화에도 근거 하나는 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#3','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C47',3,'mc','auto','「급식실 앞에서 줄이 엉킨다」는 문제를 실천 활동으로 고른 것이 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X43','K6-1-u5-X09','K6-1-u5-X29']::text[],false,'{"seq":3,"concept":"K6-1-u5-C47","difficulty":3,"kind":"mc","stem":"「급식실 앞에서 줄이 엉킨다」는 문제를 실천 활동으로 고른 것이 알맞은 까닭은 어느 것인가요?","options":[{"t":"우리 힘으로 바꿀 수 있고, 직접 세거나 물어 근거를 댈 수 있기 때문이다","correct":true},{"t":"우리가 바꿀 수 없는 일이라 더 중요하기 때문이다","mis":"K6-1-u5-X43"},{"t":"근거가 없어도 다들 알기 때문이다","mis":"K6-1-u5-X09"},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u5-X29"}],"explanation":["바꿀 수 있어야 실천이 돼요.","근거가 있어야 해요.","여럿에게 걸린 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#4','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C49',3,'mc','auto','「오늘부터 사물함 위를 비워 둡시다」가 들어갈 칸은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":4,"concept":"K6-1-u5-C49","difficulty":3,"kind":"mc","stem":"「오늘부터 사물함 위를 비워 둡시다」가 들어갈 칸은 어느 것인가요?","options":[{"t":"제안","correct":true},{"t":"의견","mis":"K6-1-u5-X45"},{"t":"까닭","mis":"K6-1-u5-X45"},{"t":"사례","mis":"K6-1-u5-X45"}],"explanation":["의견은 처음 꺼내는 말이에요.","까닭은 왜 그런지예요.","그러니 이렇게 하자는 말은 제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#5','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C51',3,'mc','auto','「어떤 선생님께서 … 궁금해한다고 하셨다」를 믿을 수 있는 근거로 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X19','K6-1-u5-X16']::text[],false,'{"seq":5,"concept":"K6-1-u5-C51","difficulty":3,"kind":"mc","stem":"「어떤 선생님께서 … 궁금해한다고 하셨다」를 믿을 수 있는 근거로 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구에게 · 언제 · 무엇에 대해 여쭈었는지와 실린 곳을 갖추어 출처를 밝힌다","correct":true},{"t":"「어떤 선생님」을 「많은 선생님」으로 바꾼다","mis":"K6-1-u5-X47"},{"t":"선생님 말씀을 더 세게 바꿔 쓴다","mis":"K6-1-u5-X19"},{"t":"출처 없이 내 생각인 것처럼 쓴다","mis":"K6-1-u5-X16"}],"explanation":["「많은」도 확인할 수 없어요.","뜻을 비틀면 안 돼요.","네 가지를 갖추어야 확인할 수 있어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#6','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C50',3,'mc','auto','「말한 대로 해 보기」를 바르게 한 것은 어느 것인가요?',ARRAY['K6-1-u5-X46']::text[],false,'{"seq":6,"concept":"K6-1-u5-C50","difficulty":3,"kind":"mc","stem":"「말한 대로 해 보기」를 바르게 한 것은 어느 것인가요?","options":[{"t":"일주일 동안 사물함 위를 비웠는지 날마다 표시하고, 무엇이 달라졌는지 한 줄로 적었다","correct":true},{"t":"표어를 붙인 뒤 할 일은 다 했다고 여겼다","mis":"K6-1-u5-X46"},{"t":"친구들에게만 하라고 하고 나는 하지 않았다","mis":"K6-1-u5-X46"},{"t":"지켰는지 표시하지 않고 기억에만 맡겼다","mis":"K6-1-u5-X46"}],"explanation":["알리고 끝이 아니에요.","내가 먼저 해 봐요.","날마다 표시해 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#7','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C52',2,'mc','auto','밤사이 사람들 모르게 내린 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":7,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"밤사이 사람들 모르게 내린 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"도둑눈","correct":true},{"t":"숫눈","mis":"K6-1-u5-X48"},{"t":"가루눈","mis":"K6-1-u5-X48"},{"t":"여우비","mis":"K6-1-u5-X48"}],"explanation":["숫눈은 아무도 밟지 않은 눈이에요.","가루눈은 가루처럼 잘게 내리는 눈이에요.","모르게 내렸으니 도둑눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#8','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',4,'mc','auto','사물함 표어 두 가지 가운데 더 설득력 있는 것을 고르고 그 까닭을 바르게 말한 것은 어느 것인가요? ㄱ 「사물함 위를 비웁시다!!!」(커다란 글씨) ㄴ 「사물함 위를 비웁시다 — 사흘 동안 하루 평균 아홉 개가 떨어질 뻔했어요」',ARRAY['K6-1-u5-X44','K6-1-u5-X24']::text[],false,'{"seq":8,"concept":"K6-1-u5-C48","difficulty":4,"kind":"mc","stem":"사물함 표어 두 가지 가운데 더 설득력 있는 것을 고르고 그 까닭을 바르게 말한 것은 어느 것인가요? ㄱ 「사물함 위를 비웁시다!!!」(커다란 글씨) ㄴ 「사물함 위를 비웁시다 — 사흘 동안 하루 평균 아홉 개가 떨어질 뻔했어요」","options":[{"t":"ㄴ — 읽는 사람이 「정말?」 하고 물을 때 보여 줄 사실이 있기 때문이다","correct":true},{"t":"ㄱ — 글씨가 커서 멀리서도 보이기 때문이다","mis":"K6-1-u5-X44"},{"t":"ㄱ — 느낌표가 많아 힘이 느껴지기 때문이다","mis":"K6-1-u5-X44"},{"t":"ㄴ — 글자가 많아 더 길기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["크기는 눈길만 끌어요.","느낌표는 근거가 아니에요.","길이가 아니라 사실이 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#9','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C49',4,'essay','teacher','「특별실을 쓰고 뒷정리를 하지 않고 나간다」는 문제로 네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u5-C49","difficulty":4,"kind":"essay","stem":"「특별실을 쓰고 뒷정리를 하지 않고 나간다」는 문제로 네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 의견 — 특별실을 쓰고 나갈 때 뒷정리를 합시다. 까닭 — 다음에 쓰는 반이 정리부터 하느라 수업 시간이 줄기 때문입니다. 사례 — 우리 반이 일주일 동안 과학실에 들어갈 때마다 세어 보니 다섯 번 가운데 네 번은 의자가 흩어져 있었습니다. 제안 — 나가기 전에 의자 넣기와 재료 정리를 함께 합시다.","scoring_points":["의견을 할 일이 드러나는 한 문장으로 썼는가","까닭과 확인할 수 있는 사례를 썼는가","제안으로 다시 밀어 주었는가"]},"explanation":["하고 싶은 말을 먼저 꺼내요.","까닭과 사례로 받쳐요.","그러니 이렇게 하자고 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_L12_challenge#10','kor',6,1,'u5','L12','g6_1_kor_u5_L12_challenge','lesson_challenge','K6-1-u5-C48',4,'essay','teacher','「사람을 움직이는 것은 목소리의 크기가 아니라 근거다」라는 말을, 이 단원에서 배운 것과 이어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C48","difficulty":4,"kind":"essay","stem":"「사람을 움직이는 것은 목소리의 크기가 아니라 근거다」라는 말을, 이 단원에서 배운 것과 이어 설명하세요.","answer_guide":{"answer":"예: 큰 글씨나 화려한 그림, 큰 목소리는 잠깐 눈길을 끌 뿐 왜 그래야 하는지 알려 주지 못한다. 이 단원에서는 주장 아래에 이유를 세우고, 그 이유를 누구나 확인할 수 있는 근거와 출처로 받쳐야 한다고 배웠다. 「사흘 동안 하루 평균 아홉 개」 같은 사실 하나가 있어야 읽는 사람이 확인하고 생각을 바꾼다. 그래서 어떤 방법으로 펼치든 근거 하나는 남겨야 한다.","scoring_points":["크기나 꾸밈만으로는 설득되지 않는 까닭을 썼는가","이유와 근거 · 출처의 역할을 이어 썼는가","근거를 남겨야 한다는 점을 정리했는가"]},"explanation":["눈에 띄는 것과 설득을 견줘요.","근거의 힘을 떠올려요.","배운 것과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#1','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C1',1,'mc','auto','어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글을 무엇이라고 하나요?',ARRAY['K6-1-u5-X01']::text[],false,'{"seq":1,"concept":"K6-1-u5-C1","difficulty":1,"kind":"mc","stem":"어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글을 무엇이라고 하나요?","options":[{"t":"주장하는 글","correct":true},{"t":"일기","mis":"K6-1-u5-X01"},{"t":"견학 기록문","mis":"K6-1-u5-X01"},{"t":"이야기","mis":"K6-1-u5-X01"}],"explanation":["일기는 마음을 적어요.","견학 기록문은 보고 들은 것을 써요.","설득하려는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#2','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C11',1,'mc','auto','주장하는 글에서 문제를 제기하고 주장을 밝히는 부분은 어디인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":2,"concept":"K6-1-u5-C11","difficulty":1,"kind":"mc","stem":"주장하는 글에서 문제를 제기하고 주장을 밝히는 부분은 어디인가요?","options":[{"t":"서론","correct":true},{"t":"본론","mis":"K6-1-u5-X10"},{"t":"결론","mis":"K6-1-u5-X10"},{"t":"제목","mis":"K6-1-u5-X10"}],"explanation":["본론은 펼쳐요.","결론은 모아요.","서론에서 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#3','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C17',1,'mc','auto','남의 것을 가져다 쓰면서 출처를 밝히지 않는 것을 무엇이라고 하나요?',ARRAY['K6-1-u5-X17']::text[],false,'{"seq":3,"concept":"K6-1-u5-C17","difficulty":1,"kind":"mc","stem":"남의 것을 가져다 쓰면서 출처를 밝히지 않는 것을 무엇이라고 하나요?","options":[{"t":"표절","correct":true},{"t":"인용","mis":"K6-1-u5-X17"},{"t":"요약","mis":"K6-1-u5-X17"},{"t":"주장","mis":"K6-1-u5-X17"}],"explanation":["인용은 출처를 밝히며 가져와요.","요약은 줄이는 거예요.","출처를 숨기면 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#4','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C21',1,'ox','auto','출처에는 만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳이 들어가요.',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"ox","stem":"출처에는 만든 사람 · 만든 시기 · 자료의 이름 · 실린 곳이 들어가요.","answer":"O","reason_options":[{"t":"네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있기 때문에","correct":true},{"t":"자료의 이름만 있으면 충분하기 때문에","mis":"K6-1-u5-X21"}],"mis":"K6-1-u5-X21","explanation":["네 가지예요.","하나라도 빠지면 찾기 어려워요.","확인할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#5','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C30',1,'ox','auto','「아마 다들 그럴 것이다」라는 짐작도 근거가 될 수 있어요.',ARRAY['K6-1-u5-X09']::text[],false,'{"seq":5,"concept":"K6-1-u5-C30","difficulty":1,"kind":"ox","stem":"「아마 다들 그럴 것이다」라는 짐작도 근거가 될 수 있어요.","answer":"X","reason_options":[{"t":"누구나 찾아가 확인할 수 있는 객관적인 자료가 아니기 때문에","correct":true},{"t":"많은 사람이 그렇게 여기면 객관적이기 때문에","mis":"K6-1-u5-X09"}],"mis":"K6-1-u5-X09","explanation":["짐작은 확인할 수 없어요.","객관적인 자료가 아니에요.","확인할 수 있어야 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#6','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C34',1,'mc','auto','글을 쓰는 목적 · 주제 · 읽을 사람을 정하는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C34","difficulty":1,"kind":"mc","stem":"글을 쓰는 목적 · 주제 · 읽을 사람을 정하는 단계는 어느 것인가요?","options":[{"t":"계획하기","correct":true},{"t":"내용 생성하기","mis":"K6-1-u5-X37"},{"t":"표현하기","mis":"K6-1-u5-X37"},{"t":"고쳐쓰기","mis":"K6-1-u5-X37"}],"explanation":["내용 생성하기는 쓸 거리를 모아요.","표현하기는 문장을 써요.","정하는 단계는 계획하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#7','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',1,'ox','auto','글을 쓰다가 앞 단계로 되돌아가는 것은 쓰기의 성질이에요.',ARRAY['K6-1-u5-X38']::text[],false,'{"seq":7,"concept":"K6-1-u5-C42","difficulty":1,"kind":"ox","stem":"글을 쓰다가 앞 단계로 되돌아가는 것은 쓰기의 성질이에요.","answer":"O","reason_options":[{"t":"점검과 조정이 어느 단계에서나 일어나 되돌아올 수 있기 때문에","correct":true},{"t":"앞으로만 가야 좋은 글이 되기 때문에","mis":"K6-1-u5-X38"}],"mis":"K6-1-u5-X38","explanation":["되돌아가도 괜찮아요.","어느 단계에서나 점검해요.","되돌아간 단계에서 글이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#8','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C52',1,'mc','auto','볕이 난 날 잠깐 오다가 그치는 비를 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"볕이 난 날 잠깐 오다가 그치는 비를 가리키는 우리말은 어느 것인가요?","options":[{"t":"여우비","correct":true},{"t":"밤비","mis":"K6-1-u5-X48"},{"t":"먼지잼","mis":"K6-1-u5-X48"},{"t":"도둑눈","mis":"K6-1-u5-X48"}],"explanation":["밤비는 밤에 내리는 비예요.","먼지잼은 아주 조금 오는 비예요.","볕 속에 잠깐 오는 비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#9','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C51',2,'mc','auto','「헌책 나눔 상자」 글에서 출처가 제대로 밝혀지지 않은 곳은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X02']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"「헌책 나눔 상자」 글에서 출처가 제대로 밝혀지지 않은 곳은 어느 것인가요?","options":[{"t":"어떤 조사에 따르면","correct":true},{"t":"솔바람반(2026), 「헌책 이용 설문」, 학급 게시판","mis":"K6-1-u5-X47"},{"t":"우리 반 스물다섯 명 가운데 스물한 명","mis":"K6-1-u5-X47"},{"t":"헌책 나눔 상자를 두어 책이 다시 읽히게 하자","mis":"K6-1-u5-X02"}],"explanation":["네 가지를 갖춘 출처예요.","출처가 붙은 조사 결과예요.","누가 · 언제 한 조사인지 없어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#10','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C9',2,'mc','auto','「헌책 나눔 상자」 글의 이유 가운데 주장과 이어지는 것은 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":10,"concept":"K6-1-u5-C9","difficulty":2,"kind":"mc","stem":"「헌책 나눔 상자」 글의 이유 가운데 주장과 이어지는 것은 어느 것인가요?","options":[{"t":"책이 필요한 사람에게 옮겨 가기 때문이다","correct":true},{"t":"현관이 넓기 때문이다","mis":"K6-1-u5-X08"},{"t":"책을 많이 읽으면 키가 크기 때문이다","mis":"K6-1-u5-X08"},{"t":"헌책은 값이 싸기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["현관 넓이는 이유가 아니에요.","주장과 이어지지 않아요.","나눔 상자의 쓸모와 이어져요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#11','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C2',2,'mc','auto','우재 초고의 주장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X03']::text[],false,'{"seq":11,"concept":"K6-1-u5-C2","difficulty":2,"kind":"mc","stem":"우재 초고의 주장은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 서야 한다","correct":true},{"t":"점심시간 급식실 앞은 늘 북적인다","mis":"K6-1-u5-X02"},{"t":"밀치다 넘어질 일이 줄기 때문이다","mis":"K6-1-u5-X03"},{"t":"열다섯 명이 밀린 적이 있다고 답했다","mis":"K6-1-u5-X03"}],"explanation":["문제 상황이에요.","이유예요.","하자고 내세운 말이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#12','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',2,'mc','auto','우재 초고 앞부분에서 통일성을 깨는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":12,"concept":"K6-1-u5-C37","difficulty":2,"kind":"mc","stem":"우재 초고 앞부분에서 통일성을 깨는 문장은 어느 것인가요?","options":[{"t":"급식실 반찬은 골고루 먹어야 키가 큰다","correct":true},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X33"},{"t":"먼저 온 사람이 먼저 먹을 수 있기 때문이다","mis":"K6-1-u5-X33"},{"t":"줄이 두세 갈래로 엉켜 서로 밀치기도 한다","mis":"K6-1-u5-X33"}],"explanation":["글의 주장이에요.","줄서기와 이어진 이유예요.","옳은 말이어도 줄서기와 이어지지 않아요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#13','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C46',2,'mc','auto','우재 초고 뒷부분에서 띄어쓰기를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":13,"concept":"K6-1-u5-C46","difficulty":2,"kind":"mc","stem":"우재 초고 뒷부분에서 띄어쓰기를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「한줄로」 → 「한 줄로」","correct":true},{"t":"「점심시간의」 → 「점심 시간의」","mis":"K6-1-u5-X42"},{"t":"「살펴보았다」 → 「살펴 보았다」","mis":"K6-1-u5-X42"},{"t":"「편안한」 → 「편 안한」","mis":"K6-1-u5-X42"}],"explanation":["「점심시간」은 붙여 써요.","「살펴보다」는 한 낱말이에요.","「한 줄」은 띄어 써요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#14','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',2,'mc','auto','대화에서 하영이가 「처음부터가 아니라 잠깐 돌아가는 거야」라고 한 말의 뜻은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X07']::text[],false,'{"seq":14,"concept":"K6-1-u5-C42","difficulty":2,"kind":"mc","stem":"대화에서 하영이가 「처음부터가 아니라 잠깐 돌아가는 거야」라고 한 말의 뜻은 어느 것인가요?","options":[{"t":"앞 단계로 되돌아가는 것은 실패가 아니라 쓰기의 성질이다","correct":true},{"t":"되돌아가면 처음부터 다시 써야 한다","mis":"K6-1-u5-X38"},{"t":"다 쓴 글은 고치지 않아야 한다","mis":"K6-1-u5-X07"},{"t":"되돌아가는 것은 계획이 틀렸다는 뜻이다","mis":"K6-1-u5-X38"}],"explanation":["처음부터가 아니에요.","고쳐도 괜찮아요.","되돌아가는 것은 정상이에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#15','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C49',2,'mc','auto','하영이의 네 칸 글에서 「우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다」가 들어간 칸은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":15,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"하영이의 네 칸 글에서 「우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다」가 들어간 칸은 어느 것인가요?","options":[{"t":"사례","correct":true},{"t":"의견","mis":"K6-1-u5-X45"},{"t":"까닭","mis":"K6-1-u5-X45"},{"t":"제안","mis":"K6-1-u5-X45"}],"explanation":["의견은 하고 싶은 말이에요.","까닭은 왜 그런지예요.","조사 결과는 사례 칸에 들어가요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#16','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C52',2,'match','auto','비와 눈이 내린 날의 문장과 알맞은 우리말을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"match","stem":"비와 눈이 내린 날의 문장과 알맞은 우리말을 이으세요.","pairs":[{"l":"ㄱ","r":"여우비"},{"l":"ㄴ","r":"도둑눈"},{"l":"ㄷ","r":"먼지잼"},{"l":"ㄹ","r":"숫눈"}],"mis":"K6-1-u5-X48","explanation":["볕 속에 잠깐 온 비예요.","모르게 내린 눈이에요.","조금 온 비와 밟지 않은 눈이에요."],"asset":{"type":"passage","lines":["ㄱ. 볕이 쨍한데 잠깐 비가 오다 그쳤다.","ㄴ. 아침에 일어나 보니 밤사이 아무도 모르게 눈이 쌓여 있었다.","ㄷ. 먼지나 겨우 가라앉힐 만큼 비가 아주 조금 내렸다.","ㄹ. 운동장에 쌓인 눈을 아직 아무도 밟지 않았다."],"title":"비와 눈이 내린 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#17','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C15',3,'mc','auto','「우산꽂이에 꽂자」는 글에 출처를 갖춘 「우리 반 아침 독서 설문」을 근거로 붙였어요. 이 근거를 판단한 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X15']::text[],false,'{"seq":17,"concept":"K6-1-u5-C15","difficulty":3,"kind":"mc","stem":"「우산꽂이에 꽂자」는 글에 출처를 갖춘 「우리 반 아침 독서 설문」을 근거로 붙였어요. 이 근거를 판단한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"출처는 갖추었지만 이유와 관련이 없어 타당한 근거가 아니다","correct":true},{"t":"출처가 있으니 타당한 근거이다","mis":"K6-1-u5-X14"},{"t":"설문이니 어느 이유에 붙여도 된다","mis":"K6-1-u5-X14"},{"t":"그냥 그럴 것 같아 타당하다","mis":"K6-1-u5-X15"}],"explanation":["출처가 곧 타당함은 아니에요.","이유와 이어져야 해요.","판단에는 까닭이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#18','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C19',3,'mc','auto','사서 선생님이 「늦게 온 책을 다시 정리하는 데 시간이 많이 든다」고 하셨어요. 출처를 밝혔어도 잘못 옮긴 것은 어느 것인가요?',ARRAY['K6-1-u5-X19']::text[],false,'{"seq":18,"concept":"K6-1-u5-C19","difficulty":3,"kind":"mc","stem":"사서 선생님이 「늦게 온 책을 다시 정리하는 데 시간이 많이 든다」고 하셨어요. 출처를 밝혔어도 잘못 옮긴 것은 어느 것인가요?","options":[{"t":"사서 선생님께서 늦게 온 책 때문에 도서관 일을 할 수 없다고 하셨다","correct":true},{"t":"사서 선생님께서 늦게 온 책을 다시 정리하는 데 시간이 많이 든다고 하셨다","mis":"K6-1-u5-X19"},{"t":"늦게 돌아온 책은 정리에 시간이 많이 든다고 하셨다","mis":"K6-1-u5-X19"},{"t":"사서 선생님 말씀으로는 늦은 책 정리에 시간이 많이 든다","mis":"K6-1-u5-X19"}],"explanation":["뜻 그대로예요.","뜻 그대로예요.","「많이 든다」를 「할 수 없다」로 과장했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#19','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C27',3,'mc','auto','「급식실을 더 좋게 만듭시다」를 명료한 주장으로 고친 것은 어느 것인가요?',ARRAY['K6-1-u5-X27','K6-1-u5-X02']::text[],false,'{"seq":19,"concept":"K6-1-u5-C27","difficulty":3,"kind":"mc","stem":"「급식실을 더 좋게 만듭시다」를 명료한 주장으로 고친 것은 어느 것인가요?","options":[{"t":"급식실 앞에서는 한 줄로 섭시다","correct":true},{"t":"급식실을 아름답게 꾸밉시다","mis":"K6-1-u5-X27"},{"t":"급식실에 대해 생각해 봅시다","mis":"K6-1-u5-X27"},{"t":"급식실 문제가 많습니다","mis":"K6-1-u5-X02"}],"explanation":["주장이 다른 쪽으로 바뀌었어요.","무엇을 하자는지 흐려요.","문제 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#20','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C43',3,'error','auto','우재의 점검 질문이에요. 단계와 질문이 어긋난 것은 누구의 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":20,"concept":"K6-1-u5-C43","difficulty":3,"kind":"error","stem":"우재의 점검 질문이에요. 단계와 질문이 어긋난 것은 누구의 것인가요?","options":[{"t":"하영 — 내용 생성하기: 「띄어쓰기가 틀리지 않았나요?」","correct":true,"mis_target":"K6-1-u5-X39"},{"t":"우재 — 계획하기: 「읽을 사람이 누구인지 정했나요?」","mis":"K6-1-u5-X39"},{"t":"민찬 — 내용 조직하기: 「주장 · 이유 · 근거가 짜임에 맞게 놓였나요?」","mis":"K6-1-u5-X39"}],"explanation":["우재는 바르게 붙였어요.","민찬도 바르게 붙였어요.","띄어쓰기는 내용 생성하기 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#21','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C45',3,'mc','auto','우재 초고의 고칠 곳 가운데 글 수준에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C45","difficulty":3,"kind":"mc","stem":"우재 초고의 고칠 곳 가운데 글 수준에 해당하는 것은 어느 것인가요?","options":[{"t":"주제와 이어지지 않는 「급식실 반찬」 문장이 섞여 글 전체의 통일성이 흐려졌다","correct":true},{"t":"「한줄로」를 「한 줄로」로 띄어 써야 한다","mis":"K6-1-u5-X41"},{"t":"④문단에 문장 하나를 보태야 한다","mis":"K6-1-u5-X41"},{"t":"「이기적인」이라는 낱말 하나만 바꾼다","mis":"K6-1-u5-X41"}],"explanation":["띄어쓰기는 문장과 낱말 수준이에요.","한 문단 안의 일이에요.","주제가 드러나는지는 글 수준이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#22','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C48',3,'mc','auto','「한 줄이면 모두가 먼저」 표어만 붙이고 아래 네 칸 글을 뗐어요. 무엇이 약해지나요?',ARRAY['K6-1-u5-X44','K6-1-u5-X47']::text[],false,'{"seq":22,"concept":"K6-1-u5-C48","difficulty":3,"kind":"mc","stem":"「한 줄이면 모두가 먼저」 표어만 붙이고 아래 네 칸 글을 뗐어요. 무엇이 약해지나요?","options":[{"t":"「정말?」이라는 물음에 보여 줄 근거가 사라져 설득의 힘이 약해진다","correct":true},{"t":"글씨가 작아져 설득이 약해진다","mis":"K6-1-u5-X44"},{"t":"표어가 짧아져 주장이 사라진다","mis":"K6-1-u5-X47"},{"t":"약해지는 것이 없다","mis":"K6-1-u5-X44"}],"explanation":["크기 문제가 아니에요.","주장은 표어에 남아 있어요.","근거가 빠졌어요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#23','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',4,'mc','auto','우재 초고 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X40','K6-1-u5-X41']::text[],false,'{"seq":23,"concept":"K6-1-u5-C37","difficulty":4,"kind":"mc","stem":"우재 초고 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"짜임과 이유는 갖추었지만, 통일성을 깨는 문장 · 흐린 출처 · 헐뜯는 말 · 띄어쓰기를 고쳐야 한다","correct":true},{"t":"근거가 셋이니 고칠 곳이 없다","mis":"K6-1-u5-X14"},{"t":"고칠 곳이 많으니 버리고 새로 써야 한다","mis":"K6-1-u5-X40"},{"t":"맞춤법만 고치면 좋은 글이 된다","mis":"K6-1-u5-X41"}],"explanation":["출처가 흐린 근거가 있어요.","버리지 않고 고쳐요.","큰 고침도 필요해요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#24','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C37',4,'essay','teacher','우재 초고 앞부분에서 통일성을 깨는 문장을 찾아 쓰고, 그 문장을 어떻게 할지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C37","difficulty":4,"kind":"essay","stem":"우재 초고 앞부분에서 통일성을 깨는 문장을 찾아 쓰고, 그 문장을 어떻게 할지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「급식실 반찬은 골고루 먹어야 키가 큰다.」가 통일성을 깬다. 이 문장은 옳은 말이지만 「급식실 앞에서는 한 줄로 서자」는 주제와 이어지지 않는다. 그래서 이 문장은 지운다. 주제와 멀어진 내용이 섞이면 읽는 사람이 글쓴이가 무엇을 주장하는지 헷갈리기 때문이다.","scoring_points":["통일성을 깨는 문장을 찾았는가","지우거나 고치는 방법을 썼는가","주제와 이어지지 않는다는 까닭을 썼는가"]},"explanation":["주제를 먼저 잡아요.","주제와 먼 문장을 찾아요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_a#25','kor',6,1,'u5','','g6_1_kor_u5_review_a','unit_review','K6-1-u5-C42',4,'essay','teacher','이 단원의 이름 「자신의 글쓰기 과정을 살펴봐요」가 무엇을 뜻하는지, 쓰기 과정 다섯 단계와 「되돌아감」을 넣어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C42","difficulty":4,"kind":"essay","stem":"이 단원의 이름 「자신의 글쓰기 과정을 살펴봐요」가 무엇을 뜻하는지, 쓰기 과정 다섯 단계와 「되돌아감」을 넣어 설명하세요.","answer_guide":{"answer":"예: 글쓰기는 계획하기 · 내용 생성하기 · 내용 조직하기 · 표현하기 · 고쳐쓰기의 다섯 단계를 지나지만, 한 줄로 곧게 가는 길이 아니다. 쓰다가 근거가 약하면 내용 생성하기로, 읽을 사람이 달라지면 계획하기로 되돌아간다. 이 단원은 완성된 글 한 편보다 내가 어느 단계에서 무엇을 했고 어디로 되돌아갔는지 스스로 살펴보는 법을 배우는 단원이다.","scoring_points":["쓰기 과정 다섯 단계를 썼는가","되돌아감이 정상이라는 점을 썼는가","완성보다 과정을 살펴본다는 뜻을 정리했는가"]},"explanation":["다섯 단계를 떠올려요.","되돌아가는 예를 넣어요.","단원 이름의 뜻을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#1','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C2',1,'mc','auto','「이유를 뒷받침하는 객관적인 자료」를 무엇이라고 하나요?',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"「이유를 뒷받침하는 객관적인 자료」를 무엇이라고 하나요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u5-X03"},{"t":"이유","mis":"K6-1-u5-X03"},{"t":"제목","mis":"K6-1-u5-X03"}],"explanation":["주장은 의견이에요.","이유는 내 까닭이에요.","밖에서 가져온 자료가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#2','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C12',1,'mc','auto','이유와 근거, 그리고 그 출처를 제시하는 부분은 어디인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":2,"concept":"K6-1-u5-C12","difficulty":1,"kind":"mc","stem":"이유와 근거, 그리고 그 출처를 제시하는 부분은 어디인가요?","options":[{"t":"본론","correct":true},{"t":"서론","mis":"K6-1-u5-X10"},{"t":"결론","mis":"K6-1-u5-X10"},{"t":"제목","mis":"K6-1-u5-X10"}],"explanation":["서론은 문제와 주장을 밝혀요.","결론은 요약하고 강조해요.","본론에서 주장을 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#3','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C20',1,'mc','auto','저작물을 만든 사람을 무엇이라고 하나요?',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":3,"concept":"K6-1-u5-C20","difficulty":1,"kind":"mc","stem":"저작물을 만든 사람을 무엇이라고 하나요?","options":[{"t":"저작자","correct":true},{"t":"저작물","mis":"K6-1-u5-X20"},{"t":"저작권","mis":"K6-1-u5-X20"},{"t":"독자","mis":"K6-1-u5-X20"}],"explanation":["저작물은 만든 것이에요.","저작권은 권리예요.","만든 사람은 저작자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#4','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C21',1,'mc','auto','「새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.」에서 「학급 게시판」은 무엇에 해당하나요?',ARRAY['K6-1-u5-X21']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"「새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.」에서 「학급 게시판」은 무엇에 해당하나요?","options":[{"t":"자료가 실린 곳","correct":true},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"},{"t":"자료를 만든 시기","mis":"K6-1-u5-X21"},{"t":"인용한 자료의 이름","mis":"K6-1-u5-X21"}],"explanation":["만든 쪽은 맨 앞이에요.","시기는 괄호 안이에요.","끝은 실린 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#5','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C27',1,'mc','auto','다음 가운데 무엇을 하자는지 한 가지로 읽히는 주장은 어느 것인가요?',ARRAY['K6-1-u5-X27']::text[],false,'{"seq":5,"concept":"K6-1-u5-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 무엇을 하자는지 한 가지로 읽히는 주장은 어느 것인가요?","options":[{"t":"빈 교실을 나올 때 불을 끕시다","correct":true},{"t":"교실을 더 아낍시다","mis":"K6-1-u5-X27"},{"t":"학교를 좋게 만듭시다","mis":"K6-1-u5-X27"},{"t":"모두 노력합시다","mis":"K6-1-u5-X27"}],"explanation":["무엇을 아끼자는지 흐려요.","사람마다 다르게 읽어요.","할 일이 한 가지로 읽혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#6','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C36',1,'mc','auto','쓸 거리를 떠올리고 자료를 모으는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C36","difficulty":1,"kind":"mc","stem":"쓸 거리를 떠올리고 자료를 모으는 단계는 어느 것인가요?","options":[{"t":"내용 생성하기","correct":true},{"t":"계획하기","mis":"K6-1-u5-X37"},{"t":"내용 조직하기","mis":"K6-1-u5-X37"},{"t":"고쳐쓰기","mis":"K6-1-u5-X37"}],"explanation":["계획하기는 정하는 단계예요.","조직하기는 늘어놓아요.","모으는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#7','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C40',1,'ox','auto','점검은 글을 다 쓴 뒤에 한 번만 하는 일이에요.',ARRAY['K6-1-u5-X36']::text[],false,'{"seq":7,"concept":"K6-1-u5-C40","difficulty":1,"kind":"ox","stem":"점검은 글을 다 쓴 뒤에 한 번만 하는 일이에요.","answer":"X","reason_options":[{"t":"쓰는 도중 어느 단계에서나 방향을 다시 잡는 일이기 때문에","correct":true},{"t":"다 쓴 글을 채점하는 일이기 때문에","mis":"K6-1-u5-X36"}],"mis":"K6-1-u5-X36","explanation":["도중에도 해요.","채점이 아니에요.","방향을 다시 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#8','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C52',1,'mc','auto','쌓인 뒤에 아직 아무도 밟지 않은 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"쌓인 뒤에 아직 아무도 밟지 않은 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"숫눈","correct":true},{"t":"도둑눈","mis":"K6-1-u5-X48"},{"t":"가루눈","mis":"K6-1-u5-X48"},{"t":"여우비","mis":"K6-1-u5-X48"}],"explanation":["도둑눈은 모르게 내린 눈이에요.","가루눈은 잘게 내리는 눈이에요.","아무도 밟지 않은 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#9','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',2,'mc','auto','④문단의 「어떤 선생님께서」가 근거로 힘을 잃는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X23','K6-1-u5-X25','K6-1-u5-X24']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"④문단의 「어떤 선생님께서」가 근거로 힘을 잃는 까닭은 어느 것인가요?","options":[{"t":"말한 사람과 여쭌 때가 없어 전문가 의견이 아니라 떠도는 말이 되기 때문이다","correct":true},{"t":"선생님 말씀은 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"문장이 길기 때문이다","mis":"K6-1-u5-X25"},{"t":"선생님이 한 분뿐이기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["면담도 근거가 돼요.","길이 때문이 아니에요.","누구 · 언제가 빠졌어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#10','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C8',2,'match','auto','헌책 글의 이유와 그것을 뒷받침한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u5-C8","difficulty":2,"kind":"match","stem":"헌책 글의 이유와 그것을 뒷받침한 내용을 알맞게 이으세요.","pairs":[{"l":"필요한 사람에게 옮겨 간다","r":"읽지 않는 책을 둔 학생이 많다"},{"l":"종이를 덜 쓰게 된다","r":"스물한 명이 헌책을 받아 본 적이 있다"},{"l":"책 고르는 재미가 생긴다","r":"남의 손을 거친 책을 더 궁금해한다"}],"mis":"K6-1-u5-X03","explanation":["옮겨 감은 쌓인 책과 이어져요.","종이는 헌책 이용과 이어져요.","재미는 궁금함과 이어져요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#11','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C8',2,'mc','auto','우재 초고 ②문단에서 근거에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X02']::text[],false,'{"seq":11,"concept":"K6-1-u5-C8","difficulty":2,"kind":"mc","stem":"우재 초고 ②문단에서 근거에 해당하는 것은 어느 것인가요?","options":[{"t":"스물네 명 가운데 열다섯 명이 밀린 적이 있다는 설문 결과","correct":true},{"t":"한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다","mis":"K6-1-u5-X03"},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X02"},{"t":"줄이 두세 갈래로 엉킨다","mis":"K6-1-u5-X02"}],"explanation":["「때문이다」는 이유예요.","주장이에요.","출처가 붙은 조사 결과예요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#12','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',2,'mc','auto','우재 초고 ③문단의 근거를 고쳐야 하는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X03','K6-1-u5-X25','K6-1-u5-X10']::text[],false,'{"seq":12,"concept":"K6-1-u5-C51","difficulty":2,"kind":"mc","stem":"우재 초고 ③문단의 근거를 고쳐야 하는 까닭은 어느 것인가요?","options":[{"t":"「어떤 조사에 따르면」이라 누가 · 언제 한 조사인지 확인할 수 없기 때문이다","correct":true},{"t":"조사 결과는 이유가 되기 때문이다","mis":"K6-1-u5-X03"},{"t":"문장이 두 줄이라 짧기 때문이다","mis":"K6-1-u5-X25"},{"t":"「둘째」라는 말이 있기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["조사 결과는 근거예요.","길이 문제가 아니에요.","출처가 흐려 확인할 수 없어요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#13','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C25',2,'mc','auto','우재 초고 뒷부분에서 쓰기 윤리에 어긋난 문장은 어느 것인가요?',ARRAY['K6-1-u5-X25']::text[],false,'{"seq":13,"concept":"K6-1-u5-C25","difficulty":2,"kind":"mc","stem":"우재 초고 뒷부분에서 쓰기 윤리에 어긋난 문장은 어느 것인가요?","options":[{"t":"줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다","correct":true},{"t":"한 줄로 서는 일은 어렵지 않다","mis":"K6-1-u5-X25"},{"t":"지금까지 세 가지 까닭을 살펴보았다","mis":"K6-1-u5-X25"},{"t":"모두가 편안한 점심시간을 만들자","mis":"K6-1-u5-X25"}],"explanation":["사실을 말한 문장이에요.","요약하는 문장이에요.","다른 사람을 헐뜯는 말이에요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#14','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C34',2,'mc','auto','우재가 「동생들도 읽을 텐데」라고 한 것은 어느 단계를 다시 살핀 것인가요?',ARRAY['K6-1-u5-X39']::text[],false,'{"seq":14,"concept":"K6-1-u5-C34","difficulty":2,"kind":"mc","stem":"우재가 「동생들도 읽을 텐데」라고 한 것은 어느 단계를 다시 살핀 것인가요?","options":[{"t":"계획하기 — 글을 읽을 사람","correct":true},{"t":"내용 조직하기 — 짜임","mis":"K6-1-u5-X39"},{"t":"고쳐쓰기 — 맞춤법","mis":"K6-1-u5-X39"},{"t":"내용 생성하기 — 자료","mis":"K6-1-u5-X39"}],"explanation":["짜임 이야기가 아니에요.","맞춤법 이야기가 아니에요.","읽을 사람을 다시 보는 것은 계획하기예요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#15','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C48',2,'ox','auto','하영이의 표어는 근거 없이 눈에 띄는 말만 내세웠어요.',ARRAY['K6-1-u5-X44']::text[],false,'{"seq":15,"concept":"K6-1-u5-C48","difficulty":2,"kind":"ox","stem":"하영이의 표어는 근거 없이 눈에 띄는 말만 내세웠어요.","answer":"X","reason_options":[{"t":"표어 아래에 네 칸 글로 까닭과 사례를 붙여 근거를 남겼기 때문에","correct":true},{"t":"표어는 근거가 없어도 설득되기 때문에","mis":"K6-1-u5-X44"}],"mis":"K6-1-u5-X44","explanation":["표어만 있는 게 아니에요.","사례가 있어요.","근거 하나를 남겼어요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#16','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C52',2,'mc','auto','「먼지잼」이 어울리는 날은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"「먼지잼」이 어울리는 날은 어느 것인가요?","options":[{"t":"먼지나 겨우 가라앉힐 만큼 비가 아주 조금 내린 날","correct":true},{"t":"밤새도록 비가 내린 날","mis":"K6-1-u5-X48"},{"t":"볕이 쨍한데 잠깐 비가 온 날","mis":"K6-1-u5-X48"},{"t":"가루처럼 잘게 눈이 내린 날","mis":"K6-1-u5-X48"}],"explanation":["밤에 내리는 비는 밤비예요.","그것은 여우비예요.","아주 조금 온 비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#17','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C10',3,'mc','auto','근거의 타당성을 묻는 세 물음을 모두 넘긴 근거는 어느 것인가요? (이유: 물기 때문에 복도가 미끄럽다)',ARRAY['K6-1-u5-X09','K6-1-u5-X23','K6-1-u5-X14']::text[],false,'{"seq":17,"concept":"K6-1-u5-C10","difficulty":3,"kind":"mc","stem":"근거의 타당성을 묻는 세 물음을 모두 넘긴 근거는 어느 것인가요? (이유: 물기 때문에 복도가 미끄럽다)","options":[{"t":"비 온 날 복도에 물이 고인 곳을 사흘 동안 센 기록과 그 출처","correct":true},{"t":"비 오는 날은 기분이 처진다는 내 느낌","mis":"K6-1-u5-X09"},{"t":"누가 썼는지 모르는 누리집 글","mis":"K6-1-u5-X23"},{"t":"출처를 갖춘 우리 반 급식 잔반 기록","mis":"K6-1-u5-X14"}],"explanation":["느낌은 객관적이지 않아요.","출처를 믿기 어려워요.","이유와 이어지고 · 믿을 수 있고 · 객관적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#18','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C17',3,'mc','auto','내 글에 표절이 없는지 확인하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X17']::text[],false,'{"seq":18,"concept":"K6-1-u5-C17","difficulty":3,"kind":"mc","stem":"내 글에 표절이 없는지 확인하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남에게서 가져온 문장 · 표 · 자료마다 출처를 붙였는지 하나씩 짚어 본다","correct":true},{"t":"글이 다른 글보다 긴지 본다","mis":"K6-1-u5-X25"},{"t":"어려운 낱말이 많은지 본다","mis":"K6-1-u5-X25"},{"t":"여러 글에서 가져온 조각이면 괜찮다고 여긴다","mis":"K6-1-u5-X17"}],"explanation":["길이와 관계없어요.","어려운 낱말과 관계없어요.","조각도 표절이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#19','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C31',3,'mc','auto','우재의 주장에 「한 줄로 서면 줄이 너무 길어져 복도를 막아요」라는 반박이 나왔어요. 가장 알맞은 대처는 어느 것인가요?',ARRAY['K6-1-u5-X28','K6-1-u5-X27','K6-1-u5-X25']::text[],false,'{"seq":19,"concept":"K6-1-u5-C31","difficulty":3,"kind":"mc","stem":"우재의 주장에 「한 줄로 서면 줄이 너무 길어져 복도를 막아요」라는 반박이 나왔어요. 가장 알맞은 대처는 어느 것인가요?","options":[{"t":"맞는 걱정이니 「벽을 따라 한 줄로 서자」는 내용을 보탠다","correct":true},{"t":"반박을 못 들은 척한다","mis":"K6-1-u5-X28"},{"t":"주장을 「모두 노력합시다」로 바꾼다","mis":"K6-1-u5-X27"},{"t":"반박한 친구를 이기적이라고 쓴다","mis":"K6-1-u5-X25"}],"explanation":["그 자리에서 무너져요.","주장이 흐려져요.","헐뜯으면 쓰기 윤리에 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#20','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C41',3,'mc','auto','「점심시간 급식실 앞 → 한 줄 서기」를 정한 뒤 「설문 · 면담」을 모은 우재가 다음에 할 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":20,"concept":"K6-1-u5-C41","difficulty":3,"kind":"mc","stem":"「점심시간 급식실 앞 → 한 줄 서기」를 정한 뒤 「설문 · 면담」을 모은 우재가 다음에 할 단계는 어느 것인가요?","options":[{"t":"내용 조직하기 — 서론 · 본론 · 결론에 나누어 개요를 짠다","correct":true},{"t":"고쳐쓰기 — 맞춤법을 고친다","mis":"K6-1-u5-X37"},{"t":"계획하기 — 목적을 처음 정한다","mis":"K6-1-u5-X37"},{"t":"표현하기 없이 바로 끝낸다","mis":"K6-1-u5-X37"}],"explanation":["아직 쓴 글이 없어요.","계획은 이미 세웠어요.","모은 것을 늘어놓을 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#21','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C46',3,'mc','auto','「안돼요」와 「안 돼요」 가운데 바른 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X42']::text[],false,'{"seq":21,"concept":"K6-1-u5-C46","difficulty":3,"kind":"mc","stem":"「안돼요」와 「안 돼요」 가운데 바른 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「안 돼요」 — 「안」과 「돼요」를 띄어 쓰기 때문이다","correct":true},{"t":"「안돼요」 — 소리 나는 대로 붙여 쓰기 때문이다","mis":"K6-1-u5-X42"},{"t":"둘 다 맞다 — 띄어쓰기는 뜻과 관계없기 때문이다","mis":"K6-1-u5-X42"},{"t":"「안 되요」 — 「되」로 써야 하기 때문이다","mis":"K6-1-u5-X42"}],"explanation":["붙여 쓰지 않아요.","띄어쓰기도 민감하게 살펴요.","「돼요」가 바른 맞춤법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#22','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C47',3,'mc','auto','하영이가 처음 「급식 시간을 늘립시다」로 실천 주장을 세웠다가 바꾼 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X24','K6-1-u5-X34']::text[],false,'{"seq":22,"concept":"K6-1-u5-C47","difficulty":3,"kind":"mc","stem":"하영이가 처음 「급식 시간을 늘립시다」로 실천 주장을 세웠다가 바꾼 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"급식 시간은 학생이 정할 수 없어, 우리가 바꿀 수 있는 「한 줄로 서기」로 바꾸었다","correct":true},{"t":"주장이 너무 짧아서","mis":"K6-1-u5-X47"},{"t":"근거가 너무 많아서","mis":"K6-1-u5-X24"},{"t":"읽을 사람이 정해져 있지 않아서","mis":"K6-1-u5-X34"}],"explanation":["짧아서가 아니에요.","근거 수 문제가 아니에요.","우리 힘으로 바꿀 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#23','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',4,'mc','auto','우재가 ③문단 근거를 고친 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X47','K6-1-u5-X19','K6-1-u5-X21']::text[],false,'{"seq":23,"concept":"K6-1-u5-C51","difficulty":4,"kind":"mc","stem":"우재가 ③문단 근거를 고친 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「일주일 동안 줄이 엉킨 날 늦게 온 사람이 먼저 들어간 횟수를 세어 보니 … (새솔반(2026), 「급식실 앞 관찰 기록」, 학급 게시판.)」","correct":true},{"t":"「많은 사람들이 그렇다고 한다.」","mis":"K6-1-u5-X47"},{"t":"「어떤 조사에 따르면 아주아주 많다고 한다.」","mis":"K6-1-u5-X19"},{"t":"「누리집에서 봤는데 정말 그렇다.」","mis":"K6-1-u5-X21"}],"explanation":["누가 말했는지 몰라요.","흐린 출처에 과장까지 했어요.","어느 누리집인지 확인할 수 없어요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#24','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C51',4,'essay','teacher','「헌책 나눔 상자」 글에서 출처가 흐린 곳 두 군데를 찾아 쓰고, 그중 하나를 학생이 직접 만들 수 있는 근거로 바꾸어 출처를 네 가지를 갖추어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C51","difficulty":4,"kind":"essay","stem":"「헌책 나눔 상자」 글에서 출처가 흐린 곳 두 군데를 찾아 쓰고, 그중 하나를 학생이 직접 만들 수 있는 근거로 바꾸어 출처를 네 가지를 갖추어 쓰세요.","answer_guide":{"answer":"예: 출처가 흐린 곳은 ②문단의 「어떤 조사에 따르면」과 ④문단의 「어떤 선생님께서」이다. ②문단을 바꾸면 — 우리 반 스물다섯 명에게 물어보니 열아홉 명이 집에 읽지 않는 책이 다섯 권 넘게 있다고 답했다. (솔바람반(2026), 「집에 있는 읽지 않는 책 설문」, 학급 게시판.)","scoring_points":["흐린 곳 두 군데를 찾았는가","학생이 직접 만들 수 있는 근거로 바꾸었는가","출처를 네 가지를 갖추어 적었는가"]},"explanation":["누가 · 언제가 빠진 곳을 찾아요.","직접 세거나 물을 수 있는 자료로 바꿔요.","네 칸을 채워요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_b#25','kor',6,1,'u5','','g6_1_kor_u5_review_b','unit_review','K6-1-u5-C10',4,'essay','teacher','좋은 근거가 갖추어야 할 것을 세 가지 쓰고, 그 가운데 출처가 왜 중요한지 「확인」이라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C10","difficulty":4,"kind":"essay","stem":"좋은 근거가 갖추어야 할 것을 세 가지 쓰고, 그 가운데 출처가 왜 중요한지 「확인」이라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: 좋은 근거는 첫째, 이유와 관련이 있어야 하고, 둘째, 출처를 믿을 수 있어야 하며, 셋째, 느낌이나 짐작이 아닌 객관적인 자료여야 한다. 출처가 중요한 까닭은 만든 사람 · 시기 · 자료의 이름 · 실린 곳이 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있기 때문이다. 확인할 수 없으면 근거가 아니라 짐작이 된다.","scoring_points":["근거가 갖출 것 세 가지를 썼는가","출처의 네 가지를 썼는가","확인할 수 있어야 근거라는 점을 썼는가"]},"explanation":["세 물음을 떠올려요.","출처 네 칸을 떠올려요.","확인과 이어 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#1','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C7',1,'ox','auto','「∼하기 때문이다」로 이어지는 내 까닭은 이유예요.',ARRAY['K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C7","difficulty":1,"kind":"ox","stem":"「∼하기 때문이다」로 이어지는 내 까닭은 이유예요.","answer":"O","reason_options":[{"t":"이유는 그렇게 주장하는 주관적인 까닭이기 때문에","correct":true},{"t":"밖에서 가져와 출처를 붙인 자료이기 때문에","mis":"K6-1-u5-X03"}],"mis":"K6-1-u5-X03","explanation":["내 까닭이에요.","출처를 붙이는 것은 근거예요.","이유와 근거를 섞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#2','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C13',1,'ox','auto','결론에서는 처음 꺼내는 새로운 근거를 내놓아요.',ARRAY['K6-1-u5-X11']::text[],false,'{"seq":2,"concept":"K6-1-u5-C13","difficulty":1,"kind":"ox","stem":"결론에서는 처음 꺼내는 새로운 근거를 내놓아요.","answer":"X","reason_options":[{"t":"결론은 주장한 내용을 요약하고 다시 한번 강조하는 부분이기 때문에","correct":true},{"t":"마지막에 가장 센 새 근거를 두어야 하기 때문에","mis":"K6-1-u5-X11"}],"mis":"K6-1-u5-X11","explanation":["새 근거는 본론에 둬요.","결론은 모으는 부분이에요.","다시 한번 힘주어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#3','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C18',1,'ox','auto','출처를 밝히는 일은 해도 되고 안 해도 되는 예의예요.',ARRAY['K6-1-u5-X18']::text[],false,'{"seq":3,"concept":"K6-1-u5-C18","difficulty":1,"kind":"ox","stem":"출처를 밝히는 일은 해도 되고 안 해도 되는 예의예요.","answer":"X","reason_options":[{"t":"만든 사람의 권리를 지키기 위해 꼭 지켜야 할 약속이기 때문에","correct":true},{"t":"읽는 사람이 원할 때만 밝히면 되기 때문에","mis":"K6-1-u5-X18"}],"mis":"K6-1-u5-X18","explanation":["예의가 아니에요.","약속이에요.","권리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#4','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C21',1,'mc','auto','같은 출처에서 「2026」은 무엇에 해당하나요?',ARRAY['K6-1-u5-X21','K6-1-u5-X22']::text[],false,'{"seq":4,"concept":"K6-1-u5-C21","difficulty":1,"kind":"mc","stem":"같은 출처에서 「2026」은 무엇에 해당하나요?","options":[{"t":"자료를 만든 시기","correct":true},{"t":"자료가 실린 곳","mis":"K6-1-u5-X21"},{"t":"자료를 만든 사람","mis":"K6-1-u5-X21"},{"t":"자료의 쪽수","mis":"K6-1-u5-X22"}],"explanation":["실린 곳은 끝에 적어요.","만든 쪽은 맨 앞이에요.","괄호 안 숫자는 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#5','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C23',1,'mc','auto','근거로 쓰기에 믿을 만한 자료는 어느 것인가요?',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":5,"concept":"K6-1-u5-C23","difficulty":1,"kind":"mc","stem":"근거로 쓰기에 믿을 만한 자료는 어느 것인가요?","options":[{"t":"언제 · 누구에게 · 어디서 했는지 적어 둔 우리 반 설문","correct":true},{"t":"누가 썼는지 모르는 글","mis":"K6-1-u5-X23"},{"t":"언제 올라온 것인지 모를 자료","mis":"K6-1-u5-X23"},{"t":"친구가 들었다고 한 소문","mis":"K6-1-u5-X23"}],"explanation":["누가 썼는지 몰라요.","언제인지 몰라요.","직접 조사도 출처를 적으면 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#6','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C37',1,'mc','auto','떠올린 내용을 서론 · 본론 · 결론 짜임에 맞게 늘어놓는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C37","difficulty":1,"kind":"mc","stem":"떠올린 내용을 서론 · 본론 · 결론 짜임에 맞게 늘어놓는 단계는 어느 것인가요?","options":[{"t":"내용 조직하기","correct":true},{"t":"내용 생성하기","mis":"K6-1-u5-X37"},{"t":"표현하기","mis":"K6-1-u5-X37"},{"t":"계획하기","mis":"K6-1-u5-X37"}],"explanation":["생성하기는 꺼내 놓아요.","표현하기는 문장으로 써요.","늘어놓는 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#7','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C44',1,'ox','auto','고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이에요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":7,"concept":"K6-1-u5-C44","difficulty":1,"kind":"ox","stem":"고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이에요.","answer":"O","reason_options":[{"t":"점검은 흠 잡기가 아니라 나아지기 위한 조정이기 때문에","correct":true},{"t":"고칠 곳이 많으면 망한 글이기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["찾아낸 만큼 나아져요.","흠 잡기가 아니에요.","과정을 보는 단원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#8','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C47',1,'mc','auto','우리 힘으로 바꿀 수 있어 실천 활동으로 알맞은 문제는 어느 것인가요?',ARRAY['K6-1-u5-X43']::text[],false,'{"seq":8,"concept":"K6-1-u5-C47","difficulty":1,"kind":"mc","stem":"우리 힘으로 바꿀 수 있어 실천 활동으로 알맞은 문제는 어느 것인가요?","options":[{"t":"특별실을 쓰고 뒷정리를 하지 않고 나간다","correct":true},{"t":"겨울이 너무 춥다","mis":"K6-1-u5-X43"},{"t":"해가 너무 일찍 진다","mis":"K6-1-u5-X43"},{"t":"바다가 너무 멀다","mis":"K6-1-u5-X43"}],"explanation":["날씨는 바꿀 수 없어요.","해 지는 시각도 바꿀 수 없어요.","우리가 바꿀 수 있는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#9','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C51',2,'ox','auto','「어떤 조사에 따르면」처럼 쓰면 읽는 사람이 그 조사를 찾아가 확인할 수 있어요.',ARRAY['K6-1-u5-X47']::text[],false,'{"seq":9,"concept":"K6-1-u5-C51","difficulty":2,"kind":"ox","stem":"「어떤 조사에 따르면」처럼 쓰면 읽는 사람이 그 조사를 찾아가 확인할 수 있어요.","answer":"X","reason_options":[{"t":"누가 · 언제 · 무엇을 · 어디에 실었는지가 모두 빠져 있기 때문에","correct":true},{"t":"「조사」라는 말이 들어 있으니 출처를 밝힌 것이기 때문에","mis":"K6-1-u5-X47"}],"mis":"K6-1-u5-X47","explanation":["네 가지가 모두 없어요.","확인할 길이 없어요.","근거가 아니라 짐작이 돼요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#10','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C13',2,'mc','auto','⑤문단 「상자 하나면 된다. … 다시 읽히게 하자.」는 글의 어느 부분인가요?',ARRAY['K6-1-u5-X10','K6-1-u5-X11']::text[],false,'{"seq":10,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"⑤문단 「상자 하나면 된다. … 다시 읽히게 하자.」는 글의 어느 부분인가요?","options":[{"t":"결론 — 주장을 다시 강조한다","correct":true},{"t":"서론 — 문제를 제기한다","mis":"K6-1-u5-X10"},{"t":"본론 — 새 근거를 든다","mis":"K6-1-u5-X11"},{"t":"본론 — 이유를 처음 밝힌다","mis":"K6-1-u5-X10"}],"explanation":["문제 제기는 ①문단이에요.","새 근거가 없어요.","마지막에 다시 힘주어 말해요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#11','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C12',2,'ox','auto','우재 초고 ②문단은 본론으로, 이유와 근거가 함께 놓였어요.',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":11,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"우재 초고 ②문단은 본론으로, 이유와 근거가 함께 놓였어요.","answer":"O","reason_options":[{"t":"「첫째」로 이유를 밝히고 설문 결과와 출처를 붙였기 때문에","correct":true},{"t":"문제를 처음 꺼내고 주장을 밝혔기 때문에","mis":"K6-1-u5-X10"}],"mis":"K6-1-u5-X10","explanation":["첫째로 이유를 갈랐어요.","근거와 출처가 있어요.","문제 제기는 ①문단이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#12','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C33',2,'ox','auto','「급식실 반찬은 골고루 먹어야 키가 큰다」는 옳은 말이니 우재 초고에 그대로 두어도 돼요.',ARRAY['K6-1-u5-X33']::text[],false,'{"seq":12,"concept":"K6-1-u5-C33","difficulty":2,"kind":"ox","stem":"「급식실 반찬은 골고루 먹어야 키가 큰다」는 옳은 말이니 우재 초고에 그대로 두어도 돼요.","answer":"X","reason_options":[{"t":"옳은 말이어도 「한 줄로 서자」는 주제와 이어지지 않아 통일성을 깨기 때문에","correct":true},{"t":"옳은 말은 어느 글에 넣어도 되기 때문에","mis":"K6-1-u5-X33"}],"mis":"K6-1-u5-X33","explanation":["주제를 먼저 봐요.","줄서기와 관계없어요.","걸러 내야 해요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#13','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C12',2,'ox','auto','우재 초고 ④문단의 근거는 이유와 이어지고 출처도 갖추었어요.',ARRAY['K6-1-u5-X23']::text[],false,'{"seq":13,"concept":"K6-1-u5-C12","difficulty":2,"kind":"ox","stem":"우재 초고 ④문단의 근거는 이유와 이어지고 출처도 갖추었어요.","answer":"O","reason_options":[{"t":"선생님의 일이 준다는 이유를 급식 지도 선생님 면담이 받치고 네 가지 출처가 있기 때문에","correct":true},{"t":"선생님 말씀은 근거가 될 수 없기 때문에","mis":"K6-1-u5-X23"}],"mis":"K6-1-u5-X23","explanation":["면담은 근거가 돼요.","이유와 이어져요.","출처 네 가지가 있어요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#14','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C44',2,'ox','auto','하영이는 고칠 곳을 찾은 것을 우재가 볼 줄 알게 된 것으로 받아들였어요.',ARRAY['K6-1-u5-X40']::text[],false,'{"seq":14,"concept":"K6-1-u5-C44","difficulty":2,"kind":"ox","stem":"하영이는 고칠 곳을 찾은 것을 우재가 볼 줄 알게 된 것으로 받아들였어요.","answer":"O","reason_options":[{"t":"점검은 흠을 잡는 일이 아니라 나아지기 위한 조정이기 때문에","correct":true},{"t":"고칠 곳이 있으면 글이 망한 것이기 때문에","mis":"K6-1-u5-X40"}],"mis":"K6-1-u5-X40","explanation":["하영이는 격려했어요.","흠 잡기가 아니에요.","찾아낸 만큼 나아져요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#15','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C49',2,'mc','auto','하영이의 네 칸 글이 서론 · 본론 · 결론과 이어지는 것으로 바른 것은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":15,"concept":"K6-1-u5-C49","difficulty":2,"kind":"mc","stem":"하영이의 네 칸 글이 서론 · 본론 · 결론과 이어지는 것으로 바른 것은 어느 것인가요?","options":[{"t":"의견은 서론, 까닭과 사례는 본론, 제안은 결론에 가깝다","correct":true},{"t":"의견과 까닭은 결론에 가깝다","mis":"K6-1-u5-X45"},{"t":"사례는 서론에 가깝다","mis":"K6-1-u5-X45"},{"t":"제안은 본론에 가깝다","mis":"K6-1-u5-X45"}],"explanation":["의견은 처음 꺼내는 말이에요.","사례는 펼치는 부분이에요.","제안은 다시 힘주는 말이에요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#16','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C52',2,'ox','auto','우리말에는 비와 눈을 언제 · 얼마나 내리느냐에 따라 갈라 부르는 말이 많아요.',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"ox","stem":"우리말에는 비와 눈을 언제 · 얼마나 내리느냐에 따라 갈라 부르는 말이 많아요.","answer":"O","reason_options":[{"t":"여우비 · 먼지잼 · 도둑눈 · 숫눈처럼 이름이 다르기 때문에","correct":true},{"t":"비와 눈은 한 가지 이름으로만 부르기 때문에","mis":"K6-1-u5-X48"}],"mis":"K6-1-u5-X48","explanation":["갈라 부르는 말이 많아요.","사전에 실려 있어요.","언제 · 얼마나에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#17','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C15',3,'error','auto','근거를 판단하고 그 까닭을 말했어요. 판단의 까닭이 알맞지 않은 사람은 누구인가요?',ARRAY['K6-1-u5-X15','K6-1-u5-X14','K6-1-u5-X47']::text[],false,'{"seq":17,"concept":"K6-1-u5-C15","difficulty":3,"kind":"error","stem":"근거를 판단하고 그 까닭을 말했어요. 판단의 까닭이 알맞지 않은 사람은 누구인가요?","options":[{"t":"규리 — 「이 근거는 타당해. 그냥 그럴 것 같거든.」","correct":true,"mis_target":"K6-1-u5-X15"},{"t":"예찬 — 「타당해. 넘어질 뻔한 수를 세어서 안전 이유와 바로 이어지거든.」","mis":"K6-1-u5-X14"},{"t":"민찬 — 「타당하지 않아. 출처가 「어떤 조사」라서 확인할 수 없거든.」","mis":"K6-1-u5-X47"}],"explanation":["예찬은 관련을 까닭으로 들었어요.","민찬은 출처를 까닭으로 들었어요.","「그냥 그럴 것 같아서」는 판단이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#18','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C18',3,'mc','auto','출처를 밝히면 「어디까지가 내 말인지」 읽는 사람이 알 수 있다는 것이 왜 중요한가요?',ARRAY['K6-1-u5-X25','K6-1-u5-X24','K6-1-u5-X18']::text[],false,'{"seq":18,"concept":"K6-1-u5-C18","difficulty":3,"kind":"mc","stem":"출처를 밝히면 「어디까지가 내 말인지」 읽는 사람이 알 수 있다는 것이 왜 중요한가요?","options":[{"t":"글쓴이의 생각과 남에게서 가져온 생각이 갈라져 읽는 사람이 무엇을 확인할지 알기 때문이다","correct":true},{"t":"글이 길어 보여 더 믿음직하기 때문이다","mis":"K6-1-u5-X25"},{"t":"내 생각은 숨기는 것이 좋기 때문이다","mis":"K6-1-u5-X24"},{"t":"출처는 예의라서 상관없기 때문이다","mis":"K6-1-u5-X18"}],"explanation":["길이로 믿음이 생기지 않아요.","내 생각이 중심이에요.","출처는 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#19','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C26',3,'mc','auto','우재가 글을 선생님들께 보여 드리기로 했어요. 무엇을 다시 살피는 것이 알맞은가요?',ARRAY['K6-1-u5-X26','K6-1-u5-X04']::text[],false,'{"seq":19,"concept":"K6-1-u5-C26","difficulty":3,"kind":"mc","stem":"우재가 글을 선생님들께 보여 드리기로 했어요. 무엇을 다시 살피는 것이 알맞은가요?","options":[{"t":"선생님들께 맞는 말투와, 선생님들이 고개를 끄덕일 근거","correct":true},{"t":"「한 줄로 서자」는 주장 자체를 바꾼다","mis":"K6-1-u5-X26"},{"t":"근거를 모두 빼고 주장만 남긴다","mis":"K6-1-u5-X04"},{"t":"누구에게 보이든 그대로 둔다","mis":"K6-1-u5-X26"}],"explanation":["주장은 그대로예요.","근거가 있어야 해요.","대상에 맞게 전하는 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#20','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C43',3,'mc','auto','표현하기 점검에서 「급식 지도」라는 말이 동생들에게 어려운지 살핀 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X35','K6-1-u5-X25']::text[],false,'{"seq":20,"concept":"K6-1-u5-C43","difficulty":3,"kind":"mc","stem":"표현하기 점검에서 「급식 지도」라는 말이 동생들에게 어려운지 살핀 까닭은 어느 것인가요?","options":[{"t":"표현하기 점검의 잣대가 내가 아니라 읽을 사람이기 때문이다","correct":true},{"t":"내가 읽어 매끄러우면 되기 때문이다","mis":"K6-1-u5-X35"},{"t":"어려운 낱말이 많을수록 좋기 때문이다","mis":"K6-1-u5-X25"},{"t":"줄임말은 누구나 알기 때문이다","mis":"K6-1-u5-X35"}],"explanation":["나만 알면 안 돼요.","어려운 낱말이 좋은 게 아니에요.","읽을 사람이 알아들어야 해요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#21','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C41',3,'ox','auto','문단 수준의 고침은 「중심 문장을 뒷받침 문장이 받쳐 주는가」를 살펴 문단 안을 손보는 일이에요.',ARRAY['K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C41","difficulty":3,"kind":"ox","stem":"문단 수준의 고침은 「중심 문장을 뒷받침 문장이 받쳐 주는가」를 살펴 문단 안을 손보는 일이에요.","answer":"O","reason_options":[{"t":"한 문단 안에서 중심 문장과 뒷받침 문장, 문장끼리의 이음을 보는 크기이기 때문에","correct":true},{"t":"글 전체의 주제를 바꾸는 크기이기 때문에","mis":"K6-1-u5-X41"}],"mis":"K6-1-u5-X41","explanation":["한 문단 안의 일이에요.","글 전체는 글 수준이에요.","고침에도 크기가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#22','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C50',3,'mc','auto','일주일 실천을 마친 하영이가 다음 주장을 펼칠 출발선으로 남길 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X25','K6-1-u5-X46']::text[],false,'{"seq":22,"concept":"K6-1-u5-C50","difficulty":3,"kind":"mc","stem":"일주일 실천을 마친 하영이가 다음 주장을 펼칠 출발선으로 남길 것은 어느 것인가요?","options":[{"t":"잘된 점과 아쉬운 점을 한 줄씩 적은 것","correct":true},{"t":"표어를 만든 종이의 색","mis":"K6-1-u5-X44"},{"t":"반대한 친구의 이름","mis":"K6-1-u5-X25"},{"t":"아무것도 남기지 않는다","mis":"K6-1-u5-X46"}],"explanation":["색은 출발선이 아니에요.","남을 겨누지 않아요.","되짚어 적어 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#23','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C42',4,'mc','auto','우재와 하영이의 대화 전체가 보여 주는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X38','K6-1-u5-X36','K6-1-u5-X30']::text[],false,'{"seq":23,"concept":"K6-1-u5-C42","difficulty":4,"kind":"mc","stem":"우재와 하영이의 대화 전체가 보여 주는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기는 점검하며 내용 생성하기와 계획하기로 되돌아가는 과정이고, 그것은 실패가 아니다","correct":true},{"t":"글은 한 번에 끝까지 써야 한다","mis":"K6-1-u5-X38"},{"t":"점검은 다 쓴 뒤에 흠을 세는 일이다","mis":"K6-1-u5-X36"},{"t":"읽을 사람은 쓰기 전에만 정한다","mis":"K6-1-u5-X30"}],"explanation":["한 번에 쓰지 않아도 돼요.","흠 세기가 아니에요.","쓰는 도중에도 다시 정해요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#24','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C46',4,'essay','teacher','우재 초고 뒷부분을 고쳐쓰기 세 수준 가운데 두 수준에서 하나씩 고치고, 무엇을 왜 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C46","difficulty":4,"kind":"essay","stem":"우재 초고 뒷부분을 고쳐쓰기 세 수준 가운데 두 수준에서 하나씩 고치고, 무엇을 왜 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 문장과 낱말 수준 — 「한줄로」를 「한 줄로」로 고쳤다. 「한」과 「줄」은 띄어 써야 하기 때문이다. 글 수준 — 「줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다.」를 지웠다. 다른 사람을 헐뜯는 말이라 쓰기 윤리에 어긋나고, 결론은 주장을 다시 힘주는 부분이기 때문이다.","scoring_points":["두 수준에서 하나씩 고쳤는가","띄어쓰기나 맞춤법을 바르게 고쳤는가","고친 까닭을 썼는가"]},"explanation":["수준을 두 가지 골라요.","고친 곳을 밝혀요.","까닭을 써요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_c#25','kor',6,1,'u5','','g6_1_kor_u5_review_c','unit_review','K6-1-u5-C19',4,'essay','teacher','인용할 때 지켜야 할 두 가지를 쓰고, 둘 가운데 하나만 지키면 왜 안 되는지 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C19","difficulty":4,"kind":"essay","stem":"인용할 때 지켜야 할 두 가지를 쓰고, 둘 가운데 하나만 지키면 왜 안 되는지 예를 들어 설명하세요.","answer_guide":{"answer":"예: 인용할 때에는 출처를 밝히는 일과 뜻을 비틀지 않는 일을 함께 지켜야 한다. 사서 선생님이 「정리에 시간이 많이 든다」고 하셨는데 출처를 붙인 채 「도서관 일을 할 수 없다」고 옮기면, 출처는 지켰지만 만든 사람의 뜻을 과장한 것이다. 반대로 뜻은 그대로 옮겨도 출처를 빼면 표절이 된다. 둘 다 지켜야 만든 사람의 권리를 지킨 것이다.","scoring_points":["출처 밝히기와 뜻 지키기를 썼는가","하나만 지킨 예를 들었는가","저작자의 권리와 이어 정리했는가"]},"explanation":["두 가지를 써요.","하나만 지킨 예를 떠올려요.","권리와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#1','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C2',1,'mc','auto','다음 가운데 주장에 해당하는 문장은 어느 것인가요?',ARRAY['K6-1-u5-X02','K6-1-u5-X03']::text[],false,'{"seq":1,"concept":"K6-1-u5-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 주장에 해당하는 문장은 어느 것인가요?","options":[{"t":"헌책 나눔 상자를 두어 책이 다시 읽히게 하자","correct":true},{"t":"지난해에 보던 책이 쌓인다","mis":"K6-1-u5-X02"},{"t":"종이를 덜 쓰게 되기 때문이다","mis":"K6-1-u5-X03"},{"t":"스물한 명이 헌책을 받아 본 적이 있다고 답했다","mis":"K6-1-u5-X03"}],"explanation":["문제 상황이에요.","이유예요.","하자고 내세운 말이 주장이에요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#2','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C14',1,'mc','auto','문단을 대표하는 한 문장을 무엇이라고 하나요?',ARRAY['K6-1-u5-X13','K6-1-u5-X34']::text[],false,'{"seq":2,"concept":"K6-1-u5-C14","difficulty":1,"kind":"mc","stem":"문단을 대표하는 한 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K6-1-u5-X13"},{"t":"예시 문장","mis":"K6-1-u5-X13"},{"t":"끝맺는 문장","mis":"K6-1-u5-X34"}],"explanation":["뒷받침 문장은 받쳐 줘요.","예시 문장은 예를 들어요.","중심 문장이 문단을 대표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#3','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C17',1,'ox','auto','여러 글에서 한 문장씩 가져와 이어 붙이고 내 글이라고 하는 것도 표절이에요.',ARRAY['K6-1-u5-X17']::text[],false,'{"seq":3,"concept":"K6-1-u5-C17","difficulty":1,"kind":"ox","stem":"여러 글에서 한 문장씩 가져와 이어 붙이고 내 글이라고 하는 것도 표절이에요.","answer":"O","reason_options":[{"t":"남이 쓴 것을 출처 없이 내 것처럼 썼기 때문에","correct":true},{"t":"한 글에서 통째로 가져온 것만 표절이기 때문에","mis":"K6-1-u5-X17"}],"mis":"K6-1-u5-X17","explanation":["조각도 남의 것이에요.","출처가 없어요.","조각 이어 붙이기도 표절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#4','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C22',1,'ox','auto','출처를 적는 차례와 부호는 조금씩 달라도 네 가지가 빠지지 않으면 돼요.',ARRAY['K6-1-u5-X22']::text[],false,'{"seq":4,"concept":"K6-1-u5-C22","difficulty":1,"kind":"ox","stem":"출처를 적는 차례와 부호는 조금씩 달라도 네 가지가 빠지지 않으면 돼요.","answer":"O","reason_options":[{"t":"중요한 것은 네 가지를 빠짐없이 갖추는 것이기 때문에","correct":true},{"t":"차례가 하나라도 다르면 틀린 출처이기 때문에","mis":"K6-1-u5-X22"}],"mis":"K6-1-u5-X22","explanation":["차례는 다를 수 있어요.","네 가지가 핵심이에요.","빠짐이 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#5','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C24',1,'mc','auto','많이 인용할수록 좋은 글이 되지 않는 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X18','K6-1-u5-X23','K6-1-u5-X24']::text[],false,'{"seq":5,"concept":"K6-1-u5-C24","difficulty":1,"kind":"mc","stem":"많이 인용할수록 좋은 글이 되지 않는 까닭은 어느 것인가요?","options":[{"t":"글에 담아야 할 글쓴이의 생각이 남지 않기 때문이다","correct":true},{"t":"출처를 적기 귀찮기 때문이다","mis":"K6-1-u5-X18"},{"t":"자료는 근거가 될 수 없기 때문이다","mis":"K6-1-u5-X23"},{"t":"글이 짧아지기 때문이다","mis":"K6-1-u5-X24"}],"explanation":["귀찮음의 문제가 아니에요.","자료는 근거가 돼요.","내 생각이 중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#6','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C39',1,'mc','auto','조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 단계는 어느 것인가요?',ARRAY['K6-1-u5-X37']::text[],false,'{"seq":6,"concept":"K6-1-u5-C39","difficulty":1,"kind":"mc","stem":"조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 단계는 어느 것인가요?","options":[{"t":"표현하기","correct":true},{"t":"내용 조직하기","mis":"K6-1-u5-X37"},{"t":"계획하기","mis":"K6-1-u5-X37"},{"t":"내용 생성하기","mis":"K6-1-u5-X37"}],"explanation":["조직하기는 낱말과 어구로도 돼요.","계획하기는 정해요.","문장을 써 내려가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#7','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C35',1,'ox','auto','쓰다가 읽을 사람이 달라져야 함을 알면 계획하기로 돌아가도 돼요.',ARRAY['K6-1-u5-X30']::text[],false,'{"seq":7,"concept":"K6-1-u5-C35","difficulty":1,"kind":"ox","stem":"쓰다가 읽을 사람이 달라져야 함을 알면 계획하기로 돌아가도 돼요.","answer":"O","reason_options":[{"t":"계획하기는 글을 쓰기 전에만 거치는 단계가 아니기 때문에","correct":true},{"t":"계획은 한 번 세우면 바꿀 수 없기 때문에","mis":"K6-1-u5-X30"}],"mis":"K6-1-u5-X30","explanation":["쓰는 도중에도 계획을 고쳐요.","어긋난 계획을 붙들지 않아요.","언제든 돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#8','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C52',1,'mc','auto','가루처럼 잘게 내리는 눈을 가리키는 우리말은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":8,"concept":"K6-1-u5-C52","difficulty":1,"kind":"mc","stem":"가루처럼 잘게 내리는 눈을 가리키는 우리말은 어느 것인가요?","options":[{"t":"가루눈","correct":true},{"t":"숫눈","mis":"K6-1-u5-X48"},{"t":"먼지잼","mis":"K6-1-u5-X48"},{"t":"밤비","mis":"K6-1-u5-X48"}],"explanation":["숫눈은 밟지 않은 눈이에요.","먼지잼은 비예요.","가루처럼 내리는 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#9','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C21',2,'mc','auto','③문단의 출처가 믿을 만한 까닭은 어느 것인가요?',ARRAY['K6-1-u5-X14','K6-1-u5-X21','K6-1-u5-X15']::text[],false,'{"seq":9,"concept":"K6-1-u5-C21","difficulty":2,"kind":"mc","stem":"③문단의 출처가 믿을 만한 까닭은 어느 것인가요?","options":[{"t":"만든 사람 · 시기 · 자료의 이름 · 실린 곳이 모두 있어 찾아가 확인할 수 있기 때문이다","correct":true},{"t":"숫자가 들어 있기 때문이다","mis":"K6-1-u5-X14"},{"t":"문단의 가운데에 있기 때문이다","mis":"K6-1-u5-X21"},{"t":"내 생각과 같기 때문이다","mis":"K6-1-u5-X15"}],"explanation":["수가 있다고 믿을 만한 것은 아니에요.","놓인 곳은 관계없어요.","네 가지를 갖췄어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#10','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C11',2,'mc','auto','①문단이 서론인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X10']::text[],false,'{"seq":10,"concept":"K6-1-u5-C11","difficulty":2,"kind":"mc","stem":"①문단이 서론인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책이 쌓이는 문제를 꺼내고 나눔 상자를 두자는 주장을 밝혔기 때문이다","correct":true},{"t":"세 가지 까닭을 모아 말했기 때문이다","mis":"K6-1-u5-X10"},{"t":"이유마다 근거를 붙였기 때문이다","mis":"K6-1-u5-X10"},{"t":"처음 꺼내는 근거가 많기 때문이다","mis":"K6-1-u5-X10"}],"explanation":["모아 말하는 것은 결론이에요.","이유와 근거는 본론이에요.","문제와 주장을 밝혔어요."],"asset":{"type":"passage","lines":["① 학년이 올라가면 지난해에 보던 책이 쌓인다. 현관에 헌책 나눔 상자를 두면 좋겠다.","② 첫째, 책이 필요한 사람에게 옮겨 가기 때문이다. 어떤 조사에 따르면,","집에 읽지 않는 책을 여러 권 두고 있는 학생이 많다고 한다.","③ 둘째, 종이를 덜 쓰게 되기 때문이다. 우리 반 스물다섯 명 가운데 스물한 명이","헌책을 받아 본 적이 있다고 답했다. (솔바람반(2026), 「헌책 이용 설문」, 학급 게시판.)","④ 셋째, 책을 고르는 재미가 생기기 때문이다. 어떤 선생님께서","남의 손을 거친 책을 아이들이 더 궁금해한다고 하셨다.","⑤ 상자 하나면 된다. 헌책 나눔 상자를 두어 책이 다시 읽히게 하자."],"title":"「헌책 나눔 상자를 두면 좋겠습니다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#11','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C14',2,'mc','auto','우재 초고 ②문단의 중심 문장은 어느 것인가요?',ARRAY['K6-1-u5-X13','K6-1-u5-X10']::text[],false,'{"seq":11,"concept":"K6-1-u5-C14","difficulty":2,"kind":"mc","stem":"우재 초고 ②문단의 중심 문장은 어느 것인가요?","options":[{"t":"첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다","correct":true},{"t":"우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했다","mis":"K6-1-u5-X13"},{"t":"새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판","mis":"K6-1-u5-X13"},{"t":"급식실 앞에서는 한 줄로 서야 한다","mis":"K6-1-u5-X10"}],"explanation":["조사 결과는 뒷받침 문장이에요.","출처는 근거에 붙은 것이에요.","문단을 대표하는 문장이에요."],"asset":{"type":"passage","lines":["① 점심시간 급식실 앞은 늘 북적인다. 줄이 두세 갈래로 엉켜 서로 밀치기도 한다.","급식실 앞에서는 한 줄로 서야 한다.","② 첫째, 한 줄로 서면 밀치다 넘어질 일이 줄기 때문이다. 우리 반 스물네 명","가운데 열다섯 명이 급식실 앞에서 밀린 적이 있다고 답했다.","(새솔반(2026), 「급식실 앞 줄서기 설문」, 학급 게시판.)","③ 둘째, 먼저 온 사람이 먼저 먹을 수 있기 때문이다. 어떤 조사에 따르면","줄이 엉키면 늦게 온 사람이 먼저 들어가는 일이 많다고 한다.","급식실 반찬은 골고루 먹어야 키가 큰다."],"title":"우재의 초고 「급식실 앞에서는 한 줄로 섭시다」 — 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#12','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C36',2,'mc','auto','우재가 ③문단 근거를 고치려고 할 때 돌아갈 쓰기 단계는 어느 것인가요?',ARRAY['K6-1-u5-X41','K6-1-u5-X38','K6-1-u5-X31']::text[],false,'{"seq":12,"concept":"K6-1-u5-C36","difficulty":2,"kind":"mc","stem":"우재가 ③문단 근거를 고치려고 할 때 돌아갈 쓰기 단계는 어느 것인가요?","options":[{"t":"내용 생성하기","correct":true},{"t":"고쳐쓰기만 하면 된다","mis":"K6-1-u5-X41"},{"t":"처음부터 다시 쓴다","mis":"K6-1-u5-X38"},{"t":"표현하기에서 문장만 다듬는다","mis":"K6-1-u5-X31"}],"explanation":["근거를 새로 찾아야 해요.","처음부터가 아니에요.","자료 모으기 단계로 돌아가요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#13','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C13',2,'mc','auto','우재 초고 ⑤문단이 결론으로 하는 일은 어느 것인가요?',ARRAY['K6-1-u5-X11','K6-1-u5-X10']::text[],false,'{"seq":13,"concept":"K6-1-u5-C13","difficulty":2,"kind":"mc","stem":"우재 초고 ⑤문단이 결론으로 하는 일은 어느 것인가요?","options":[{"t":"세 가지 까닭을 모아 말하고 한 줄로 서자는 주장을 다시 강조한다","correct":true},{"t":"처음 꺼내는 근거를 든다","mis":"K6-1-u5-X11"},{"t":"급식실 문제를 처음 제기한다","mis":"K6-1-u5-X10"},{"t":"이유마다 출처를 붙인다","mis":"K6-1-u5-X10"}],"explanation":["새 근거는 두지 않아요.","문제 제기는 서론이에요.","모으고 다시 힘줘요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#14','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C23',2,'mc','auto','하영이가 「우리 반에서 직접 세어 보면 되지」라고 한 근거가 믿을 만해지려면 무엇을 함께 적어야 하나요?',ARRAY['K6-1-u5-X09','K6-1-u5-X23']::text[],false,'{"seq":14,"concept":"K6-1-u5-C23","difficulty":2,"kind":"mc","stem":"하영이가 「우리 반에서 직접 세어 보면 되지」라고 한 근거가 믿을 만해지려면 무엇을 함께 적어야 하나요?","options":[{"t":"언제 · 누구에게 · 어디서 조사했는지와 실린 곳","correct":true},{"t":"세어 본 사람의 느낌","mis":"K6-1-u5-X09"},{"t":"친구들의 짐작","mis":"K6-1-u5-X09"},{"t":"아무것도 적지 않아도 된다","mis":"K6-1-u5-X23"}],"explanation":["느낌은 근거가 아니에요.","짐작도 아니에요.","직접 조사도 출처를 적어요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#15','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C50',2,'mc','auto','하영이가 표어를 붙인 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X46','K6-1-u5-X44','K6-1-u5-X25']::text[],false,'{"seq":15,"concept":"K6-1-u5-C50","difficulty":2,"kind":"mc","stem":"하영이가 표어를 붙인 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내일부터 일주일 동안 자신이 먼저 한 줄로 서고 날마다 지켰는지 표시한다","correct":true},{"t":"표어를 붙였으니 할 일을 다 했다","mis":"K6-1-u5-X46"},{"t":"표어 글씨를 더 크게 다시 쓴다","mis":"K6-1-u5-X44"},{"t":"반대하는 친구의 표어를 뗀다","mis":"K6-1-u5-X25"}],"explanation":["붙이고 끝이 아니에요.","크기가 설득이 아니에요.","남의 것을 떼면 안 돼요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#16','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C52',2,'mc','auto','사전에서 다른 비 이름을 더 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u5-X48']::text[],false,'{"seq":16,"concept":"K6-1-u5-C52","difficulty":2,"kind":"mc","stem":"사전에서 다른 비 이름을 더 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"「비」를 표제어로 잡고 그 아래에 딸린 말을 살핀다","correct":true},{"t":"사전 첫 쪽부터 차례로 넘긴다","mis":"K6-1-u5-X48"},{"t":"짐작한 이름을 그대로 맞다고 여긴다","mis":"K6-1-u5-X48"},{"t":"「여우」를 찾아 동물 뜻만 읽는다","mis":"K6-1-u5-X48"}],"explanation":["처음부터 넘기면 오래 걸려요.","짐작은 확인해야 해요.","「비」를 잡고 딸린 말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#17','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C9',3,'mc','auto','「빈 교실의 불을 끕시다」에 붙이기에 타당하지 않은 이유는 어느 것인가요?',ARRAY['K6-1-u5-X08']::text[],false,'{"seq":17,"concept":"K6-1-u5-C9","difficulty":3,"kind":"mc","stem":"「빈 교실의 불을 끕시다」에 붙이기에 타당하지 않은 이유는 어느 것인가요?","options":[{"t":"교실 벽 색이 칙칙하기 때문이다","correct":true},{"t":"쓰지 않는 전기가 낭비되기 때문이다","mis":"K6-1-u5-X08"},{"t":"켜 둔 선풍기가 뜨거워질 수 있기 때문이다","mis":"K6-1-u5-X08"},{"t":"끄는 사람이 정해져 있지 않아 늘 켜져 있기 때문이다","mis":"K6-1-u5-X08"}],"explanation":["전기 낭비는 이어져요.","안전과 이어져요.","벽 색은 불을 끄는 일과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#18','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C20',3,'mc','auto','친구가 내가 쓴 주장하는 글을 자기 이름으로 학급 신문에 실었어요. 무엇을 지키지 않은 것인가요?',ARRAY['K6-1-u5-X20']::text[],false,'{"seq":18,"concept":"K6-1-u5-C20","difficulty":3,"kind":"mc","stem":"친구가 내가 쓴 주장하는 글을 자기 이름으로 학급 신문에 실었어요. 무엇을 지키지 않은 것인가요?","options":[{"t":"저작자인 나의 저작권","correct":true},{"t":"학급 신문의 편집 규칙","mis":"K6-1-u5-X20"},{"t":"친구의 저작권","mis":"K6-1-u5-X20"},{"t":"지키지 않은 것이 없다","mis":"K6-1-u5-X20"}],"explanation":["신문 규칙 문제만이 아니에요.","글을 쓴 사람은 나예요.","내 글도 저작물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#19','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C32',3,'mc','auto','발표를 글로 쓰기 전에 말로 먼저 해 보면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X46','K6-1-u5-X44','K6-1-u5-X32']::text[],false,'{"seq":19,"concept":"K6-1-u5-C32","difficulty":3,"kind":"mc","stem":"발표를 글로 쓰기 전에 말로 먼저 해 보면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰기 부담을 줄이면서 주장과 근거의 흐름을 먼저 확인할 수 있다","correct":true},{"t":"말로 했으니 글은 쓰지 않아도 된다","mis":"K6-1-u5-X46"},{"t":"목소리를 키우면 근거가 필요 없어진다","mis":"K6-1-u5-X44"},{"t":"출처는 말할 때만 밝힌다","mis":"K6-1-u5-X32"}],"explanation":["글로도 옮겨요.","크기가 아니라 근거예요.","글에도 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#20','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C40',3,'mc','auto','우재가 다 쓴 뒤에야 「어떤 조사에 따르면」을 발견했어요. 쓰는 도중에 점검했다면 무엇이 달랐을까요?',ARRAY['K6-1-u5-X36','K6-1-u5-X06','K6-1-u5-X37']::text[],false,'{"seq":20,"concept":"K6-1-u5-C40","difficulty":3,"kind":"mc","stem":"우재가 다 쓴 뒤에야 「어떤 조사에 따르면」을 발견했어요. 쓰는 도중에 점검했다면 무엇이 달랐을까요?","options":[{"t":"내용 생성하기 단계에서 출처가 흐린 것을 바로 알아차려 그때 자료를 바꿀 수 있었다","correct":true},{"t":"달라질 것이 없다","mis":"K6-1-u5-X36"},{"t":"글이 더 길어졌을 것이다","mis":"K6-1-u5-X06"},{"t":"표현하기 단계를 건너뛸 수 있었다","mis":"K6-1-u5-X37"}],"explanation":["도중 점검은 그때 바로잡게 해요.","길이 문제가 아니에요.","단계를 건너뛰는 게 아니에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"다 썼는데 둘째 이유의 근거가 「어떤 조사에 따르면」이야. 다시 자료를 찾으면 처음부터 다시 하는 거잖아."},{"who":"하영","text":"처음부터가 아니라 내용 생성하기로 잠깐 돌아가는 거야. 우리 반에서 직접 세어 보면 되지."},{"who":"우재","text":"그리고 이 글은 동생들도 읽을 텐데 「급식 지도」 같은 말은 어려울까?"},{"who":"하영","text":"그건 계획하기에서 읽을 사람을 다시 보는 거네. 고칠 곳을 찾았다는 건 네가 볼 줄 알게 됐다는 뜻이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#21','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C44',3,'mc','auto','고칠 곳이 많아 다시 쓰기가 버거운 우재에게 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u5-X40','K6-1-u5-X07','K6-1-u5-X41']::text[],false,'{"seq":21,"concept":"K6-1-u5-C44","difficulty":3,"kind":"mc","stem":"고칠 곳이 많아 다시 쓰기가 버거운 우재에게 알맞은 방법은 어느 것인가요?","options":[{"t":"원래 글 위에 쪽지를 붙여 고칠 말만 얹고, 어디를 왜 고쳤는지 한 줄 적는다","correct":true},{"t":"글을 버리고 다른 주제로 새로 쓴다","mis":"K6-1-u5-X40"},{"t":"고칠 곳이 많으니 아무것도 고치지 않는다","mis":"K6-1-u5-X07"},{"t":"맞춤법 하나만 고치고 나머지는 덮는다","mis":"K6-1-u5-X41"}],"explanation":["버리지 않아도 돼요.","한 군데부터 고쳐요.","큰 고침도 쪽지로 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#22','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C49',3,'mc','auto','「까닭」 칸과 「사례」 칸의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u5-X45']::text[],false,'{"seq":22,"concept":"K6-1-u5-C49","difficulty":3,"kind":"mc","stem":"「까닭」 칸과 「사례」 칸의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭은 왜 그렇게 여기는지 밝히고, 사례는 실제로 있었던 일이나 조사 결과를 든다","correct":true},{"t":"까닭과 사례는 같은 칸이다","mis":"K6-1-u5-X45"},{"t":"사례는 하고 싶은 말을 처음 꺼낸다","mis":"K6-1-u5-X45"},{"t":"까닭은 그러니 이렇게 하자고 마무리한다","mis":"K6-1-u5-X45"}],"explanation":["두 칸은 하는 일이 달라요.","처음 꺼내는 건 의견이에요.","마무리는 제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#23','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C48',4,'mc','auto','하영이의 표어와 네 칸 글을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u5-X44','K6-1-u5-X45','K6-1-u5-X14']::text[],false,'{"seq":23,"concept":"K6-1-u5-C48","difficulty":4,"kind":"mc","stem":"하영이의 표어와 네 칸 글을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"짧은 표어로 눈길을 끌고, 네 칸 짜임으로 까닭과 확인할 수 있는 사례를 남겨 설득력을 갖추었다","correct":true},{"t":"표어가 짧으니 근거는 없어도 된다","mis":"K6-1-u5-X44"},{"t":"네 칸 가운데 제안은 빼도 된다","mis":"K6-1-u5-X45"},{"t":"출처를 밝혔으니 더 볼 것이 없다","mis":"K6-1-u5-X14"}],"explanation":["짧아도 근거는 남겨요.","제안으로 다시 밀어 줘요.","출처가 곧 타당함은 아니에요."],"asset":{"type":"passage","lines":["표어 — 「한 줄이면 모두가 먼저」","의견 — 급식실 앞에서는 한 줄로 섭시다.","까닭 — 엉킨 줄에서는 밀려 넘어질 수 있기 때문입니다.","사례 — 우리 반 스물네 명 가운데 열다섯 명이 밀린 적이 있다고 답했습니다.","제안 — 내일 점심부터 급식실 앞에서는 한 줄로 서 봅시다."],"title":"하영이 만든 표어와 네 칸 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#24','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C31',4,'essay','teacher','우재의 주장 「급식실 앞에서는 한 줄로 섭시다」에 나올 만한 반박을 하나 쓰고, 반박을 받아들여 결론을 어떻게 고칠지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u5-C31","difficulty":4,"kind":"essay","stem":"우재의 주장 「급식실 앞에서는 한 줄로 섭시다」에 나올 만한 반박을 하나 쓰고, 반박을 받아들여 결론을 어떻게 고칠지 쓰세요.","answer_guide":{"answer":"예: 반박 — 「한 줄로 서면 줄이 길어져 복도를 막아 다른 사람이 지나가기 어려워요.」 이 걱정이 맞으므로 결론을 「급식실 앞에서는 벽을 따라 한 줄로 서서 모두가 편안한 점심시간을 만들자.」로 고치겠다. 반박을 미리 받아들이면 주장이 더 단단해진다.","scoring_points":["나올 만한 반박을 썼는가","반박을 받아들여 결론을 고쳤는가","주장이 단단해지는 까닭을 썼는가"]},"explanation":["반대할 사람이 되어 봐요.","받아들일 점을 찾아요.","결론에 보태요."],"asset":{"type":"passage","lines":["④ 셋째, 줄을 정리하시는 선생님의 일이 줄기 때문이다. 급식 지도를 맡으신","선생님께서 엉킨 줄을 푸는 데 점심시간의 많은 부분을 쓰신다고 하셨다.","(최○○ 선생님 면담(2026), 「급식 지도 이야기」, 급식실.)","⑤ 지금까지 세 가지 까닭을 살펴보았다. 한 줄로 서는 일은 어렵지 않다.","급식실 앞에서는 한줄로 서서 모두가 편안한 점심시간을 만들자.","줄을 서지 않고 끼어드는 사람은 정말 이기적인 사람이다."],"title":"우재의 초고 — 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u5_review_d#25','kor',6,1,'u5','','g6_1_kor_u5_review_d','unit_review','K6-1-u5-C47',4,'essay','teacher','우리 학교에서 내가 바꿀 수 있는 문제 하나로 주장을 한 문장으로 세우고, 이유 하나 · 근거 하나(출처 포함)를 쓴 뒤, 말한 대로 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u5-C47","difficulty":4,"kind":"essay","stem":"우리 학교에서 내가 바꿀 수 있는 문제 하나로 주장을 한 문장으로 세우고, 이유 하나 · 근거 하나(출처 포함)를 쓴 뒤, 말한 대로 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 주장 — 다 쓴 미술 도구는 제자리에 돌려놓읍시다. 이유 — 다음 반이 도구를 찾느라 수업 시간이 줄기 때문이다. 근거 — 일주일 동안 미술실에 들어갈 때마다 세어 보니 다섯 번 가운데 세 번은 붓이 흩어져 있었다. (솔바람반(2026), 「미술실 도구 관찰 기록」, 학급 게시판.) 실천 — 일주일 동안 내가 쓴 도구를 돌려놓았는지 날마다 표시하고, 끝나면 달라진 점을 한 줄로 적겠다.","scoring_points":["바꿀 수 있는 문제로 한 문장 주장을 세웠는가","이유와 출처를 갖춘 근거를 썼는가","말한 대로 해 볼 실천 방법을 썼는가"]},"explanation":["우리 힘으로 바꿀 문제를 골라요.","이유와 근거 · 출처를 붙여요.","먼저 해 볼 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
